insert into "questions" ("paperKey", "idx", "chapter", "chapterTitle", "stem", "options", "answer", "explanation") values
('p2', 0, '一', '一般保險產品類別', '1. 一般保險中，健康保險通常會歸類於：', '{"A":"責任保險","B":"人身保險","C":"財產保險","D":"經濟權益保險"}'::jsonb, 'B', '「人身」這個詞是指人的身體，而非「有別於組織的個人」，因此「人身保險」的標的是人的生命、肢體或健康，或醫療費用。'),
('p2', 1, '一', '一般保險產品類別', '2. 一般保險包括以下哪類保險產品？', '{"A":"財產保險","B":"責任保險","C":"人身保險(例如：個人意外保險)","D":"以上所有各項"}'::jsonb, 'D', '一般保險四類保障:包括人身、財產、經濟權益及責任保險。'),
('p2', 2, '一', '一般保險產品類別', '3. 醫療保障是屬於哪類保險類別？', '{"A":"財產保險","B":"人身保險","C":"經濟權益保險","D":"責任保險"}'::jsonb, 'B', '「人身」這個詞是指人的身體，而非「有別於組織的個人」，因此「人身保險」的標的是人的生命、肢體或健康，或醫療費用。'),
('p2', 3, '一', '一般保險產品類別', '4. 一般保險保障範圍分兩類，其中一類是以「全險」作根據，另一種是：', '{"A":"特定壽險作根據","B":"特定危險作根據","C":"指明危險作根據","D":"指明壽險作根據"}'::jsonb, 'C', '一般保險中有許多險種都承保屬於或託管於被保險人（或稱受保人）的財產所遭受的損失或損害。保障類別必屬指明危險(或指明危險) 或「全險」(或「一切險」) 。'),
('p2', 4, '一', '一般保險產品類別', '5. 只對火災，閃電及爆炸造成的損毀提供保障的保障形式是：', '{"A":"全險","B":"第三者保險","C":"除外危險","D":"指明危險"}'::jsonb, 'D', '「只對火災，閃電及爆炸造成的損毀提供保障」意思是指明某種情況底下保單將保障的範圍。'),
('p2', 5, '一', '一般保險產品類別', '6. 如果一份保單說明保障包括火災、閃電及爆炸引起的損失，該類保單可稱為：', '{"A":"指明危險","B":"「全險」","C":"綜合","D":"以上所有各項"}'::jsonb, 'A', '「只對火災，閃電及爆炸造成的損毀提供保障」意思是指明某種情況底下保單將保障的範圍。'),
('p2', 6, '一', '一般保險產品類別', '7. 在大部份的一般保單當中被視為除外責任的基本風險包括：戰爭及', '{"A":"地震風險","B":"颱風風險","C":"核子風險","D":"水災風險"}'::jsonb, 'C', '基本風險基本上是這樣的：其成因並非一個個人甚至一群個人有能力控制的，發生後會對數目龐大的人造成影響，因此往往被設定為標準的保單除外責任。'),
('p2', 7, '一', '一般保險產品類別', '8. 戰爭風險及核子風險是標準除外責任，以下哪項描述是正確的？', '{"A":"是基本風險，一般是不可保的","B":"在願意給付額外保險費後便可保","C":"在「全險」的保障中，是屬於可保的","D":"以上所有各項"}'::jsonb, 'A', '基本風險基本上是這樣的：其成因並非一個個人甚至一群個人有能力控制的，發生後會對數目龐大的人造成影響，因此往往被設定為標準的保單除外責任。'),
('p2', 8, '一', '一般保險產品類別', '9. “全險”保單不大可能保障以下哪項或哪些或成因所導致的損失或損害？', '{"A":"遭一名持械盜賊偷竊","B":"手錶因跌入海中所造成手錶內部的損害","C":"因濕度持續高企造成手錶內部的損害","D":"以上各項皆是"}'::jsonb, 'C', '因濕度持續高企造成手錶內部的損害相對較為不可保情況，原因是可能某手錶的設計並不合適於高濕度的環境中使用，但保險人亦有責任證明有關損失不屬於保障範圍之內。'),
('p2', 9, '一', '一般保險產品類別', '10. 保單1承保「火災、閃電和爆炸」,而保單2則承保「意外損失和損壞」，保單1的保障範圍可以描述為「指明危險」，而保單2的保障範圍則可描述為:', '{"A":"全險","B":"複合保險","C":"不指明危險","D":"非指明危險"}'::jsonb, 'A', '「全險」:只要不在除外責任之列，任何可能的風險所引致的損失或損害都受到這類保單承保。'),
('p2', 10, '一', '一般保險產品類別', '11. 一般保險包括以下哪項或哪些保險產品？', '{"A":"財產保險","B":"危疾附約","C":"長期護理","D":"上述所有各項"}'::jsonb, 'A', '一般保險不包括危疾附約。'),
('p2', 11, '一', '一般保險產品類別', '12. 汽車保險具不同類別，以下那項不屬慣常類別？', '{"A":"出租汽車","B":"私家車","C":"電單車","D":"商用車輪"}'::jsonb, 'A', '汽車保險的三個主要類別：私家車、電單車和商用車輛。'),
('p2', 12, '一', '一般保險產品類別', '13. 保險業中車輛分為不同類別，以下那類不是通常分類', '{"A":"的士","B":"私家車","C":"電單車","D":"商用車輛"}'::jsonb, 'A', '汽車保險的三個主要類別：私家車、電單車和商用車輛。'),
('p2', 13, '一', '一般保險產品類別', '14. 以下哪種汽車保險單，保障範圍包括對受保車輛造成的損失及毀壞？
i. 「法令」
ii. 第三者責任
iii. 第三者責任，火災及盜竊
iv. 綜合', '{"A":"i, ii","B":"i, iii","C":"ii, iii","D":"iii, iv"}'::jsonb, 'D', '第三者責任、火災及盜竊保險保障：保障範圍是純第三者責任保險保障，加上承保受保汽車遭受由火災或盜竊引起的損失或損害的財產保險。同時綜合保險保障：市面上的汽車保險保障中，這是保障範圍最廣闊的一種，包括第三者責任、火災及盜竊保險保障，而受保汽車的保險保障是「全險」的。'),
('p2', 14, '一', '一般保險產品類別', '15. 一輛汽車高速行駛時翻側，全車損壞。但並沒有令到任何生命損傷，請問以下哪類保單可獲賠償？', '{"A":"汽車綜合保單","B":"第三者責任保險","C":"第三者責任、火險、盜竊保險","D":"以上所列各項"}'::jsonb, 'A', '綜合保險保障：市面上的汽車保險保障中，這是保障範圍最廣闊的一種，包括第三者責任、火災及盜竊保險保障，而受保汽車的保險保障是「全險」的。全車損壞既不包括在第三者責任、火災及盜竊保險保障故屬於綜合保險保障。'),
('p2', 15, '一', '一般保險產品類別', '16. 以下哪種汽車保險單，保障範圍最廣泛？', '{"A":"「法令」","B":"第三者責任","C":"第三者責任，火災及盜竊","D":"綜合"}'::jsonb, 'D', '第三者責任、火災及盜竊保險保障：保障範圍是純第三者責任保險保障，加上承保受保汽車遭受由火災或盜竊引起的損失或損害的財產保險。同時綜合保險保障：市面上的汽車保險保障中，這是保障範圍最廣闊的一種，包括第三者責任、火災及盜竊保險保障，而受保汽車的保險保障是「全險」的。'),
('p2', 16, '一', '一般保險產品類別', '17. 在道路意外中，被保險人的乘客遭受損傷，其醫療費用可能包括於下列哪項汽車保險中？', '{"A":"法令","B":"第三者責任、火災、盜竊","C":"綜合","D":"以上所有各項"}'::jsonb, 'C', '法令、第三者責任、火災、盜竊及綜合保險均承擔對司機以外的第三方提供保障。'),
('p2', 17, '一', '一般保險產品類別', '18. 若乘客在交通意外中受傷，以下哪項保險可為被保險人的責任提供保障？', '{"A":"綜合保險","B":"「法定」保險","C":"第三者責任、火災及盜竊保險","D":"以上所有各項"}'::jsonb, 'D', '法令、第三者責任、火災、盜竊及綜合保險均承擔對司機以外的第三方提供保障。'),
('p2', 18, '一', '一般保險產品類別', '19. 我們常提及保險人承保的「第三者」保險，以下那三項是正確的？
i. 它較強制性的「第三者」保險保障廣泛
ii. 它與強制性的「第三者」保險不同
iii. 它包括財產損毀保障
iv. 它並不包括第三者財產保障', '{"A":"i, ii, iii","B":"i, ii, iv","C":"i, iii, iv","D":"ii, iii, iv"}'::jsonb, 'A', '純第三者責任保險保障：保障範圍是任何受保駕駛者（或任何乘客）對第三者造成死亡、受傷或財產損害而應負的法律責任，'),
('p2', 19, '一', '一般保險產品類別', '20. 提供最狹窄保障範圍的汽車保險是：', '{"A":"「法令」","B":"第三者責任","C":"綜合","D":"第三者責任、火、綜合"}'::jsonb, 'A', '「法令」只提供由汽車導致或引起任何人死亡或身體受傷而承擔的法律責任購買保險，僱主責任和合約上的法律責任則除外。'),
('p2', 20, '一', '一般保險產品類別', '21. 某汽車司機只有「法令」保險，並疏忽地令電單車司機發生意外。以下哪些可以向保險公司追討?', '{"A":"自己汽車的損毀","B":"電單車的損毀","C":"電單車司機的受傷","D":"汽車司機的緊急召援醫生現場醫療費用"}'::jsonb, 'C', '「法令」只提供由汽車導致或引起任何人死亡或身體受傷而承擔的法律責任購買保險，僱主責任和合約上的法律責任則除外。'),
('p2', 21, '一', '一般保險產品類別', '22. 在汽車保險中的“第三者”，有時會引起一些混淆，一般保險公司提供的第三者保障是指：', '{"A":"“綜合”保障","B":"法令保險","C":"與《汽車保險(第三者風險)條例》相同","D":"與《汽車保險(第三者風險)條例》有所不同"}'::jsonb, 'D', '《汽車保險(第三者風險)條例》是指「法令」保險保障的範圍，只提供由汽車導致或引起任何人死亡或身體受傷而承擔的法律責任購買保險，而一般保險公司提供的第三者保障指任何受保駕駛者（或任何乘客）對第三者造成死亡、受傷或財產損害而應負的法律責任。'),
('p2', 22, '一', '一般保險產品類別', '23. 在強制性汽車保險中，乘客是指:', '{"A":"載客車輛之下付車資的乘客","B":"不需要是一個付車資的乘客","C":"同時可保(A)及(B)","D":"以上全部都不是正確答案"}'::jsonb, 'B', '乘客是指沒有提供任何利益給予司機而乘坐汽車的人。'),
('p2', 23, '一', '一般保險產品類別', '24. 強制性第三者責任是指：', '{"A":"第三者財產損毀責任","B":"第三者的死亡或身體受傷責任","C":"第三者的財產損毀責任及傷亡責任","D":"十足的第三者財產損毀及傷亡責任"}'::jsonb, 'B', '「第三者」一詞總是有雙重含義。條例中「第三者」風險僅指對死亡、受傷應負的法律責任。'),
('p2', 24, '一', '一般保險產品類別', '25. 汽車保險(第三者風險)條例', '{"A":"是本地汽車保險的起源","B":"由於令到司機需要負責任何死傷，大大增加了汽車保險的需求","C":"是嘗試確保令那些在路面意外的不幸死傷者都有賠償","D":"是香港法例唯一的強制性保險"}'::jsonb, 'C', '《汽車保險（第三者風險）條例》:必須就因在道路（包括私家路——位於完全或主要用作進行建造工程或工業活動的範圍內的私家路則除外)上使用汽車導致或引起任何人死亡或身體受傷而承擔的法律責任購買保險，'),
('p2', 25, '一', '一般保險產品類別', '26. 在強制性汽車傷亡責任，最低要求的保險金額為：', '{"A":"一百萬","B":"一億","C":"沒有上限","D":"不受限制"}'::jsonb, 'B', '對於第三者的死亡和受傷的法律責任，最低要求的保險金額是每次事故一億港元（實際上，這也是香港汽車保單的通常彌償限額（或責任限額）。'),
('p2', 26, '一', '一般保險產品類別', '27. 以下哪項汽車保險保障形式，只保障法律所要求的責任？', '{"A":"「法令」","B":"第三者責任","C":"綜合責任","D":"第三者責任、火災、盜竊"}'::jsonb, 'A', '「法令」只提供由汽車導致或引起任何人死亡或身體受傷而承擔的法律責任購買保險，僱主責任和合約上的法律責任則除外。'),
('p2', 27, '一', '一般保險產品類別', '28. 在強制性汽車法例的「第三者」保單，與本港汽車保險人的第三者保單：', '{"A":"完全相同","B":"均只是「法令」保障責任","C":"均可是「法令」與「綜合」","D":"完全不相同，後者是提供財產損毀及責任保障"}'::jsonb, 'D', '「第三者」一詞總是有雙重含義。條例中「第三者」風險僅指對死亡、受傷應負的法律責任。另一方面，「第三者」汽車保險單除了承保死亡和傷害的法律責任以外，還承保對第三者造成財產損害的法律責任。'),
('p2', 28, '一', '一般保險產品類別', '29. 以下哪項對純「法令」保險的描述不正確？', '{"A":"提供最狹窄保障範圍的汽車保險","B":"只對死亡或受傷的責任作出保障","C":"是汽車保險中最便宜的一種，所以最為普遍","D":"以上所有各項"}'::jsonb, 'C', '純法令保險保障已經很難在市場上找到'),
('p2', 29, '一', '一般保險產品類別', '30. 以下哪項或哪些不屬於汽車保險中第三者保險的正確描述？', '{"A":"它祗適用對第三者做成的受傷及財產損毀","B":"通常情況下，最低要求保險金額是一億港元","C":"它屬於強制性保險","D":"它同時保障受保司機與乘客的受傷"}'::jsonb, 'D', '《汽車保險(第三者風險)條例》是指「法令」保險保障的範圍，只提供由汽車導致或引起任何人死亡或身體受傷而承擔的法律責任購買保險，而一般保險公司提供的第三者保障指任何受保駕駛者（或任何乘客）對第三者造成死亡、受傷或財產損害而應負的法律責任，對於第三者的死亡和受傷的法律責任，最低要求的保險金額是每次事故一億港元（實際上，這也是香港汽車保單的通常彌償限額（或責任限額）。'),
('p2', 30, '一', '一般保險產品類別', '31. 強制性汽車保險是:', '{"A":"在道路（包括私家路位於主要用作進行建造工程或工業活動的範圍內的私家路則除外)上使用汽車導致或引起任何人死亡或身體受傷而承擔的法律責任購買保險","B":"在道路（包括私家路位於完全或主要用作進行建造工程或工業活動的範圍內的私家路則除外)上使用汽車導致或引起任何人死亡或身體受傷而承擔的法律責任購買保險","C":"在道路（包括公路位於完全或主要用作進行建造工程或工業活動的範圍內的私家路則除外)上使用汽車導致或引起任何人死亡或身體受傷而承擔的法律責任購買保險","D":"在道路（包括所有用作進行建造工程或工業活動的範圍內的私家路則除外)上使用汽車導致或引起任何人死亡或身體受傷而承擔的法律責任購買保險"}'::jsonb, 'B', '必須就因在道路(包括私家路位於完全或主要用作進行建造工程或工業活動的範圍內的私家路則除外)上使用汽車導致或引起任何人死亡或身體受傷而承擔的法律責任購買保險，僱主責任和合約上的法律責任，此類法律責任稱為「法令責任」。'),
('p2', 31, '一', '一般保險產品類別', '32. 本港汽車保險的慣例中，保險人採用的無索償折扣提供最高的折扣率予：', '{"A":"所有類別的車輛","B":"私家車","C":"電單車","D":"商用車輛"}'::jsonb, 'B', '私家車的典型無索償折扣表是這樣的：第一年的無索償記錄可賺取無索償折扣20%，第二年為30%，依次類推，而連續五年的無索償記錄將無索償折扣累進到最高的60%。對於其他類別的汽車，折扣表相當可能從10%開始，經過連續三年的無索償記錄後提升到最高的30%。'),
('p2', 32, '一', '一般保險產品類別', '33. 在私家車的保險中，「折扣回減機制」的意思是：', '{"A":"若索償與第三者有關，折扣將不會回減","B":"每次索償會將所有折扣取消","C":"每次索償會將折扣回減30%","D":"每次索償會將折扣回減10%"}'::jsonb, 'C', '私家車而言，無索償折扣以所謂「折扣回減機制」運作一次索償不一定會撤銷來年的折扣。舉個例子，如果在某個保單年度中所享用的折扣屬於四年的相應折扣率（即50%），而當年發生了一次索償，那麽續保時的折扣率便會被調低至20%。'),
('p2', 33, '一', '一般保險產品類別', '34. 在某種情況下，無索償折扣採用的「折扣回減」機制，意思是不會因一次的索償而導致損失全部折扣，不過這種機制只適用於？', '{"A":"私家車保險","B":"電單車保險","C":"商用車輛保險","D":"汽車行業風險保險"}'::jsonb, 'A', '私家車而言，無索償折扣以所謂「折扣回減機制」運作一次索償不一定會撤銷來年的折扣。舉個例子，如果在某個保單年度中所享用的折扣屬於四年的相應折扣率（即50%），而當年發生了一次索償，那麽續保時的折扣率便會被調低至20%。'),
('p2', 34, '一', '一般保險產品類別', '35. 在汽車保險中，何時可取得無索償折扣？', '{"A":"以往無任何索償紀錄","B":"於來年度並無索償紀錄","C":"於上一年度並無任何索償紀錄","D":"以上所有各項"}'::jsonb, 'C', '私家車的典型無索償折扣表是這樣的：第一年的無索償記錄可賺取無索償折扣20%，第二年為30%，依次類推，而連續五年的無索償記錄將無索償折扣累進到最高的60%。對於其他類別的汽車，折扣表相當可能從10%開始，經過連續三年的無索償記錄後提升到最高的30%。'),
('p2', 35, '一', '一般保險產品類別', '36. 大部份汽車保險保單均有一項慣例，就是如果被保險人在過往一年沒有作出索償，便可於來年續保時，獲取保費上的扣減。這種慣例的最正確名稱為：', '{"A":"無索償獎金","B":"無索償折扣","C":"無索償扣減額","D":"無索償續保減免"}'::jsonb, 'B', '汽車保險有一個非常重要，也幾乎是最為獨特的特徵，就是如果被保險人在剛過去的保單年度中沒有任何索償，那麽保險人便會對續保年保費給予稱為無索償折扣(No Claim Discount (NCD) / ClaimFreeDiscount)的累進折扣，以鼓勵安全駕駛。'),
('p2', 36, '一', '一般保險產品類別', '37. 以下哪項對「無索償折扣」的描述是正確的？', '{"A":"私家車獲得的折扣是最低的","B":"市場上很多時稱為「無索償獎金」","C":"在過去一年未曾索償而可獲得超過百份比的保費折扣","D":"商用車輛往往比私家車的折扣為高"}'::jsonb, 'B', '汽車保險有一個非常重要，也幾乎是最為獨特的特徵，就是如果被保險人在剛過去的保單年度中沒有任何索償，那麽保險人便會對續保年保費給予稱為無索償折扣(No Claim Discount (NCD) / ClaimFreeDiscount)的累進折扣，以鼓勵安全駕駛。'),
('p2', 37, '一', '一般保險產品類別', '38. 無索償折扣的最高百分比出現於：', '{"A":"私家車保險","B":"電單車保險","C":"的士保險","D":"商用車輛保險"}'::jsonb, 'A', '私家車的典型無索償折扣表是這樣的：第一年的無索償記錄可賺取無索償折扣20%，第二年為30%，依次類推，而連續五年的無索償記錄將無索償折扣累進到最高的60%。對於其他類別的汽車，折扣表相當可能從10%開始，經過連續三年的無索償記錄後提升到最高的30%。'),
('p2', 38, '一', '一般保險產品類別', '39. 如被保險人享有百分之六十的無索償折扣，經過一次索償後，無索損折扣將減至:', '{"A":"百分之三十","B":"百分之二十","C":"百分之十","D":"百分之一"}'::jsonb, 'A', '私家車而言，無索償折扣以所謂「折扣回減機制」運作一次索償不一定會撤銷來年的折扣。舉個例子，如果在某個保單年度中所享用的折扣屬於四年的相應折扣率（即50%），而當年發生了一次索償，那麽續保時的折扣率便會被調低至 20%。'),
('p2', 39, '一', '一般保險產品類別', '40. 無索償折扣會應用於私家車的保險中，當私家車得到最高的無索償折扣時，不會因一次意外索償而完全取消所有折扣。這種運作稱為：', '{"A":"無索償折扣扣減機制","B":"平均機制","C":"折扣回減機制","D":"不能作廢保單條款"}'::jsonb, 'C', '私家車而言，無索償折扣以所謂「折扣回減機制」運作一次索償不一定會撤銷來年的折扣。舉個例子，如果在某個保單年度中所享用的折扣屬於四年的相應折扣率（即50%），而當年發生了一次索償，那麽續保時的折扣率便會被調低至 20%。'),
('p2', 40, '一', '一般保險產品類別', '41. 你預期以下哪項不屬於本港所簽發的無擴展汽車保單的除外責任？', '{"A":"財物損毀責任","B":"發生在保險人指定保障區範圍以外的意外","C":"被保險汽車首一千元損毀","D":"以上所有各項"}'::jsonb, 'A', '無拓展是指《汽車保險(第三者風險)條例》是指「法令」保險保障的範圍，對第三者造成財產損害的法律責任不屬於強制保險的範圍。'),
('p2', 41, '一', '一般保險產品類別', '42. 下列哪項不大可能出現於大部份汽車保險保單的除外責任？', '{"A":"戰爭及核子風險","B":"合約上的責任","C":"屬於社交、娛樂及消閒用途","D":"未經批準的車輛用途"}'::jsonb, 'C', '汽車的用途是個釐定保費的重要依據，因此，如果某張保單規定了受保汽車只能作社交、家事及娛樂之用，但該車卻在遇上意外事故時被用作的士，這意外事故是不保的。'),
('p2', 42, '一', '一般保險產品類別', '43. 根據各類汽車保險〈汽車行業除外〉，均有一些通用的除外責任，其中包括下列哪項或哪些除外責任？', '{"A":"賽車","B":"汽車測試","C":"用在汽車行業的用途","D":"以上所有各項"}'::jsonb, 'D', '汽車的用途是個釐定保費的重要依據，因此，如果某張保單規定了受保汽車只能作社交、家事及娛樂之用，但該車卻在遇上意外事故時被用作的士，這意外事故是不保的。'),
('p2', 43, '一', '一般保險產品類別', '44. 在一般保險的責任保險中，合約的附加責任(協議已約定承擔的法律責任)是：', '{"A":"屬於除外責任","B":"自動獲得保障","C":"在法律上是不可保的","D":"不可保的"}'::jsonb, 'A', '合約附加的責任，此詞常用於責任保險，意指根據保單索取彌償的人已在某項協議中同意承擔的法律責任，而這項法律責任是不可能在沒有這項協議的情況下產生的。'),
('p2', 44, '一', '一般保險產品類別', '45. 你認為以下哪項或哪些損失原因屬於汽車保險保單的除外責任？', '{"A":"戰爭風險","B":"合約附加的責任","C":"核子和輻射風險","D":"上述所有各項"}'::jsonb, 'D', '戰爭、合約附加責任及核子和輻射風險均為除外責任。'),
('p2', 45, '一', '一般保險產品類別', '46. 汽車保險怎樣釐定保費？', '{"A":"車輛的用途","B":"引擎的立方容量","C":"被保人對其車輛的估計價值","D":"上述各項都是"}'::jsonb, 'D', '保障種類、馬力、汽車價值、用途、物理特徵及司機等均為計算保費的元素。'),
('p2', 46, '一', '一般保險產品類別', '47. 您認為以下哪一種不屬於保險人釐定綜合私家汽車保險單保費的考慮因素？', '{"A":"被保險人對車輛的估計價值","B":"保障範圍","C":"被保險人的性別","D":"被保險車輛的引擎容量"}'::jsonb, 'C', '保障種類、馬力、汽車價值、用途、物理特徵及司機等均為計算保費的元素。'),
('p2', 47, '一', '一般保險產品類別', '48. 有一種由被保險人要求的汽車保險保單自負額，通常是為了換取保單的折扣，這種自負額稱為：', '{"A":"標準自負額","B":"自願性自負額","C":"承保自負額","D":"非強制性自負額"}'::jsonb, 'B', '自負額可以是自願性自負額（也就是被保險人為了換取保費折扣而自己要求的）'),
('p2', 48, '一', '一般保險產品類別', '49. 下列哪項有關標準自負額的陳述並不正確？', '{"A":"它們必定和任何自願性自負額並行","B":"這類自負額不容許提供保費扣減","C":"適用於同一業務類別的所有保單","D":"這類自負額容許提供一項標準保費的扣減"}'::jsonb, 'D', '標準自負額不會有保費折扣。'),
('p2', 49, '一', '一般保險產品類別', '50. 「有權追回款項條款」適用於：', '{"A":"只在特別條款（例如額外保費）生效時","B":"在強制性條款凌駕於保單條款時","C":"意外中只有被保人的汽車遭損壞","D":"只由第三者引起的損毀"}'::jsonb, 'B', '根據規定，凡為施行「使若干條款無效及有權追回款項」條款而發出的保險單內載列任何條件，訂定如在引致可根據該保險單提出申索的事故發生後，某些指明事情獲得辦理或沒有辦理，便不會根據該保險單產生法律責任或已如此產生的法律責任即告終止，則該條件對任何適用強制汽車保險相關規定的申索並無效力。'),
('p2', 50, '一', '一般保險產品類別', '51. 「有權追回款項條款」可於以下哪項情況下使用？', '{"A":"當強制性條款凌駕於保險條款之上","B":"當只有被保險人的車輛受損的時候","C":"當涉及第三者財產損毀的時候","D":"以上所有各項"}'::jsonb, 'A', '根據規定，凡為施行「使若干條款無效及有權追回款項」條款而發出的保險單內載列任何條件，訂定如在引致可根據該保險單提出申索的事故發生後，某些指明事情獲得辦理或沒有辦理，便不會根據該保險單產生法律責任或已如此產生的法律責任即告終止，則該條件對任何適用強制汽車保險相關規定的申索並無效力。'),
('p2', 51, '一', '一般保險產品類別', '52. 汽車保險中，私家車用途是：', '{"A":"受保駕駛者視為陌生人的乘客","B":"非為獎賞或租金而接載的乘客","C":"為了租金而提供接載服務的乘客","D":"會給予小費的乘客(如給予小費予的士司機)"}'::jsonb, 'B', '該車只能用於社交、家事及娛樂目的，或用於被保險人的業務或專業之上；不得用來出租或取酬、參加比賽…或用於任何與汽車銷售行業有關連的目的。'),
('p2', 52, '一', '一般保險產品類別', '53. 以下哪項是不屬於香港汽車保單中造成「本身損失及損害」的保障範圍？', '{"A":"於碰撞中對汽車做成的損害","B":"對輪呔造成損毀，對汽車並未做成其他損害","C":"汽車上的配件及備用零件","D":"除對輪呔造成損毀外，對汽車亦做成其他損害"}'::jsonb, 'B', '後果損失、折舊、損耗，以及電氣或機械故障均不獲賠償。'),
('p2', 53, '一', '一般保險產品類別', '54. 以下哪項損失及損毀的例子，可得到綜合私家車保單的保障？', '{"A":"更換破舊的死氣喉","B":"更換破舊的電線的開支","C":"被保險人的車輛的車胎被割損(沒有其他損毀)","D":"被保險人的車輛被盜賊偷去時損毀"}'::jsonb, 'D', '後果損失、折舊、損耗，以及電氣或機械故障均不獲賠償。'),
('p2', 54, '一', '一般保險產品類別', '55. 在香港現時未擴展的汽車保險保障中，以下哪項是除外責任？', '{"A":"汽車冷卻器的損壞","B":"汽車在維修過程中租用其他車輛的費用","C":"汽車零件遭盜竊","D":"汽車擋風玻璃遭撞擊而損壞"}'::jsonb, 'B', '受保汽車的損失或損害（本身損害）：這種「全險」範圍的財產保險，承保被保險人的汽車，及屬於該汽車並於遇事時在其上的配件和零件，並以該車遭受損失或損害時的合理市價為彌償上限。'),
('p2', 55, '一', '一般保險產品類別', '56. 以下哪項屬於私家車保險得到折扣的途徑？', '{"A":"自願性自負額","B":"無索償折扣","C":"汽車長期「停用」","D":"以上所有各項"}'::jsonb, 'D', '無索償折扣和自願性自負額以外，用同一份保單承保多於一輛汽車或受保汽車暫時停用了超過最低限度的時間後，也可以獲得保費折扣。'),
('p2', 56, '一', '一般保險產品類別', '57. 以下哪項對於電單車保單的說明是正確的？
i. 只有當整輛電單車遭到偷竊，才會作出賠償
ii. 通常不會設有醫療開支的保障
iii. 可享有的無索償折扣，比私家車低
iv. 通常會於火災或盜竊引起的損失設有標準自負額', '{"A":"i, ii, iii","B":"i, ii, iv","C":"ii, iii, iv","D":"i, ii, iii, iv"}'::jsonb, 'A', '只有當整輛電單車被盜時才能構成有效的盜竊索償。僅是電單車的配件被盜是不會受到承保的。通常對受保電單車的任何損失或損害（因火災或盜竊引起的除外），都設有標準自負額。'),
('p2', 57, '一', '一般保險產品類別', '58. 在電單車保單中，「本身損毀或意外損毀」保障的除外責任包括：
i. 電單車部份配件因盜竊所招致的損失
ii. 因意外而引致的修理費
iii. 司機因投保車輛意外損毀而引致的醫療開支
iv. 自負額', '{"A":"只有i","B":"只有iii","C":"i, ii","D":"i, iii, iv"}'::jsonb, 'D', '只有當整輛電單車被盜時才能構成有效的盜竊索償。僅是電單車的配件被盜是不會受到承保的。通常對受保電單車的任何損失或損害（因火災或盜竊引起的除外），都設有標準自負額。'),
('p2', 58, '一', '一般保險產品類別', '59. 以下哪項描述不屬於「電單車」保單的保障範圍？', '{"A":"電單車乘客在意外中身體受傷","B":"當整輛電單車遭到偷竊","C":"電單車的意外損毀","D":"為電單車乘客所付的醫療開支"}'::jsonb, 'D', '承保醫療費用的標準保單部分及擴展人身意外保險保障並不存在。'),
('p2', 59, '一', '一般保險產品類別', '60. 以下哪項是對於電單車保險的正確描述？
i. 相對於私家車保險的「無索償折扣」為低
ii. 盜竊索償部份祗適用於整輛車被盜去
iii. 乘客引致的第三者責任通常是不保的
iv. 火災及盜竊不設有標準自負額', '{"A":"i, ii, iii","B":"i, ii, iv","C":"ii, iii, iv","D":"i, ii, iii, iv"}'::jsonb, 'D', '私家車以外之汽車無索償折扣最高為30%。只有當整輛電單車被盜時才能構成有效的盜竊索償。僅是電單車的配件被盜是不會受到承保的。通常對受保電單車的任何損失或損害（因火災或盜竊引起的除外），都設有標準自負額。'),
('p2', 60, '一', '一般保險產品類別', '61. 電單車保險的保障範圍不包括：', '{"A":"司機的意外受傷","B":"祗限整部車輛被盜去","C":"後座乘客在發生意外後的醫療費用","D":"對乘客造成的受傷負責"}'::jsonb, 'C', '承保醫療費用的標準保單部分及擴展人身意外保險保障並不存在。'),
('p2', 61, '一', '一般保險產品類別', '62. 一些特別車輛(如：救護車及鏟泥車)所購買的保險類別為：', '{"A":"商用","B":"汽車貿易","C":"專門車輛","D":"綜合"}'::jsonb, 'A', '的士、輕型貨車到巨型貨櫃車及為專門用途而特別製造或改造的汽車均屬商用車輛保險之保障範圍。'),
('p2', 62, '一', '一般保險產品類別', '63. 一部商用車輛如果同時使用於建築工程上，例如挖掘地洞，商業車輛保單可能在這段操作期間拒絕提供保障。這種除外責任稱為：', '{"A":"謀生工具條款","B":"業務使用條款","C":"工業行動條款","D":"專業責任條款"}'::jsonb, 'A', '汽車被用作謀生工具（例如正在用作謀生工具的機械挖土機），除非屬於強制保險相關法定條文所要求的保障範圍。（這項除外責任條款稱為「謀生工具條款」。）'),
('p2', 63, '一', '一般保險產品類別', '64. 在香港，會把車輛用作「謀生工具」有關的除外責任，較可能出現於下列哪項商用車輛保險單中？', '{"A":"運送貨櫃或拖架工具的商用車輛","B":"的士","C":"機械挖土機","D":"送遞薄餅的電單車"}'::jsonb, 'C', '汽車被用作謀生工具（例如正在用作謀生工具的機械挖土機），除非屬於強制保險相關法定條文所要求的保障範圍。（這項除外責任條款稱為「謀生工具條款」。）'),
('p2', 64, '一', '一般保險產品類別', '65. 由於車房的業務絕大程度與汽車有關，而且有特別的需要，提供的保障亦有所不同，這類保單稱為：', '{"A":"汽車行業風險","B":"商業車輛風險","C":"貿易車輛風險","D":"維修貿易風險"}'::jsonb, 'A', '汽車行業風險：從事主要與汽車有關的業務的人，諸如買賣車輛、修理車輛、代客開車、洗車、救援拖車等，對保險會有特別的需要。這類風險的保單，稱為汽車行業保單，可能涉及在道路上使用汽車或處所風險， 並提供多樣化的保險保障組合。'),
('p2', 65, '一', '一般保險產品類別', '66. 車房及其他類似風險會有特別的需要，這是：', '{"A":"汽車行業風險","B":"汽車責任限額","C":"批發及貿易","D":"第三者損毀"}'::jsonb, 'A', '汽車行業風險：從事主要與汽車有關的業務的人，諸如買賣車輛、修理車輛、代客開車、洗車、救援拖車等，對保險會有特別的需要。這類風險的保單，稱為汽車行業保單，可能涉及在道路上使用汽車或處所風險， 並提供多樣化的保險保障組合。'),
('p2', 66, '一', '一般保險產品類別', '67. 以下哪項有關免賠額的描述是正確的？', '{"A":"它是可與「自負額」互換的","B":"免賠額金額通常低於自負額","C":"它們隱含於合約中","D":"以上各項皆是"}'::jsonb, 'A', '自負額（也稱免賠額）是指一項訂明的金額，每次損失中的該金額或以下的金額是不受保的。'),
('p2', 67, '一', '一般保險產品類別', '68. 在本港，商業車輛標準組合保單中「本身損害」部份，相當可能出現與以下哪項有關的特殊除外責任？', '{"A":"火災和盜竊","B":"超載或勞損","C":"碰撞和推翻","D":"停放或停泊時造成的損害"}'::jsonb, 'B', '超載或勞損是除外責任。'),
('p2', 68, '一', '一般保險產品類別', '69. 以下哪項不大可能涉及在汽車保險保單中的「有權追回款項條款」？', '{"A":"未能在合理時間內報告受傷行人","B":"未能在合理時間內報告受保損壞車輛","C":"在意外事發現向受傷行人承認法律責任","D":"以上各項皆是"}'::jsonb, 'B', '主要為被保險人尚未取得保險人的書面同意以前即以任何方式向第三者承認法律責任，根據「有權追回款項條款」便不會在保險單產生法律責任，或已如此產生的法律責任即告終止，則該條件對任何適用強制汽車保險相關規定的申索並無效力。'),
('p2', 69, '一', '一般保險產品類別', '70. 在某些情形下，即使被保險人違反了保單條款，保險人仍須就屬於「法令」保險範圍內的索償作出賠償，這些索償較多出現於汽車意外，這條款是:', '{"A":"有權追回款項條款","B":"比例分攤條款","C":"特別條款","D":"專業責任條款"}'::jsonb, 'A', '被保險人違反了保單條款，保險人仍須就屬於「法令」保險範圍內的索償作出賠償的條款名稱為「使若干條款無效及有權追回款項」條款。'),
('p2', 70, '一', '一般保險產品類別', '71. 汽車保險中第三者保險的保障對象包括？', '{"A":"受保汽車裝卸「貨物」(可包括運往新居的家居用品)","B":"任何乘客(例如因疏忽地打開車門而導致意外事故)","C":"受保汽車裝卸「貨物」(包括商用汽車所運載的貨物)","D":"屬於僱員補償保險的保障範圍內的索償"}'::jsonb, 'B', '第三者責任保險保障的對象是被保險人及任何其他受保司機及任何乘客(例如因疏忽地打開車門而導致意外事故)。'),
('p2', 71, '一', '一般保險產品類別', '72. 無索償折扣(NCD)以所謂「折扣回減機制」運作，一次索償表示已獲得最高折扣者，其折扣是:', '{"A":"每次索償會將所有折扣回減至0%","B":"每次索償會將折扣回減10%","C":"每次索償會將折扣回減20%","D":"每次索償會將折扣回減30%"}'::jsonb, 'D', '對私家車而言，當年發生了一次索償，那麽續保時的折扣率便會被調低30%。'),
('p2', 72, '一', '一般保險產品類別', '73. 以下那項或那些是綜合汽車保險保障肯定不會承保的', '{"A":"司機於駕駛時睡著","B":"司機從不曾持有駕駛執照","C":"司機駕駛的速度比一般速度快","D":"以上所述各項"}'::jsonb, 'B', '不曾持有駕駛執照(非法行為)汽車保險固然不能在保障範圍內。'),
('p2', 73, '一', '一般保險產品類別', '74. 以下哪項或哪些是汽車投保中的所需資料？
i. 司機的家庭背景
ii. 司機的職業
iii. 司機的姓名及地址詳情
iv. 司機的過去索償索償紀錄', '{"A":"i, ii, iii","B":"i, ii, iv","C":"i, iii, iv","D":"ii, iii, iv"}'::jsonb, 'D', '車保不會考慮家庭背景因素'),
('p2', 74, '一', '一般保險產品類別', '75. 保險人拒絶索償是因被保險人違反保單條款，但有一種索償是可能凌駕於拒絶索償的理由，這是：', '{"A":"個人意外保險","B":"關於被保險人財產的保險","C":"關於強制性保險保障的範圍","D":"以上所述各項"}'::jsonb, 'C', '保險人須就屬於強制保險範圍內的索償作出賠償，即使本來可以基於某項合約條款遭到違反為由而拒絕賠償'),
('p2', 75, '一', '一般保險產品類別', '76. 不用符合強制汽車保險要求的例外情況是存在的，如向庫務局局長作出價值______港元的繳存的人所擁有的汽車正由該車主或車主的僱員駕駛。', '{"A":"1000000","B":"2000000","C":"3000000","D":"5000000"}'::jsonb, 'B', '向庫務局局長作出價值200萬港元的繳存的人所擁有的汽車正由該車主或車主的僱員駕駛'),
('p2', 76, '一', '一般保險產品類別', '77. 以下哪項關於個人意外及疾病保險是不正確的？', '{"A":"個人意外保險是意外保險中首先面世的主要險種","B":"個人意外死亡保障權益與人壽保險相同","C":"它主要保障內容是死於意外的整筆權益","D":"除了整筆權益，也可以提供每週利益"}'::jsonb, 'B', '人身意外保險屬於意外保險中首先面世的主要險種，它起源於早期鐵路上發生的意外事故不斷上升所引發的保險需求。人身意外保險保障三個主要項目:整筆支付的利益、按周計算的利益及醫療費用'),
('p2', 77, '一', '一般保險產品類別', '78. 根據個人意外保險保單中，每周利益會於以下哪種情況發放？', '{"A":"死亡","B":"醫療開支","C":"暫時性喪失能力","D":"永久喪失能力"}'::jsonb, 'C', '按周計算的利益：這些是針對暫時完全殘疾（傷殘程度達100%者為之「完全殘疾」）或暫時部分殘疾（傷殘程度低於100%）的定期付款。'),
('p2', 78, '一', '一般保險產品類別', '79. 個人意外保險屬於意外保險的首個主要類別，是因應早期以下哪項不斷上升的意外而發展？', '{"A":"汽車","B":"鐵路","C":"船隻","D":"腳踏車"}'::jsonb, 'B', '人身意外保險屬於意外保險中首先面世的主要險種，它起源於早期鐵路上發生的意外事故不斷上升所引發的保險需求。'),
('p2', 79, '一', '一般保險產品類別', '80. 個人意外保險提供的保障包括三個標題，分別是：整筆權益(一筆過的款項)、每週利益及', '{"A":"退休年金","B":"牙科護理","C":"醫療開支","D":"住院權益"}'::jsonb, 'C', '人身意外保險保障三個主要項目:整筆支付的利益、按周計算的利益及醫療費用'),
('p2', 80, '一', '一般保險產品類別', '81. 標準的個人意外保單所提供保障的三大標題，包括整筆支付的利益、醫療費用及：', '{"A":"按周計算的利益","B":"輔導服務","C":"住院權益","D":"意外中衣物損毀的財產保險"}'::jsonb, 'A', '人身意外保險保障三個主要項目:整筆支付的利益、按周計算的利益及醫療費用'),
('p2', 81, '一', '一般保險產品類別', '82. 個人意外保單中的按周計算的利益，可以在下列哪個情況下提取？', '{"A":"暫時喪失全部能力","B":"暫時喪失部分能力","C":"意外受傷住院期間","D":"以上所有各項"}'::jsonb, 'D', '按周計算的利益：這些是針對暫時完全殘疾（傷殘程度達100%者為之「完全殘疾」）或暫時部分殘疾（傷殘程度低於100%）的定期付款。'),
('p2', 82, '一', '一般保險產品類別', '83. 在個人意外及疾病保單中，以下哪一項不屬於保單中的保障範圍？', '{"A":"因意外導致死亡或受傷的整筆權益","B":"由於暫時性的喪失能力而發放的每週利益","C":"由於意外受傷入院而發放的每日醫療權益","D":"因意外受傷而招致的醫療開支"}'::jsonb, 'C', '人身意外保險保障三個主要項目:整筆支付的利益、按周計算的利益及醫療費用按周計算的利益：這些是針對暫時完全殘疾（傷殘程度達100%者為之「完全殘疾」）或暫時部分殘疾（傷殘程度低於100%）的定期付款。'),
('p2', 83, '一', '一般保險產品類別', '84. 以下哪項對人身意外保險的整付利益的描述是正確的
i. 利益是「主要保額」的某一百分比
ii. 死亡或主要受傷均可取得百份之一百的主要保額
iii. 多重受傷的總額可取得多於百分之一百的賠償對指明損傷及其有關的利益分配往往是在保單訂明的', '{"A":"i, ii, iii","B":"i, ii, iv","C":"ii, iii, iv","D":"i, ii, iii, iv"}'::jsonb, 'B', '死亡會得到100%的保險金給付，而指定的主要損傷（比如喪失雙肢體和完全喪失視力等）的任何一項同樣會得到100%的保險金給付。不構成任何上述指定主要損傷的完全永久殘疾也會得到100%的保險金給付。較為輕微的永久性傷害，所得的保險金給付百分率較低，'),
('p2', 84, '一', '一般保險產品類別', '85. 以下哪項不屬於慣常用於人身意外保險的保障範圍？', '{"A":"按周計算的利益","B":"醫療費用","C":"整筆支付利益","D":"住院利益"}'::jsonb, 'D', '人身意外保險保障三個主要項目:整筆支付的利益、按周計算的利益及醫療費用'),
('p2', 85, '一', '一般保險產品類別', '86. 根據個人意外保險保單，按周計算的利益通常以下列哪項情況發放?', '{"A":"死亡","B":"暫時喪失能力","C":"醫療開支","D":"永久喪失能力"}'::jsonb, 'B', '按周計算的利益：這些是針對暫時完全殘疾（傷殘程度達100%者為之「完全殘疾」）或暫時部分殘疾（傷殘程度低於100%）的定期付款。'),
('p2', 86, '一', '一般保險產品類別', '87. 個人意外保單中的按周計算的利益，可以在下列哪個情況下提取？', '{"A":"完全傷殘","B":"部份殘疾","C":"死亡或意外死亡","D":"以上所有各項"}'::jsonb, 'B', '按周計算的利益：這些是針對暫時完全殘疾（傷殘程度達100%者為之「完全殘疾」）或暫時部分殘疾（傷殘程度低於100%）的定期付款。'),
('p2', 87, '一', '一般保險產品類別', '88. 在個人意外保單的「意外身體受傷」的定義為：', '{"A":"意外及外在的原因引起的","B":"暴力及可見的身體受傷","C":"單獨及獨立於任何其他原因","D":"符合以上各項的要求"}'::jsonb, 'D', '意外的身體受傷：保單可能規定必須「由意外、外在、暴力及明顯可見的方式純粹地和直接地引起或導致的」等字句。'),
('p2', 88, '一', '一般保險產品類別', '89. 不論是獨立保單形式或是組合保單一部份的保障形式，在個人意外保險中，所包括的一般除外責任較可能包括：', '{"A":"自殺","B":"故意傷害自己身體","C":"危險的運動(例如:爬山)","D":"以上各項皆是"}'::jsonb, 'D', '除外責任：基本風險，比如戰爭、叛亂、核風險等。危險活動，例如作為乘客或車手參加賽車，作為專業運動員參與體育運動，及飛行活動（作為付費乘客進行者除外）。違反社會原則的活動，例如自殺、蓄意令自己受傷、酗酒或濫藥（服用由合格醫生開的藥則屬例外）。'),
('p2', 89, '一', '一般保險產品類別', '90. 「個人意外」保險需要為下列哪項補償作出賠償？
i. 自殺
ii. 意外死亡
iii. 蓄意令自己受傷
iv. 爬山引致的傷亡', '{"A":"只有i","B":"只有ii","C":"ii , iv","D":"ii, iii , iv"}'::jsonb, 'B', '除外責任：基本風險，比如戰爭、叛亂、核風險等。危險活動，例如作為乘客或車手參加賽車，作為專業運動員參與體育運動，及飛行活動（作為付費乘客進行者除外）。違反社會原則的活動，例如自殺、蓄意令自己受傷、酗酒或濫藥（服用由合格醫生開的藥則屬例外）。'),
('p2', 90, '一', '一般保險產品類別', '91. 以下那項不屬於人身意外保險的除外責任？', '{"A":"自殘身體","B":"爬山而導致受傷","C":"駕駛小型飛機時，在空中相撞","D":"電單車乘客在交通意外中身亡"}'::jsonb, 'D', '除外責任：基本風險，比如戰爭、叛亂、核風險等。危險活動，例如作為乘客或車手參加賽車，作為專業運動員參與體育運動，及飛行活動（作為付費乘客進行者除外）。違反社會原則的活動，例如自殺、蓄意令自己受傷、酗酒或濫藥（服用由合格醫生開的藥則屬例外）。'),
('p2', 91, '一', '一般保險產品類別', '92. 個人意外保險的保障包括：', '{"A":"自殺","B":"濫用藥物","C":"被搶劫案中的劫匪所槍傷","D":"上述所有各項"}'::jsonb, 'C', '意外的身體受傷：保單可能規定必須「由意外、外在、暴力及明顯可見的方式純粹地和直接地引起或導致的」等字句。'),
('p2', 92, '一', '一般保險產品類別', '93. 釐定意外保險保費的基本因素包括：', '{"A":"過往5年的意外數目","B":"被保險人的居住地點","C":"從死亡表中取得","D":"被保險人的專業職業"}'::jsonb, 'D', '個別的特點（如年齡）可能會影響核保的結果，但根據被保險人的職業計算保費是標準的做法。'),
('p2', 93, '一', '一般保險產品類別', '94. 個人意外保單：', '{"A":"只能由被保險人才可取消","B":"可能由保險人取消，但這種情況並不常見","C":"只能由於被保險人改變職業才可取消","D":"不能於保單生效兩年後才取消"}'::jsonb, 'B', '人身意外保單一般為期一年，期滿後是否續保是個相互協議的問題。保單一般包含註銷條款，允許單方面發出訂明通知以中止保單，保費可退。'),
('p2', 94, '一', '一般保險產品類別', '95. 在個人意外保單，被保人的年齡：', '{"A":"在同一個保險年齡範圍內並不重要","B":"直接影響每年保費","C":"影響首年保費","D":"是承保人考慮的最重要特點"}'::jsonb, 'A', '雖然保費並非根據受保人的年齡來釐定，但是保單通常指明可保年齡的範圍（例如從 18 歲到 70歲—就成人保險保障而言）。'),
('p2', 95, '一', '一般保險產品類別', '96. 保險人取消慣常人身意外保單是：', '{"A":"不可能的","B":"法律所禁止的","C":"保單條文所禁止的","D":"可能的"}'::jsonb, 'D', '人身意外保單一般為期一年，期滿後是否續保是個相互協議的問題。保單一般包含註銷條款，允許單方面發出訂明通知以中止保單，保費可退。'),
('p2', 96, '一', '一般保險產品類別', '97. 醫療保險的保障範圍包括：', '{"A":"因意外導致的受傷而已","B":"因疾病導致的受傷而已","C":"因意外或疾病導致的受傷","D":"以上所有皆不正確"}'::jsonb, 'C', '醫療保險的目的，是要承保由意外事故或疾病引致的醫療費用。'),
('p2', 97, '一', '一般保險產品類別', '98. 香港醫療保險機制下，包括以下哪些保障？', '{"A":"因病或意外導致入院","B":"先天性疾病","C":"生育控制，節育的支出","D":"非必要性手術如整容"}'::jsonb, 'A', '醫療保險的目的，是要承保由意外事故或疾病引致的醫療費用。'),
('p2', 98, '一', '一般保險產品類別', '99. 以下哪項會受到醫療保險保單所保障？', '{"A":"交通意外導致的受傷","B":"不育治療","C":"為美容而進行的整容手術","D":"以上所有各項"}'::jsonb, 'A', '醫療保險的目的，是要承保由意外事故或疾病引致的醫療費用。'),
('p2', 99, '一', '一般保險產品類別', '100. 醫療保險保障涵蓋以下哪項？', '{"A":"意外或疾病引致的醫療費用","B":"生育或不育有關醫療的開支","C":"整容","D":"以上所有各項"}'::jsonb, 'A', '生育控制/不育治療及整容手術均為醫療保險的特殊除外責任。'),
('p2', 100, '一', '一般保險產品類別', '101. 以下哪項正確描述醫療保險的除外責任？', '{"A":"包括個人意外保單的除外責任","B":"包括個人意外保單沒有提供的除外責任","C":"包括「自願性」醫療開支(例如：整容手術)","D":"以上所有各項"}'::jsonb, 'D', '人身意外保單的除外責任及整容手術均為醫療保險的特殊除外責任。'),
('p2', 101, '一', '一般保險產品類別', '102. 以下哪項是一般在香港簽發的醫療保險保單中的除外責任？', '{"A":"整容手術","B":"事先存在的狀況","C":"例行醫療檢查","D":"以上所有各項"}'::jsonb, 'D', '整容手術、(保險生效前)已患的疾病及已存在的殘疾及例行醫療檢查及身體檢查均為醫療保險的特殊除外責任。'),
('p2', 102, '一', '一般保險產品類別', '103. 自願醫保計劃的目標是:', '{"A":"為巿民更容易獲得個人住院保險，並提升個人住院保險的質素和透明度，自願醫保為願意及有能力使用私營醫療服務的消費者提供一個額外的選擇","B":"自願醫保為一眾基層市民能享受到高端醫療的住院保險計劃","C":"自願醫保為所有市民能享受到高端醫療的住院保險計劃","D":"為巿民更容易獲得更優惠的個人住院保險，自願醫保為願意及有能力使用私營醫療服務的消費者提供一個額外的選擇"}'::jsonb, 'A', '自願醫保旨在為消費者帶來某些好處。透過令巿民更容易獲得個人住院保險，並提升個人住院保險的質素和透明度，自願醫保為願意及有能力使用私營醫療服務的消費者提供一個額外的選擇。'),
('p2', 103, '一', '一般保險產品類別', '104. 客人為自己，父母，以及祖父母各買一張自願醫保保單，總可扣稅額為？', '{"A":"4萬港幣","B":"3萬港幣","C":"稅額的20%","D":"8000港幣"}'::jsonb, 'A', '外祖父母、父母和兄弟姊妹。不論受保人獲多少張保單承保，每年扣減所涉的保費上限為每名受保人8,000港元，但可申請扣減的指明親屬人數不設上限。'),
('p2', 104, '一', '一般保險產品類別', '105. 一般保險之保險產品與以下哪項或多項有關？', '{"A":"投資相連保單","B":"年金","C":"人生意外及疾病保單","D":"以上各項皆是"}'::jsonb, 'C', '一般保險產品與人生意外及疾病保單有關。'),
('p2', 105, '一', '一般保險產品類別', '106. 一般保險之保險產品與以下哪項或多項有關？
i. 由意外引致的醫療可支
ii. 意外死亡的整筆支付利益
iii. 暫時喪失部份或全部能力支付的每周利益
iv. 住院期間的每日津貼', '{"A":"i, ii, iii","B":"i, ii, iv","C":"i, ii, iv","D":"i, iii, iv"}'::jsonb, 'A', '住院期間的每日津貼並不包括在健康保險中。'),
('p2', 106, '一', '一般保險產品類別', '107. 以下哪項或哪些很可能是人身意外保險的除外責任？', '{"A":"自殺","B":"因愛滋病而死","C":"受保人醉酒駕駛遭致死亡","D":"以上各項皆是"}'::jsonb, 'D', '違反社會原則的活動及因疾病而受傷、（保險生效前）已患疾病引起加重或加速的殘疾屬除外責任。'),
('p2', 107, '一', '一般保險產品類別', '108. 以下那項是正確描述人身意外保單中的年齡限制?', '{"A":"任何類別沒有最低年齡限制","B":"被保人沒有最高年齡限制","C":"保單通常指明可保年齡的範圍","D":"退休人士沒有保險保障和沒有續保保障"}'::jsonb, 'C', '雖然保費並非根據受保人的年齡來釐定，但是保單通常指明可保年齡的範圍。'),
('p2', 108, '一', '一般保險產品類別', '109. 以下那項或那些是人生意外保險保單的醫療費用保障正確的陳述?', '{"A":"所提供的保險保障並無限額","B":"保險保障不適用於常用保單的除外責任","C":"費用必須由意外傷害導致","D":"以上各項皆是"}'::jsonb, 'C', '可獲償付的醫療費用必須由「身體受傷」而非疾病導致，並受每宗事故賠償限額制。'),
('p2', 109, '一', '一般保險產品類別', '110. 以下哪項不是一般保單(醫療保險保單)的除外責任？', '{"A":"中年女人面部「煥然一新」的費用","B":"先天性畸形的治療","C":"保險生效前已患的疾病","D":"由汽車意外令致面部受傷的牙科治療費用"}'::jsonb, 'D', '因意外事故所需進行的牙科治療費用不是除外責任。'),
('p2', 110, '一', '一般保險產品類別', '111. 以下那項不是人生意外保險保單的正確描述?', '{"A":"保費根據受保人的年齡來釐定","B":"根據被保險人的職業計算保費","C":"可購買個人保單 / 團體保單","D":"人身意外保單的合約通常為一年，有可取消條約的情況"}'::jsonb, 'A', '多種個別的特點（如年齡）可能會影響核保的結果，但根據被保險人的職業計算保費是標準的做法。'),
('p2', 111, '一', '一般保險產品類別', '112. 人身意外保險提供的保障包括三個標題，分別是：整筆權益(一筆過的款項)、每週利益及', '{"A":"退休年金","B":"牙科護理","C":"醫療開支","D":"住院權益"}'::jsonb, 'C', '人身意外保險的三個標題包括了整筆支付利益，每周津貼及醫療開支'),
('p2', 112, '一', '一般保險產品類別', '113. 以下那項或那些是人身意外保險保單的醫療費用保障的正確陳述？', '{"A":"所提供的保險保障並無限額","B":"保險保障不適用於常用保單的除外責任","C":"費用必須由意外傷害導致","D":"以上各項皆是"}'::jsonb, 'C', '可獲償付的醫療費用必須由 「身體受傷」而非疾病導致，並受每宗事故賠償限額限制。'),
('p2', 113, '一', '一般保險產品類別', '114. 醫療保險業務指引 (指引31) 適用於:', '{"A":"所有承保醫療保險業務的獲授權保險人及進行相關受規管的活動的持牌保險中介人","B":"只有承保醫療保險業務的獲授權保險人","C":"只有進行醫療保險業務相關受規管的活動的持牌保險中介人","D":"以上所有皆不是"}'::jsonb, 'A', '醫療保險業務指引 (指引31)適用於所有承保醫療保險業務的獲授權保險人及進行相關受規管的活動的持牌保險中介人'),
('p2', 114, '一', '一般保險產品類別', '115. 自願醫保是否包括精神科治療?', '{"A":"可以保障在專科醫生的建議下，香港或海外的精神料治療","B":"可以保障在專科醫生的建議下，在香港境內的精神料治療","C":"可以保障在專科醫生的建議下，在香港或海外接受住院的精神料治療","D":"可以保障在專科醫生的建議下，在香港接受住院的精神料治療"}'::jsonb, 'D', '自願醫保可以保障在專科醫生的建議下，在香港境內接受住院的精神料治療'),
('p2', 115, '一', '一般保險產品類別', '116. 闡明認可產品 (包括基本計劃和靈活計劃)在保單結構、條款及保障的最低要求是以下哪份文件', '{"A":"《自願醫保計劃下保險公司的註冊規則》","B":"《自願醫保計劃認可產品保單範本》","C":"《自願醫保計劃下產品的合規規則》","D":"《自願醫保計劃銷售規則》"}'::jsonb, 'B', '《自願醫保計劃認可產品保單範本》闡明認可產品(包括基本計劃和靈活計劃)在保單結構、條款及保障的最低要求'),
('p2', 116, '一', '一般保險產品類別', '117. 某人為他自己及其四位父母祖父母購買自願醫保計劃，他最終可獲多少額外扣稅額安排', '{"A":"8000","B":"16000","C":"24000","D":"40000"}'::jsonb, 'D', '自願醫保可為本人及「指明親屬」作扣稅安排，「指明親屬」涵蓋納稅人的配偶和子女，及納稅人或其配偶的祖父母、外祖父母、父母和兄弟姊妹。不論受保人獲多少張保單承保，，'),
('p2', 117, '一', '一般保險產品類別', '118. 在一般家居保險中，受保範圍包括
i. 因火災導致財物盜竊損失
ii. 因火災導致財物非盜竊損失
iii. 賊人從撬窗而入的盜竊損失
iv. 逃避火災過程中遺失物件', '{"A":"i, ii","B":"i, ii, iii","C":"ii, iii, iv","D":"i, ii, iii, iv"}'::jsonb, 'B', '家居保險主要是提供財產保險，所承保的是屬於被保險人的建築物及／或其內部的物品。同時指明危險中保障必定承保火災，並進而包含火險中大部分（若非所有）可保的附加危險。（附加危險的項目很多，包括風暴／旋風、地震、爆炸、動物／被汽車碰撞等）。除此之外，盜竊引起的損失或損害也包括在內。'),
('p2', 118, '一', '一般保險產品類別', '119. 一般的家居保險單，會提供下列哪項的保障？', '{"A":"財產保障","B":"若干的責任保障","C":"若干的經濟權益保障","D":"上述所有各項"}'::jsonb, 'D', '一般家居保險單包括承保被保險人的建築物及/或其內部的物品經濟權益保險、作為身處香港任何地方的私人，向第三者承擔的法律責任。'),
('p2', 119, '一', '一般保險產品類別', '120. 家居保險為下列哪項提供保障？
i. 個人意外權益
ii. 財產保障
iii. 經濟權益
iv. 責任保障', '{"A":"i, ii, iii","B":"i, iii, iv","C":"ii, iii, iv","D":"i, ii, iii, iv"}'::jsonb, 'D', '四項均為家居保險之保障範圍。'),
('p2', 120, '一', '一般保險產品類別', '121. 家居保險一般是由下列哪個保險部簽發的？', '{"A":"火險","B":"意外保險","C":"汽車保險","D":"人壽及健康保險"}'::jsonb, 'A', '家居保險是私人保險(有時稱為個人或私人險種)中的主要成員，很多保險公司是透過其火險部門或財產保險部門來承保這項業務的。'),
('p2', 121, '一', '一般保險產品類別', '122. 家居保險的主要保障範圍是：', '{"A":"建築物及/或家居物件","B":"向第三者承擔的法律責任","C":"由受保危險引致的額外損失或另覓住宿開支","D":"人身意外的保障"}'::jsonb, 'A', '家居保險主要是提供財產保險，所承保的是屬於被保險人的建築物及／或其內部的物品。'),
('p2', 122, '一', '一般保險產品類別', '123. 住宅物業的業主及住客較可能投保以下哪類保單？', '{"A":"火險保單而已","B":"家居物件保單而已","C":"建築物保單","D":"建築物及家居物件保單"}'::jsonb, 'D', '業主及租客將選擇建築物及家居物件保險保障 -建築物(業主:大廈結構)及家居物件(租客)。'),
('p2', 123, '一', '一般保險產品類別', '124. 保障家居物件的保險較適合：', '{"A":"按揭人的銀行","B":"房東","C":"租客","D":"業主或住客"}'::jsonb, 'C', '租客相對選擇為家居財物提供保障。'),
('p2', 124, '一', '一般保險產品類別', '125. 只就物業的損失或損毀提供保障的家居保單適合：', '{"A":"租客","B":"房東","C":"業主及住客","D":"擔任該物業按揭的銀行"}'::jsonb, 'B', '業主//房東將選擇建築物(大廈結構)之保險保障。'),
('p2', 125, '一', '一般保險產品類別', '126. 以下哪項屬於家居保險保單中的指明危險？', '{"A":"火災造成的損失；","B":"盜竊造成的損失；","C":"颱風造成的損失；","D":"以上所有各項"}'::jsonb, 'D', '家居保險主要是提供財產保險，所承保的是屬於被保險人的建築物及／或其內部的物品。同時指明危險中保障必定承保火災，並進而包含火險中大部分（若非所有）可保的附加危險。（附加危險的項目很多，包括風暴／旋風、地震、爆炸、動物／被汽車碰撞等）。除此之外，盜竊引起的損失或損害也包括在內。'),
('p2', 126, '一', '一般保險產品類別', '127. 以下哪項不屬於家居保險的保障範圍？', '{"A":"火災","B":"暴亂","C":"爆炸","D":"失竊"}'::jsonb, 'B', '戰爭、暴亂及類似風險屬除外責任。'),
('p2', 127, '一', '一般保險產品類別', '128. 一個物業在特定期間內空置，家居保單通常會暫停提供保障。這段期間為:', '{"A":"48小時","B":"1星期","C":"30天","D":"60天"}'::jsonb, 'C', '有關處所連續空置超過比如 30天，保單通常會暫停承保盜竊和洗衣機等漏水。其實，家居保險單一般規定，被保險人必須就超過比如 30天的可預見空置期，向保險人發出書面通知。'),
('p2', 128, '一', '一般保險產品類別', '129. 如果投保額一百萬，而實際價值是二百萬，但真正損失是一百萬，賠償額應該是：', '{"A":"一百萬","B":"二百萬","C":"因投保不足，故不作賠償作為懲罰","D":"五十萬(計算比例分攤)"}'::jsonb, 'D', '當保費是按照由被保險人自選的保額計算時，保單條款中會包括一項比例分攤條件，規定如果損失發生時出現了不足額保險的情況，被保險人就不會就全數損失獲得保障。為價值200萬的物件投保100萬是物件的50%價值，所以賠償時只會獲得損失總額的50%。'),
('p2', 129, '一', '一般保險產品類別', '130. 旅遊保險通常歸類於：', '{"A":"指明保險","B":"渡假保險","C":"「全險」","D":"一籃子保單"}'::jsonb, 'D', '旅遊保險單視為了有多年歷史的「一籃子」保單。'),
('p2', 130, '一', '一般保險產品類別', '131. 以下哪項屬旅遊保險所保障的範圍？', '{"A":"投保人自殺","B":"使用汽車時所引致的責任","C":"於酒店酒吧中因損壞財物引致的責任","D":"以上所有各項"}'::jsonb, 'C', '旅遊保險保障行李及個人財物丟失/受損害，而自殺及使用汽車均不是保障範圍內。'),
('p2', 131, '一', '一般保險產品類別', '132. 在本港簽發的旅遊保單中，以下哪種情況較可能/或會得到保障？', '{"A":"乘飛機時導致行李遺失","B":"旅遊期間治療胃病的醫療開支","C":"旅遊期間因盜賊行劫導致的財物損失","D":"以上所有各項"}'::jsonb, 'D', '旅遊保險保障行李及個人財物丟失/受損害及醫療費用及住院保險利益。'),
('p2', 132, '一', '一般保險產品類別', '133. 一般在香港簽發的旅遊保險單，以下哪項較不可能得到保障？', '{"A":"自然死亡","B":"個人公眾責任","C":"個人行李的遺失及偷竊","D":"由意外所引起的醫療費用"}'::jsonb, 'A', '自然死亡不是保障範圍內。'),
('p2', 133, '一', '一般保險產品類別', '134. 下列哪項是旅遊保險的保障範圍？
i. 醫療開支
ii. 損失訂金
iii. 公眾責任保障
iv. 送返開支', '{"A":"i & iii","B":"i & ii","C":"以上全部正確","D":"以上全部不正確"}'::jsonb, 'C', '旅遊保險保障醫療費用及住院保險利益、個人責任及緊急服務。'),
('p2', 134, '一', '一般保險產品類別', '135. 以下哪項較可能是一般於香港簽發的旅遊保險的除外責任？', '{"A":"被保險人於空中撞機身亡","B":"被保險人於渡假時自殺身亡","C":"被保險人的行李於酒店房間遭盜竊","D":"被保險人於渡假期間失足墮下所引起的醫療開支"}'::jsonb, 'B', '自然死亡不是保障範圍內。'),
('p2', 135, '一', '一般保險產品類別', '136. 以下哪項很可能不屬於責任保險組合保單的範圍？', '{"A":"公眾責任","B":"產品責任","C":"汽車責任","D":"僱員補償責任"}'::jsonb, 'C', '責任保險組合保單通常在一份文件內提供公衆責任、產品責任和僱員補償等三種障。個別客戶也可能需要董事及高級管理人員責任及/或專業責任保險保障。'),
('p2', 136, '一', '一般保險產品類別', '137. 以下哪項不是旅遊保險的保費計算考慮因素?', '{"A":"旅遊目的地區範圍","B":"旅遊日數","C":"被保險人的性別 (男性 / 女性)","D":"同行人數"}'::jsonb, 'C', '旅遊保險釐定保費的根據:地域範圍、持續時間、受保人數目及年度保單。'),
('p2', 137, '一', '一般保險產品類別', '138. 旅遊保險的「總保險單」相當可能與以下哪項有關？', '{"A":"一個大的個別保額","B":"高級行政人員的保險","C":"旅遊代理人提供的「度假套餐」有關","D":"海上旅遊的保險"}'::jsonb, 'C', '「總保單」：向很多安排度假「套餐」的旅行代理商簽發「總保單」是一種頗為普遍的做法，而個別客戶只會收到一張略述主要保險條文的保險憑證。'),
('p2', 138, '一', '一般保險產品類別', '139. 保險人對旅遊保單的核保：', '{"A":"必須很徹底，因為受保範圍較廣","B":"至少比個人意外保險的核保徹底","C":"甚少出現個別的風險核保","D":"與人壽保險的準則相符"}'::jsonb, 'C', '旅遊保險的特點是盡量將一切都簡單化，因為人們通常在最後關頭才去投保，而且不能做到「用家方便」的產品很難在這種大型的市場中取得成功。所以，甚少對風險個別地進行核保。'),
('p2', 139, '一', '一般保險產品類別', '140. 以下哪項對於商業組合保單的描述是正確的：', '{"A":"流行程度頗低","B":"市場上極為罕見","C":"在法律上是禁止的","D":"目前已較普遍"}'::jsonb, 'D', '商業組合保單可以是度身訂造保單，包括提供公衆責任、產品責任和僱員補償等三種保障，現時這類保障已較普遍。'),
('p2', 140, '一', '一般保險產品類別', '141. 商業保險組合的保險範圍包括：', '{"A":"財產保險的保障","B":"經濟權益保險的保障","C":"責任保險的保障","D":"以上所有各項"}'::jsonb, 'D', '這類保障可以包括任何類型的保障，包括財產、經濟權益及責任風險。'),
('p2', 141, '一', '一般保險產品類別', '142. 以下哪項屬於商業保險組合保單的特點？', '{"A":"它通常以「全險」形式為財產提供保障","B":"它可以在保費上累積一定的減省","C":"它在文件上提供一定程度上的方便","D":"以上所有各項"}'::jsonb, 'D', '這種保單傾向於提供「全險」保險保障，在同一張保單下提供實物損害和營業中斷保障，通常在一份文件內提供公衆責任、產品責任和僱員補償等三種保障。個別客戶也可能需要董事及高級管理人員責任及／或專業責任保險保障。同時被保險人共同追求的不僅是一份保單就能提供多種保險保障的方便，還期望能整體上節省保費。'),
('p2', 142, '一', '一般保險產品類別', '143. 包含財產及經濟權益保障的商業組合保單，通常用以下哪項形式提供財產保險保障？', '{"A":"全險","B":"約定價值","C":"指明危險","D":"火災及盜竊"}'::jsonb, 'A', '保單傾向於提供「全險」保險保障，在同一張保單下提供實物損害和營業中斷保障，通常在一份文件內提供公衆責任、產品責任和僱員補償等三種保障。'),
('p2', 143, '一', '一般保險產品類別', '144. 以下哪項不是向大型機構所提供的「傘括」類型組合保障的特點？', '{"A":"只提供財產及責任的保障","B":"可按被保險人的需要而個別草擬","C":"提供財產保障以全險為根據","D":"包括大部份保險類別(財產、責任等)"}'::jsonb, 'A', '這類保障可以包括任何類型的保障，包括財產、經濟權益及責任風險。'),
('p2', 144, '一', '一般保險產品類別', '145. 典型商業保險組合保單提供的責任保險組合保單，保障較可能包括：', '{"A":"汽車、公眾責任及產品責任","B":"公眾責任、產品責任及經濟權益","C":"公眾責任、產品責任及僱員補償(法定)責任","D":"專業責任、經濟權益責任及財產責任"}'::jsonb, 'C', '這類保單通常在一份文件內提供公衆責任、產品責任和僱員補償等三種保障。個別客戶也可能需要董事及高級管理人員責任 及／或專業責任保險保障。'),
('p2', 145, '一', '一般保險產品類別', '146. 以下哪項或哪些是旅遊保險釐定保費的因素？', '{"A":"地域範圍","B":"持續時間","C":"受保人數目","D":"以上各項皆是"}'::jsonb, 'D', '所有以上的答案均為計算保費的因素。'),
('p2', 146, '一', '一般保險產品類別', '147. 旅遊保險屬於那一種保險：', '{"A":"個人保險","B":"責任保險","C":"「全險」","D":"一籃子保單"}'::jsonb, 'D', '旅遊保險單視為了有多年歷史的「一籃子」保單。'),
('p2', 147, '一', '一般保險產品類別', '148. 在本港，向房東租用私人單位的租客，較可能購買:', '{"A":"商業火險","B":"家居財物保單而已","C":"家居建築物保單而已","D":"家居建築物及財物保單"}'::jsonb, 'B', '租客將選擇家居物件保險保障 。'),
('p2', 148, '一', '一般保險產品類別', '149. 在本港，向房東租用私人單位的租客，較有可能購買', '{"A":"商業火險","B":"純家居物件保險保障而已","C":"家居建築物保險保障 而已","D":"家居建築物及財物保險保障"}'::jsonb, 'B', '作為租客，家居物品為租客主要保障範圍。'),
('p2', 149, '一', '一般保險產品類別', '150. 旅遊保險通常歸類於：', '{"A":"指明保險","B":"責任保險","C":"一籃子保單","D":"組合保險"}'::jsonb, 'C', '旅遊保險單視為了有多年歷史的「一籃子」保單。'),
('p2', 150, '一', '一般保險產品類別', '151. 某一中式酒樓發生火災，火勢蔓延至樓上的單位，結果，林先生的單位嚴重受損，該單位是有火險單保障的。為甚麼你認為林先生的損失不獲保單賠償？', '{"A":"林先生的損失可獲保單賠償","B":"首保住處不首先起火","C":"沒有發生保單所指的“火”","D":"只要受保住處訂定義被包括該中式酒樓，林先生便可獲得賠償"}'::jsonb, 'A', '火災無須在受保處所燃燒，因此，在鄰近物業燃燒並符合以上定義的火災所產生的熱量、煙或水進而對受保財產造成的損害，也可構成有效的火災索償。'),
('p2', 151, '一', '一般保險產品類別', '152. 在火險保單當中，爆炸引致的損失是：', '{"A":"所有爆炸的損失是屬於基本保單所保障的","B":"必定屬於除外責任","C":"某些情況下爆炸引致的損失是受保的(例如：家用氣體爆炸)","D":"所有爆炸的損失要得到保障，必須額外繳付保費"}'::jsonb, 'C', '雖然在標準火險保單中，爆炸是一項除外的危險，但有關的除外責任條款載明不適用於作家居用途的氣體（或鍋爐）的爆炸這項受保危險，所導致的損害。'),
('p2', 152, '一', '一般保險產品類別', '153. 以下哪項不屬於火險保單中的附加危險？', '{"A":"熱帶氣旋","B":"地震","C":"閃電","D":"暴亂"}'::jsonb, 'C', '閃電：不管火災是否隨後發生，是保障範圍內。'),
('p2', 153, '一', '一般保險產品類別', '154. 根據本港商業火險保單，保障範圍包括以下哪項？
i. 因火災直接對財產造成毀壞
ii. 並未產生火災的閃電毀壞
iii. 因消防員嘗試用水撲滅火警而造成的毀壞在有關場所內，因意外火警產生的濃煙，對存貨造成毀壞', '{"A":"i, ii","B":"i, ii, iii","C":"ii, iii, iv","D":"i, ii, iii, iv"}'::jsonb, 'D', '火災、閃電、因救火所導致損失及濃煙影響也是保障範圍內。'),
('p2', 154, '一', '一般保險產品類別', '155. 在商業保單中，火災的定義為：', '{"A":"只限於發生在受保建築物中的火災","B":"不局限於受保建築物中的火災","C":"不包括由其他人故意引起的火災","D":"只限於由受保人引起的火災"}'::jsonb, 'B', '火災無須在受保處所燃燒，因此，在鄰近物業燃燒並符合以上定義的火災所產生的熱量、煙或水進而對受保財產造成的損害，也可構成有效的火災索償。'),
('p2', 155, '一', '一般保險產品類別', '156. 「火災」的定義是：', '{"A":"一些不應起火但起火的物件","B":"實際的燃燒","C":"非由被保險人故意引起或安排","D":"以上所有各項"}'::jsonb, 'D', '火災、無須在受保處所燃燒及不是由被保險人故意引起或安排的都是保障範圍內。'),
('p2', 156, '一', '一般保險產品類別', '157. 以下哪項屬於火災保單中的保障項目？', '{"A":"消防員用水救火造成的損失","B":"閃電引致的非火災損失","C":"閃電引致的火災","D":"以上各項都是"}'::jsonb, 'D', '火災、閃電、因救火所導致損失及濃煙影響也是保障範圍內。'),
('p2', 157, '一', '一般保險產品類別', '158. 以下那項情況為火險的基本保障範圍？', '{"A":"於烘麵包時燒焦麵包","B":"火災後因消防人員救火時造成的財物損毀","C":"戰爭中所做成的火災","D":"因自己故意放火做成的火災"}'::jsonb, 'B', '因救火所導致損失也是保障範圍內。'),
('p2', 158, '一', '一般保險產品類別', '159. 以下哪項對閃電發生所引致的火警的描述是正確的？', '{"A":"是除外責任","B":"不是除外責任","C":"是一種特殊危險，但可以除外危險作附加保障","D":"是一個基本風險，包括在保單的保障範圍內"}'::jsonb, 'B', '閃電引起的火災是保障範圍內。'),
('p2', 159, '一', '一般保險產品類別', '160. 由火引起的水、熱力及煙所造成的損毀，以下哪一項在一般的火險單中是會得到保障？', '{"A":"若火災是由建築物當中引起的","B":"若所有損毀與第三者無關","C":"若火警發生的近因是火災","D":"若火災與第三者損失有關"}'::jsonb, 'C', '如果火災（如上文所界定的）是近因，那麽「火災」損害便包括由煙、熱力，以及撲救火災時用的水引致的損害。由消防隊或其他人在撲滅火災的過程中合理地造成的損害，也在保障範圍之內。'),
('p2', 160, '一', '一般保險產品類別', '161. 根據基本火災保單，下列哪一項是正確的？', '{"A":"只有由火災引起的爆炸是可保的","B":"沒有由火災引起的爆炸是可保的","C":"由家用氣體產生的爆炸，是除外責任不適用的","D":"只有家用氣體產生的爆炸屬除外責任"}'::jsonb, 'C', '雖然在標準火險保單中，爆炸是一項除外的危險，但有關的除外責任條款載明不適用於作家居用途的氣體（或鍋爐）的爆炸這項受保危險，所導致的損害。'),
('p2', 161, '一', '一般保險產品類別', '162. 在一般基本的商業火險保單，以下哪項對爆炸危險的說明是不正確的？', '{"A":"包括在除外危險","B":"家居氣體爆炸是得到保障的","C":"就算繳交額外保費，要得到所述之保障是不可能的","D":"以上所有各項"}'::jsonb, 'C', '雖然在標準火險保單中，爆炸是一項除外的危險，但有關的除外責任條款載明不適用於作家居用途的氣體（或鍋爐）的爆炸這項受保危險，所導致的損害。'),
('p2', 162, '一', '一般保險產品類別', '163. 以下哪項不屬於附加於本港簽發的商業火險單中「附加危險」的替代用詞?', '{"A":"擴展危險","B":"類似危險","C":"特殊危險","D":"補充危險"}'::jsonb, 'D', '附加危險：也稱為特殊危險、類似危險或擴展危險。'),
('p2', 163, '一', '一般保險產品類別', '164. 因爆炸所引起的火災損失，所進行賠償的項目為：', '{"A":"不會接受賠償","B":"全部接受賠償","C":"家庭氣體燃料爆炸所造成的損失","D":"所有因爆炸導致的損失，但不包括因爆炸而造成的火災所導致的損失"}'::jsonb, 'C', '雖然在標準火險保單中，爆炸是一項除外的危險，但有關的除外責任條款載明不適用於作家居用途的氣體（或鍋爐）的爆炸這項受保危險，所導致的損害。'),
('p2', 164, '一', '一般保險產品類別', '165. 商業火險中，可以繳付額外保費而擴展成為標準保障的危險稱為：', '{"A":"附加危險","B":"特殊危險","C":"擴展危險","D":"上述任何名稱"}'::jsonb, 'D', '附加危險：也稱為特殊危險、類似危險或擴展危險。'),
('p2', 165, '一', '一般保險產品類別', '166. 火險保單中，自負額適用於：', '{"A":"火災引致之損失","B":"由閃電做成火災損失","C":"由閃電做成的非火災損失","D":"由附加危險引致之損失"}'::jsonb, 'D', '自負額：用於基本保障（即火災、閃電和「狹義的」爆炸）中的自負額並不多見，然而，某些附加危險的保障設有標準的自負額。'),
('p2', 166, '一', '一般保險產品類別', '167. 一般火險保單大多數按比例分攤的方法賠償,意思是:', '{"A":"當損失出現於不足額保障時,被保險人得不到足額賠償","B":"當損失出現於不足額保障時,保單便屬無效","C":"財產價值是按市場價值來釐定","D":"保單費用是按市面上的平均數來釐定"}'::jsonb, 'A', '比例分攤條件：財產保險通常要求全額投保；在理賠時會對不足額保險的情況作出懲罰。'),
('p2', 167, '一', '一般保險產品類別', '168. 火險的保費是根據每一百元收0.1元的保費，若保額是五百萬，保費應為？', '{"A":"五十元","B":"五百元","C":"五千元","D":"五萬元"}'::jsonb, 'C', '$100/$0.1 = 1000倍$5,000,000/1000倍 = $5000'),
('p2', 168, '一', '一般保險產品類別', '169. 以下哪項是火險保單的計算根據？', '{"A":"被保險人所付出的工資","B":"生意的營業額","C":"保障的時間","D":"保障物件的價值及保障時間因素計算附加費"}'::jsonb, 'D', '須按各自的相對風險對財產進行分類，然後再根據個別的特點（比如受保建築物的高度、偏僻或就近程度及救火設施），適當地提高或降低保費。'),
('p2', 169, '一', '一般保險產品類別', '170. 以下哪項不是商業火險的常見的標的物？', '{"A":"建築物","B":"營業存貨","C":"辦公室家具","D":"機器"}'::jsonb, 'C', '建築物、營業存貨及機器為常見的受保財產。'),
('p2', 170, '一', '一般保險產品類別', '171. 以下哪項是營業中斷保險的保障範圍？', '{"A":"淨利潤","B":"毛利潤","C":"建築物外牆之損毀","D":"以上所有各項"}'::jsonb, 'B', '因受保危險而導致的毛利潤（按保單定義）損失。'),
('p2', 171, '一', '一般保險產品類別', '172. 以下哪項是火災營業中斷保險可以提供補償的範圍？', '{"A":"毛利潤(按保單的定義)","B":"工資(有時包括毛利的計算)","C":"由受保危險引致的必要附加費用","D":"以上各項都是"}'::jsonb, 'D', '因受保危險而導致的毛利潤（按保單定義）損失、因受保危險而導致的必要和合理的附加費用及營業中斷期間支付的工資為保險範圍內。'),
('p2', 172, '一', '一般保險產品類別', '173. 以下哪項不是火災營業中斷保險的保障範圍？', '{"A":"由受保危險引起的毛利損失","B":"在營業中斷期間支付的工資","C":"因火災引致的財產損毀","D":"由受保危險引致的附加開支"}'::jsonb, 'C', '火災營業中斷保險則給他就火災等的另類後遺影響（如利潤損失、額外的費用等）提供補償。'),
('p2', 173, '一', '一般保險產品類別', '174. 選擇以下那句是正確:', '{"A":"附加危險是非火災的風險，但習慣加在火險單上","B":"「全險」保險保障每一種損失","C":"汽車保險局是一個中央基金，去賠償所有交通意外的傷者","D":"僱員補償條例令僱主要為僱員所有受傷負責"}'::jsonb, 'A', '附加危險難以說是與火災、閃電和「狹義的」爆炸這些基本危險相似，但傳統上可多付保費從而附加投保。'),
('p2', 174, '一', '一般保險產品類別', '175. 以下哪項屬於火災營業中斷保險的描述是正確的？
i. 有效的索償必須提供財產損毀保證
ii. 是屬於一種權益保險
iii. 會對於所有收入提供保障
iv. 必須向同一保險人購買火險才獲保障', '{"A":"i, ii","B":"i, iii","C":"ii, iii","D":"iii, iv"}'::jsonb, 'A', '這是一種經濟權益保險，它與火險有別但卻又密切相關。火險就有形財產的損失或損害向被保險人提供彌償，火災營業中斷保險則給他就火災等的另類後遺影響（如利潤損失）提供補償。當然，營業中斷保險是可以連同其他種類的實物損害保障（比如海上保險保障）購買的。'),
('p2', 175, '一', '一般保險產品類別', '176. 在火災營業中斷保單索償中，就火災營業中斷保單中，必須有另一張保單保證，此保單為:', '{"A":"火災損毀保證","B":"實物損害保障","C":"財產損失保單保證","D":"以上所有各項"}'::jsonb, 'B', '火災營業中斷保單中須證明實物損害保障了同一位保單持有人的權益。'),
('p2', 176, '一', '一般保險產品類別', '177. 典型的營業中斷保單規定引致營業中斷的財產損害，必須有另一保單予以賠償。 這項保單條文一般稱為:', '{"A":"火災損害保證","B":"實物損害附帶條件","C":"財產損害保險要求","D":"強制財產保險條件"}'::jsonb, 'B', '典型的實物損害附帶條件規定，如果沒有實物損害保險保障了同一位保單持有人的利益，或相關的實物損害保險人既不承認責任亦不賠付引致營業中斷的實物損害的話，營業中斷保單就不會作出賠償。'),
('p2', 177, '一', '一般保險產品類別', '178. 營業中斷保險的保費是根據承保的時間加上甚麼來計算的？', '{"A":"建築物的價值","B":"火險單中的保費率","C":"建築物室內物件的價值","D":"租金的價值"}'::jsonb, 'B', '計算這種保險的保費是複雜的，首先以火險中建築物室內物件的保險費率作為基本費率，然後再根據保障的相關時間因素來計算附加費。'),
('p2', 178, '一', '一般保險產品類別', '179. 影響營業中斷保險的保費計算是受著中斷期間的時段及：', '{"A":"火險對建築物徵收的保費率","B":"火險中替建築物其室內物件的保險費率","C":"毛利損失的保障額","D":"中段期間所支付的工資額"}'::jsonb, 'B', '計算這種保險的保費是複雜的，首先以火險中建築物室內物件的保險費率作為基本費率，然後再根據保障的相關時間因素來計算附加費。'),
('p2', 179, '一', '一般保險產品類別', '180. 營業中斷保險是為「利潤」作出保障，它亦稱為：', '{"A":"中斷賠償","B":"損失利潤保障","C":"後果損失保險","D":"中斷期間"}'::jsonb, 'C', '「營業中斷保險」是該險種最為趨時的名稱，但是有時也稱為「後果損失保險」或「利潤損失保險」。'),
('p2', 180, '一', '一般保險產品類別', '181. 一種經濟權益保單，起初是以“利潤保單”來形容及後稱為：', '{"A":"利潤損失保險","B":"後果損失保險","C":"營業中斷保險","D":"以上各項皆是"}'::jsonb, 'D', '「營業中斷保險」是該險種最為趨時的名稱，但是有時也稱為「後果損失保險」或「利潤損失保險」。'),
('p2', 181, '一', '一般保險產品類別', '182. 火災營業中斷保險保單條款中，如受保危險發生後，可得到保障一段時間，這段時間稱為：', '{"A":"事件後保險期間","B":"保單日期","C":"保障期間","D":"中斷期間"}'::jsonb, 'D', '營業中斷保險而言，損失分散在接着受保意外事故的發生的一段時間內，必須為明確保單責任而給「中斷期間」（或彌償期間）設置期限。'),
('p2', 182, '一', '一般保險產品類別', '183. 大部份財產保險有為特定危險所造成之損失提供保障。此外，還有哪一類常見之保障？', '{"A":"全險","B":"指定危險","C":"單一危險","D":"非指定危險"}'::jsonb, 'A', '財產保障其中常見的為「全險」保障。'),
('p2', 183, '一', '一般保險產品類別', '184. 按照「全險」保險單，以下哪項是會得到賠償？', '{"A":"意外火災引起的損失","B":"意外中遺失的一件珠寶","C":"被保險人被賊人用槍指嚇而被偷竊的手錶","D":"以上所有各項"}'::jsonb, 'D', '「全險」的意思是所有損失或損害均屬保障範圍内，具體豁免保障者則除外。一旦被保險人證明了受保財產的意外損失或損害後，保險人若要拒賠，便有法律責任證明某項除外責任是適用的。'),
('p2', 184, '一', '一般保險產品類別', '185. 有些財產保險都用「全險」的形式作保障，「全險」是指：', '{"A":"沒有任何除外責任","B":"任何想像到的危險都可得到保障","C":"除非屬於特定除外，否則所有損失或損壞都可得到保障","D":"在指定名單上的危險才可得到保障，其他則屬除外"}'::jsonb, 'C', '「全險」的意思是所有損失或損害均屬保障範圍内，具體豁免保障者則除外。一旦被保險人證明了受保財產的意外損失或損害後，保險人若要拒賠，便有法律責任證明某項除外責任是適用的。'),
('p2', 185, '一', '一般保險產品類別', '186. 「全險」保險通常是以引號來表達是因為:', '{"A":"它是可以提供最全面的財產保障","B":"仍然有一些風險不能保障","C":"是最新的財產保險","D":"它沒有指示投保哪一種財產"}'::jsonb, 'B', '「全險」的意思是所有損失或損害均屬保障範圍内，具體豁免保障者則除外。一旦被保險人證明了受保財產的意外損失或損害後，保險人若要拒賠，便有法律責任證明某項除外責任是適用的。'),
('p2', 186, '一', '一般保險產品類別', '187. 就「全險」保單而言，比例分攤是：', '{"A":"從不適用","B":"總是適用","C":"通常適用於分開描述的項目上","D":"通常不適用於分開描述的項目上"}'::jsonb, 'D', '如果保障範圍包括了不指明物件，那麽有關保障就相當可能適用比例分攤條款。'),
('p2', 187, '一', '一般保險產品類別', '188. 以下哪項不屬於「全險」保障的一般除外責任？', '{"A":"損耗","B":"折舊","C":"被保人的粗心大意所引致的損失","D":"基於逐漸運作而引起的損失（例如：生鏽）"}'::jsonb, 'C', '「全險」的意思是所有損失或損害均屬保障範圍内，具體豁免保障者則除外。'),
('p2', 188, '一', '一般保險產品類別', '189. 比例分攤在「全險」的保單當中是：', '{"A":"經常適用","B":"經常適用於指明的物件","C":"經常適用於未有指明的物件","D":"完全不適用"}'::jsonb, 'C', '如果保障範圍包括了不指明物件，那麽有關保障就相當可能適用比例分攤條款。'),
('p2', 189, '一', '一般保險產品類別', '190. 「全險」的保費一般是根據兩方面而釐訂。其一是保額，另一方面則是：', '{"A":"被保人的性別","B":"被保人的居住地區","C":"受保障的地區範圍","D":"被保人的年齡"}'::jsonb, 'C', '保費必然是根據保額的一定比率來計算的。同時，受保障的地區範圍不同，保險費率便會有所不同（全球保障的保費自然是最高的）。'),
('p2', 190, '一', '一般保險產品類別', '191. 「全險」保障中為貴重物品提供「約定價值」保障是指：', '{"A":"就各項損失的支付金額均在事前議定","B":"全損索償金額均在事前議定","C":"部份損失索償金額均在事前議定","D":"對每項及各項的索償，保額與最低支付金額相同"}'::jsonb, 'B', '以「全險」方式承保貴重物品這個本來意圖仍然重要。給貴重物品承保「全保」，通常採用約定價值保障，而相關保額或約定價值相當可能是依據獨立而專業的估值來釐訂的。'),
('p2', 191, '一', '一般保險產品類別', '192. 下列哪項或哪些對全險保單中的「約定價值」條款的評論是正確的？', '{"A":"它一般涉及貴重物品〈如古董花瓶〉","B":"全損時按保額賠付","C":"於保單開始時一般涉及專業估值","D":"上述所有各項"}'::jsonb, 'D', '以「全險」方式承保貴重物品這個本來意圖仍然重要。給貴重物品承保「全保」，通常採用約定價值保障，而相關保額或約定價值相當可能是依據獨立而專業的估值來釐訂的。'),
('p2', 192, '一', '一般保險產品類別', '193. 由竊匪引致的損毀於商業盜竊保險中是屬於：', '{"A":"基本的除外責任","B":"保單中的保障範圍(涉及火災的損毀則除外)","C":"所有這類的損毀都自動成為保障範圍","D":"若額外附加保費，便成為可保的風險"}'::jsonb, 'B', '商業盜竊保險承保由盜竊或企圖盜竊導致的損失或損害。'),
('p2', 193, '一', '一般保險產品類別', '194. 以下哪項會受到基本盜竊保險的保障？', '{"A":"串同職員盜竊的款項","B":"賊人由沒有鎖上及已開啟的門入內盜竊的損失","C":"意圖毀滅証據而放火所導致的損毀","D":"以上所有各項都不是"}'::jsonb, 'D', '保單通常有保由於盜賊以強行及暴力方式進入（或離開）受保處所而引致的損害。'),
('p2', 194, '一', '一般保險產品類別', '195. 大多數的盜竊保險只限於商業風險的保障，其保障範圍包括：', '{"A":"因盜賊引起的損毀","B":"以強行及暴力的方式進入或離開有關物業","C":"因盜竊而產生的實際損失","D":"以上所有各項"}'::jsonb, 'D', '商業盜竊保險承保由盜竊或企圖盜竊導致的損失或損害。'),
('p2', 195, '一', '一般保險產品類別', '196. 大多數盜竊保險的保障範圍屬於：', '{"A":"個人的風險","B":"第三者的傷害","C":"商業風險的保障","D":"家庭的保障"}'::jsonb, 'C', '獨立存在的盜竊保單主要只用於商業風險。'),
('p2', 196, '一', '一般保險產品類別', '197. 在本港簽發「商業盜竊保險單」，會提供以下哪項保障？', '{"A":"因盜竊而造成火災損毀","B":"因盜竊而造成非火災損毀","C":"向因盜竊而造成傷害的職員提供個人意外權益","D":"以上所有各項"}'::jsonb, 'B', '商業盜竊保險承保由盜竊或企圖盜竊導致的損失或損害。竊賊縱火以毀滅盜竊證據這種事情間中會發生，但是，在盜竊保單中，由火災引起的損害屬於除外責任的範圍。'),
('p2', 197, '一', '一般保險產品類別', '198. 商業盜竊險涉及下列哪項或哪些？', '{"A":"它屬於全險類別","B":"匪徒於盜竊後縱火所引致的損失屬除外責任","C":"它要求是強行及暴力方式進入或離開受保處所","D":"上述所有各項均符合"}'::jsonb, 'D', '商業盜竊保險是「全險」的一類，承保由盜竊或企圖盜竊導致的損失或損害。竊賊縱火以毀滅盜竊證據這種事情間中會發生，但是，在盜竊保單中，由火災引起的損害屬於除外責任的範圍。'),
('p2', 198, '一', '一般保險產品類別', '199. 以下哪項對於盜竊保險的描述是不正確的？', '{"A":"盜竊必須以強行及暴力的方式進行或離開","B":"向盜賊引起被保險人財產的損毀提供保障","C":"向由火災引起的損毀是受到保障的","D":"這業務的原來名稱為「入屋犯法」"}'::jsonb, 'C', '商業盜竊保險承保由盜竊或企圖盜竊導致的損失或損害。竊賊縱火以毀滅盜竊證據這種事情間中會發生，但是，在盜竊保單中，由火災引起的損害屬於除外責任的範圍。'),
('p2', 199, '一', '一般保險產品類別', '200. 本港盜竊保險早期的名稱為：', '{"A":"盜竊保障","B":"入屋盜竊保險","C":"刑事盜用","D":"忠誠保障保險"}'::jsonb, 'B', '這類業務的原來名稱是入屋盜竊保險，香港可能還有保險人仍然使用這個名稱。'),
('p2', 200, '一', '一般保險產品類別', '201. 以下哪項屬於玻璃保險的描述？', '{"A":"它以「全險」方式提供保障","B":"通常以維修方法處理","C":"玻璃破裂屬於除外責任","D":"以上各項皆是"}'::jsonb, 'A', '玻璃保險提供「全險」保險保障，範圍不僅包括被保固定玻璃的碎裂，還包括暫時用圍板擋住被保處所所需的任何費用。'),
('p2', 201, '一', '一般保險產品類別', '202. 一般「玻璃保險單」中，提供以下哪項保障？', '{"A":"因火災對受保玻璃的損毀","B":"對受影響的物業進行圍板工程","C":"因被破裂玻璃弄傷的職員提供「個人意外權益」","D":"以上所有各項"}'::jsonb, 'B', '玻璃保險提供「全險」保險保障，範圍不僅包括被保固定玻璃的碎裂，還包括暫時用圍板擋住被保處所所需的任何費用。'),
('p2', 202, '一', '一般保險產品類別', '203. 以下哪項會於玻璃保險中得到保障？', '{"A":"與戰爭有關的損毀","B":"由火災引起的損毀","C":"由一輛車子翻起的石子引致玻璃碎裂","D":"由一名小偷打碎玻璃後遭盜竊的存貨"}'::jsonb, 'C', '玻璃保險提供「全險」保險保障，範圍不僅包括被保固定玻璃的碎裂，還包括暫時用圍板擋住被保處所所需的任何費用。'),
('p2', 203, '一', '一般保險產品類別', '204. 以下哪項不屬於玻璃保險的除外責任？', '{"A":"火災","B":"核子","C":"受到汽車撞擊","D":"以上各項"}'::jsonb, 'C', '火災可由火險保單承保的風險，例如火災、風暴、地震等都被豁免承保。戰爭、核風險、恐怖主義等同屬除外責任。'),
('p2', 204, '一', '一般保險產品類別', '205. 以下哪項引致玻璃碎裂的事項，是在基本的玻璃保單中不受到保障？', '{"A":"消防員尋找救火通道時弄破的玻璃","B":"遭汽車撞擊而被破壞的玻璃","C":"醉酒球迷擲汽水罐而破碎的玻璃","D":"投保人不小心弄碎的玻璃"}'::jsonb, 'A', '火災可由火險保單承保的風險，例如火災、風暴、地震等都被豁免承保。'),
('p2', 205, '一', '一般保險產品類別', '206. 玻璃保險(Glass insurance)在以下哪種情況下不受保障:', '{"A":"被汽車撞毀","B":"意外地被碎石引致碎裂","C":"被搬運中的貨物撞毀","D":"消防員尋找救火通道時弄破的玻璃"}'::jsonb, 'D', '消防員尋找救火通道時弄破的玻璃可由火險保單承保的風險。'),
('p2', 206, '一', '一般保險產品類別', '207. 玻璃保險另外一個名稱：', '{"A":"平板玻璃保險","B":"易碎物件保險","C":"不動產保險","D":"公眾責任保險"}'::jsonb, 'A', '這類業務原來稱為平板玻璃保險，香港可能還有保險人至今仍在使用這個名稱。'),
('p2', 207, '一', '一般保險產品類別', '208. 以下哪項是金錢保險的保障範圍？', '{"A":"因職員盜竊引致的損失","B":"職員運送金錢往銀行途中遭遇械劫","C":"下班後將大量金錢存放於夾萬以外的地方","D":"金錢存放於代理人家中達數星期之久"}'::jsonb, 'B', '承保對象仍然以現金運送為主，也相當可能包括其他地點（指明職員的住所、被保險人的業務處所等）的金錢。'),
('p2', 208, '一', '一般保險產品類別', '209. 金錢保單保障有效於：', '{"A":"火災中損失的金錢","B":"運送途中遭盜竊損失的金錢","C":"準備存入銀行前意外損失的金錢","D":"以上全部各項"}'::jsonb, 'B', '承保對象仍然以現金運送為主，也相當可能包括其他地點（指明職員的住所、被保險人的業務處所等）的金錢。'),
('p2', 209, '一', '一般保險產品類別', '210. 以下哪項不屬於「金錢保險」保障範圍的特點？', '{"A":"保障以「全險」的形式為基礎","B":"由職員盜竊，行為引致的金錢損失不受保障","C":"金錢的含義只限於法定貨幣，如「鈔票及硬幣」","D":"以上所有各項"}'::jsonb, 'C', '保單中的含義比其為法定貨幣的含義更為廣泛，連支票、銀行本票及其他形式的金融文件都包括在内。'),
('p2', 210, '一', '一般保險產品類別', '211. 以下哪項關於金錢保險屬正確的？', '{"A":"保障包括金錢以外的其他標的物，例如支票、匯票等","B":"只承保火災","C":"所有保單自動承保職員住處","D":"以上所有各項"}'::jsonb, 'A', '保單中的含義比其為法定貨幣的含義更為廣泛，連支票、銀行本票及其他形式的金融文件都包括在内。'),
('p2', 211, '一', '一般保險產品類別', '212. 以下哪項是計算金錢保險保單的保費根據？', '{"A":"通常是有固定保額","B":"以被保險人全年攜帶的最大金額","C":"以被保險人存放於夾萬內的最高金額","D":"通常是根據被保險人全年於銀行內往來的金額"}'::jsonb, 'D', '保費以全年進出銀行的金額的估計總數的一個比率作為標準，因此，須支付臨時保費，到取得實際金額後再作全年的調整。'),
('p2', 212, '一', '一般保險產品類別', '213. 金錢保障保險擴展後的保障包括以下哪項？', '{"A":"被賊人打劫失去的財物","B":"受僱僱員在被劫時受傷","C":"接收偽鈔的損失","D":"運送現金時做成的損失"}'::jsonb, 'B', '金錢保單中附加人身意外保險保障以承保職員因遭盜賊襲擊而受傷，是頗為普遍的做法。'),
('p2', 213, '一', '一般保險產品類別', '214. 以下哪項不是忠實保證保險的陳述：', '{"A":"必定嚴格規定與錢有關","B":"通常職員一般的錯誤及疏忽是不保的","C":"保障可以為不記名/總括","D":"以上各項皆是"}'::jsonb, 'A', '忠實保證保險屬於經濟權益保險，承保僱主因任何人在受其僱用的期間進行任何欺詐、盜竊或不誠實等行為而導致的金錢或財產損失。保單承保職員的不誠實行為，因此一般性的錯誤和疏忽是不保的。'),
('p2', 214, '一', '一般保險產品類別', '215. 受忠實保證保障的一名僱員偷竊，僱主後來取回失去的金錢，亦沒有通知保險人，其後，同一名僱員再次偷去大筆金錢，被保險人向保險公司申請索償，此索償：', '{"A":"全數可以獲得正常賠償","B":"全數不會獲得賠償","C":"可以獲得索償，但視乎是否已繳交額外保費","D":"可以獲得「通融」賠償"}'::jsonb, 'B', '保單規定被保險人必須在知悉或懷疑員工有不誠實行為後的比如 7天內，以書面形式向保險人報告，保險人會暫時中止就該員工給與的保險保障，直至情況令其滿意為止。另外，保單或會規定於上述發現之後，自動並立即停止就該名員工提供保證。'),
('p2', 215, '一', '一般保險產品類別', '216. 忠實保證保障以下那項人士？', '{"A":"一名記名之人士","B":"一系列記名人士","C":"以不記名/總括形式登記的所有員工","D":"以上所有各項"}'::jsonb, 'D', '個人保障、組合保障及不記名/總括保障均為保障的方式。'),
('p2', 216, '一', '一般保險產品類別', '217. 以下哪項對忠實保險的描述是不正確的？', '{"A":"只對挪用公款作出賠償","B":"對於由經擔保的職員作出的不誠實行為需作出申報","C":"核查及監察制度同樣屬於極為重要","D":"對沒有履行責任的員工，保證人有追償權"}'::jsonb, 'A', '忠實保證保險承保僱主因任何人在受其僱用的期間進行任何欺詐、盜竊或不誠實等行為而導致的金錢或財產損失。不誠實的僱員在法律上必須向保證人（在這裏是指保險人），就其因該名僱員的過失而作出的支付，負責作出償付。核查及監督制度這是重要的核保考慮。未經保險人的書面同意之前，已經核准的制度不能更改。'),
('p2', 217, '一', '一般保險產品類別', '218. 「保證」須就一項反擔保作保障，意思是保險人：', '{"A":"需交額外保費作保障","B":"購買再保險","C":"可為得到進一步資料，向資詢人查問","D":"在「保證」的事項上，須經保證人的董事局核實"}'::jsonb, 'D', '擔保人通常要求被保證人的董事、其母公司的董事、或其他他接受的人向他提供個人反擔保，以保障他賠付後的追償機會。'),
('p2', 218, '一', '一般保險產品類別', '219. 以下哪項對於保證保險的描述是不正確的？', '{"A":"它必須以書面形式發出","B":"必須加上印章及簽署","C":"保證的索償程序非常複雜","D":"保險人有權追討已償付的金額"}'::jsonb, 'C', '保證書上並未提及索償程序複雜'),
('p2', 219, '一', '一般保險產品類別', '220. 以下哪句子能正確地形容處理履約保證索償的情況?', '{"A":"比處理其它一般保險索償更為複雜","B":"比處理其它一般保險索償容易","C":"必須由法庭裁決","D":"以上全部都不是"}'::jsonb, 'B', '保證人如未能履行其對權利人的責任，權利人可以向擔保人索取補償，索償上不需與一般保險上了解近因及除外責任等。'),
('p2', 220, '一', '一般保險產品類別', '221. 在忠實保證或保證，「反擔保」是指一個協議去保障', '{"A":"擔保人","B":"委託人","C":"經保證的人","D":"委託人和經保證的人"}'::jsonb, 'A', '擔保人通常要求被保證人的董事、其母公司的董事、或其他他接受的人向他提供個人反擔保，以保障他賠付後的追償機會。'),
('p2', 221, '一', '一般保險產品類別', '222. 反擔保是指：', '{"A":"額外保費","B":"風險的再評估","C":"獨立諮詢代言人的保費率","D":"抵押性的保障，由承建商董事作個人擔保的保障"}'::jsonb, 'D', '保證書是個涉及三方(即被保證人)、權利人和擔保人(或保證人)的書面協議，據此，擔保人以被保證人支付一筆費用為代價，就被保證人的責任——可以是法定責任、合約責任等，向權利人提供財務保證。'),
('p2', 222, '一', '一般保險產品類別', '223. 保證是一個協議:', '{"A":"有兩方參與","B":"有三方參與","C":"單方面擔保保險公司執行","D":"以上全部都不是"}'::jsonb, 'B', '保證書是個涉及三方(即被保證人)、權利人和擔保人(或保證人)的書面協議，據此，擔保人以被保證人支付一筆費用為代價，就被保證人的責任——可以是法定責任、合約責任等，向權利人提供財務保證。'),
('p2', 223, '一', '一般保險產品類別', '224. 有一種保單，與火險有密切的關連，但承保火災後的財務影響，這種保險被冠以下列哪項或哪些名稱：', '{"A":"附加危險保險","B":"利潤中斷保險","C":"營業中斷保險","D":"以上各項"}'::jsonb, 'C', '火災營業中斷保險是一種經濟權益保險，它與火險有別但卻又密切相關。'),
('p2', 224, '一', '一般保險產品類別', '225. 以下哪項不屬於火災保險中“火”的限定？', '{"A":"實際燃燒","B":"火災必須在受保處所裡發生","C":"不應起火的實際上起火了","D":"不是由被保險人故意或引起安排的"}'::jsonb, 'B', '火災無須在受保處所燃燒，因此，在鄰近物業燃燒並符合以上定義的火災所產生的熱量、煙或水進而對受保財產造成的損害，也可構成有效的火災索償。'),
('p2', 225, '一', '一般保險產品類別', '226. 以下哪項句子對忠實保證保險是不正確的？', '{"A":"保證袛限於金錢損失","B":"核查及監督制度是核保的考慮","C":"不記名保障包括所有職員","D":"保單保障顧員不誠實行為"}'::jsonb, 'A', '承保僱主因任何人在受其僱用的期間進行任何欺詐、盜竊或不誠實等行為而導致的金錢或財產損失。'),
('p2', 226, '一', '一般保險產品類別', '227. 以下哪項就後果損失(即營業中斷)保單之計算損失的描述是不正確的？', '{"A":"基本上，它嘗試計算中斷期間之損失","B":"這是一個非常複雜過程，經常需要專業會計師協助","C":"最後數額一定不能超過中斷期間之數額","D":"與上年度出現中斷期間的收入相比"}'::jsonb, 'D', '計算彌償期間的損失首先與上年度中類似的、業務並沒有出現中斷的期間内的收入等等相比較，然後再就某些因素，比如在彌償期間內發生更激烈的市場競爭和爆發傳染病等並非由有關受保意外事故引起的事件，作出任何必要的趨勢調整。'),
('p2', 227, '一', '一般保險產品類別', '228. 可以附加於火險保單的特殊 (額外) 危險包括:
i. 地震
ii. 閃電
iii.爆炸
iv.惡意破壞', '{"A":"i,ii,iii","B":"i,iii,iv","C":"ii,iii,iv","D":"i,ii,iii,iv"}'::jsonb, 'B', '特定火險單所承保的額外危險在其承保表上指明，可包括暴動與罷工、沉降與山體滑坡、風暴與颱風、被汽車碰撞、被飛機損壞等。'),
('p2', 228, '一', '一般保險產品類別', '229. 營業中斷保險保單的釐定，是根據時間因素及:', '{"A":"受保物業的保額","B":"受保物業的保費率","C":"計算彌償期間的損失","D":"受保人選的危險數目"}'::jsonb, 'C', '在本質上計算彌償期間的損失是如此進行的：首先與上年度中類似的、業務並沒有出現中斷的期間内的收入等等相比較，然後再就某些因素比如在彌償期間內發生更激烈的市場競爭和爆發傳染病'),
('p2', 229, '一', '一般保險產品類別', '230. 物業因盜竊而損失不涉及火災是屬於：', '{"A":"除外責任","B":"是會被保障，但受保人必須已指明及已繳交保費","C":"是不會被保障，除非受保人已指明","D":"是屬於保單的保障範圍而無需繳交額外保費"}'::jsonb, 'D', '任何索償如要成功，被保處所的保安防衛物必須遭到某些破壞。通常規定，只有牽涉「以強行及暴力的方式進入或離開」被保處所的盜竊才屬保障範圍内。竊賊縱火以毀滅盜竊證據這種事情間中會發生，但是，在盜竊保單中，由火災'),
('p2', 230, '一', '一般保險產品類別', '231. 一般火險保單大多數以按比例分攤的方法賠償,意思是指:', '{"A":"當損失出現於不足保額保障時,被保險人得不到足額賠償","B":"當損失出現於不足保額保障時,保單便屬無效","C":"財產價值是按市場價值來釐定","D":"保單費用是按市面上的平均數來釐定"}'::jsonb, 'A', '比例分攤條件：財產保險通常要求全額投保；在理賠時會對不足額保險的情況作出懲罰。'),
('p2', 231, '一', '一般保險產品類別', '232. 以下哪項是營業中斷保險所承保的:', '{"A":"淨利潤","B":"毛利潤","C":"建築物外牆之損毀","D":"以上所有各項"}'::jsonb, 'B', '營業中斷保險因受保危險而導致的毛利潤（按保單定義）損失。'),
('p2', 232, '一', '一般保險產品類別', '233. 火災營業中斷保險保障範圍包括:', '{"A":"受保危險而導致的毛利潤","B":"受保危險而導致的必要和合理的附加費用","C":"營業中斷期間支付的工資","D":"以上所有各項"}'::jsonb, 'D', '以上所有各項都是火災營業中斷保險保障範圍'),
('p2', 233, '一', '一般保險產品類別', '234. 以下哪項不涉及保證書?', '{"A":"保證人","B":"權利人","C":"被保證人","D":"抵押人"}'::jsonb, 'D', '保證書涉及三方，包括被保證人、權利人及擔保人或稱作保證人'),
('p2', 234, '一', '一般保險產品類別', '235. 標準「全險」保單中，以下那一項是保障範圍?', '{"A":"意外火災引起的財產損失","B":"意外遺失一條珠寶","C":"受保人遭人帶槍威脅下損失一隻手錶","D":"以上各項皆是"}'::jsonb, 'D', '全險保險保險應用範圍已伸展到有形財產'),
('p2', 235, '一', '一般保險產品類別', '236. 火災及附加危險保單為以下哪項提供保障?
i. 火災是近因時，濃煙引致的損失是受保的
ii. 投保額不足時，有可能得到保障假如隨後沒有出現火災，閃電引致的損失將不到保障
iv. 因火災而產生的熱力導致的損失可以得到保障', '{"A":"i, ii","B":"i, ii, iv","C":"i, iv","D":"i, iii, iv"}'::jsonb, 'B', '火災、閃電、因救火所導致損失及濃煙影響也是保障範圍內。'),
('p2', 236, '一', '一般保險產品類別', '237. 鍋爐保險提供兩項保障，包括爆炸及：', '{"A":"鍋爐倒塌","B":"部份或全部鍋爐被盜","C":"鍋爐被人惡意損毀","D":"影響受保建築物及鍋爐的火災"}'::jsonb, 'A', '鍋爐爆炸保險承保鍋爐或壓力容器「在正常運作過程中」爆炸（屬物理性質而非化學性質的）或倒塌所帶來的損失。'),
('p2', 237, '一', '一般保險產品類別', '238. 以下哪項對鍋爐爆炸保險的陳述並不正確？', '{"A":"賠償對第三者財產造成的損害","B":"只保障被保險人的財產損失","C":"保障被保險及第三者的財產損失","D":"鍋爐爆炸造成損失是發生在正常工作時間"}'::jsonb, 'B', '鍋爐爆炸保險可採用獨立的保單、或擴大範圍的機器損壞保單或火險單承保。'),
('p2', 238, '一', '一般保險產品類別', '239. 以下哪項是鍋爐爆炸中的可保事項？', '{"A":"鍋爐倒塌的後果損失","B":"酒店的鍋爐被偷去","C":"鍋爐火災引致第三者受傷","D":"以上所有各項"}'::jsonb, 'C', '就第三者財產損失、死亡或身體受傷承擔的法律責任，以及訟費及開支為鍋爐爆炸保險的保障範圍。'),
('p2', 239, '一', '一般保險產品類別', '240. 鍋爐爆炸保單的基本保障：', '{"A":"包括財產損毀及法律責任索償","B":"針對鍋爐爆炸或倒塌帶來的損失","C":"涉及在正常工作過程中對鍋爐造成的損毀","D":"與上述各項說明相符"}'::jsonb, 'D', '鍋爐爆炸保險承保鍋爐或壓力容器「在正常運作過程中」爆炸（屬物理性質而非化學性質的）或倒塌所帶來的損失，同時就第三者財產損失、死亡或身體受傷承擔的法律責任，以及訟費及開支為鍋爐爆炸保險的保障範圍。'),
('p2', 240, '一', '一般保險產品類別', '241. 「鍋爐爆炸保險」較可能提供以下哪項保障？', '{"A":"僅對第三者財產的損毀","B":"僅對第三者的受傷的責任","C":"財產責任而已","D":"財產及十足的第三者責任"}'::jsonb, 'D', '鍋爐爆炸保險承保鍋爐或壓力容器「在正常運作過程中」爆炸（屬物理性質而非化學性質的）或倒塌所帶來的損失，同時就第三者財產損失、死亡或身體受傷承擔的法律責任，以及訟費及開支為鍋爐爆炸保險的保障範圍。'),
('p2', 241, '一', '一般保險產品類別', '242. 以下哪項是鍋爐爆炸保險的除外責任?', '{"A":"戰爭或有關事項引起的損失","B":"被保險人故意疏忽所引起的損失","C":"在火險保單中受保的風險","D":"以上所有各項"}'::jsonb, 'D', '除外責任為:通常由其他保單承保的風險：例如火災和附加危險。「標準」的除外責任：例如戰爭、核風險及恐怖主義。不適當的保障：例如被保險人的故意作為和故意忽略，及損耗等。'),
('p2', 242, '一', '一般保險產品類別', '243. 機器損壞保險保單，是為受保之物件的「不可預見和突如其來」的物質損失或損害提供保障，以下哪項屬於該類保障：', '{"A":"責任保險","B":"權益保險","C":"財產保險","D":"後果損失的保險"}'::jsonb, 'C', '機器損壞保險為1財產保險。'),
('p2', 243, '一', '一般保險產品類別', '244. 機器損壞保險中，為受保機器的實質損失或毀壞提供保險，以下哪類是所保的？', '{"A":"由意外引起","B":"不可預見及突如其來","C":"被保險人造成的毀壞","D":"不被任何其他公司保的"}'::jsonb, 'B', '機器損壞保單則就已經安裝完畢並處於運作或靜止狀態的受保裝置、機器、設備、電腦等遭受「不可預見和突如其來」的物理損失或損害提供「全險」保險保障。'),
('p2', 244, '一', '一般保險產品類別', '245. 機器損壞的除外責任是：', '{"A":"在戰爭或有關事件中損失","B":"低於免賠額以下的損失","C":"機器損壞所導致的後果損失","D":"以上全部各項"}'::jsonb, 'D', '以上三項均為除外責任例子。'),
('p2', 245, '一', '一般保險產品類別', '246. 機器損壞保險包括:', '{"A":"受保機器損毀","B":"後果損失，因機械故障而出現","C":"地震導致受保機器損毀","D":"因電力導致火災而將受保機器損毀"}'::jsonb, 'A', '因機器故障而導致其他的損失是除外責任，並不是保障受保機器的保險範圍。'),
('p2', 246, '一', '一般保險產品類別', '247. 在通常的機器損壞保險保單中，以下哪一項不是除外責任？', '{"A":"戰爭和相關風險","B":"受保機器自身的損壞","C":"保單中的免賠額","D":"由機器損壞而引致的後果損失"}'::jsonb, 'B', '機器狀況因正常使用而惡化及早已存在的缺陷是除外責任。'),
('p2', 247, '一', '一般保險產品類別', '248. 建築全險的第一部份以「全險」提供財產保障，第二部份則：', '{"A":"對公眾責任提供保障","B":"不設任何免賠額","C":"提供經濟權益的保障","D":"以上所有各項"}'::jsonb, 'A', '第二部分：承保對因建築工程導致第三者受傷或財產損失所負的法律責任。'),
('p2', 248, '一', '一般保險產品類別', '249. 一般以本港提供的建築全險通常包括：', '{"A":"財產及責任保險的組合","B":"財產保險而已","C":"責任保險而已","D":"經濟權益保險"}'::jsonb, 'A', '建築全險包括財產及法律責任保障。'),
('p2', 249, '一', '一般保險產品類別', '250. 建築「全險」保險一般包括兩個部分組成:
i. 建築工人的勞工保險
ii. 承建商作出保證保險
Iii. 指明工程的財產
Iv. 工程引致第三者傷亡或財產損毀', '{"A":"i & ii","B":"i & iii","C":"ii & iii","D":"iii & iv"}'::jsonb, 'D', '建築全險包括財產及法律責任保障。'),
('p2', 250, '一', '一般保險產品類別', '251. 「建築全險保單」中的第一部份，會提供以下哪項保障？', '{"A":"因颱風對正在進行的工程損毀","B":"因錯誤設計而導致損毀","C":"實際點算後的失竊","D":"以上所有各項"}'::jsonb, 'A', '第一部分：就指明的財產以「全險」方式提供財產保險。'),
('p2', 251, '一', '一般保險產品類別', '252. 一般建築全險有兩部份，它們分別是:', '{"A":"第一部份是提供財產保險,第二部份是提供責任保險","B":"第一部份是提供責任保險,第二部份是提供經濟權益保險","C":"第一部份是提供強制性保險,第二部份是提供自願性保險","D":"第一部份是提供財產保險,第二部份是提供損害賠償"}'::jsonb, 'A', '建築全險包括財產及法律責任保障。'),
('p2', 252, '一', '一般保險產品類別', '253. 甚麼險種是保障一個承辦商當遇到它的僱員意外弄傷他人?', '{"A":"建築責任","B":"建築保障","C":"物主、業主及租客的責任","D":"物主、業主的責任"}'::jsonb, 'B', '建築工程「全險」保險承保對因建築工程導致第三者受傷或財產損失所負的法律責任。'),
('p2', 253, '一', '一般保險產品類別', '254. 一般建築全險有兩部份，第二部份是:', '{"A":"第二部份是提供責任保險","B":"第二部份是提供經濟權益保險","C":"第二部份是提供自願性保險","D":"第二部份是提供財產保險"}'::jsonb, 'A', '建築全險包括財產及法律責任保障。'),
('p2', 254, '一', '一般保險產品類別', '255. 某承建商於距離中銀大廈數米外之建築地盤動工，並購有建築全險保障，以下哪項並不屬於該保險的保障範圍，但可加費用另購的項目？', '{"A":"對其他建築物造成的減弱或除去支撐的法律責任","B":"爆炸","C":"對減弱或除去支撐所引致的“自我損害”","D":"對減弱或除去支撐所引致的“自我損害”之法律責任"}'::jsonb, 'A', '可以額外支付保費購買批單來承保由豁免承保就屬於被保險人的財產(例如保單第一部分所承保的工程)的損失或損害承擔的法律責任，及多種危險，包括減弱或消除支撐力'),
('p2', 255, '一', '一般保險產品類別', '256. 以下哪項對於建築全險的描述是不正確的？', '{"A":"減弱其他建築物支撐力是屬於除外責任，但可以付出額外保費，使之附加於保單上","B":"第一部份的保障以「全險」形式作為保障，包括錯誤設計","C":"第一部份或第二部份都設有免賠額","D":"以上所有各項"}'::jsonb, 'B', '第一部分：就指明的財產以「全險」方式提供財產保險。受保財產相當可能包括合約工程和任何由委託人供應的物料，附加承保建築用的裝置、設備和機械也行。清除殘損物的費用也可包括在內。'),
('p2', 256, '一', '一般保險產品類別', '257. 以下哪項較有可能是全險建築保險的除外責任？', '{"A":"在保單的責任部分下設定一個免賠額","B":"由於減弱支撐所造成的第三者責任","C":"於實際點算時才發現的損失","D":"以上所有各項"}'::jsonb, 'D', '免賠額、減弱支撐及盤點時才發現的損失均屬除外責任。'),
('p2', 257, '一', '一般保險產品類別', '258. 對其他建築物造成的支撐減弱通常：', '{"A":"已經包括在建築全險中的責任保障部份","B":"已經包括在建築全險中的財產保險保障部份","C":"在損失金額較免賠額為大時，已經包括在建築全險中","D":"是建築全險的除外責任"}'::jsonb, 'D', '減弱支撐屬除外責任。'),
('p2', 258, '一', '一般保險產品類別', '259. 以下哪項不屬於建築全險的保障範圍？', '{"A":"因水災引致建築物料損失或毀壞","B":"因火災引致建築物料損失或毀壞","C":"實際點算時才發現之損失","D":"因颱風引致的損毀"}'::jsonb, 'C', '盤點時才發現的損失屬除外責任。'),
('p2', 259, '一', '一般保險產品類別', '260. 在建築全險第二部份保障中所提供保障範圍可能是：', '{"A":"對其他建築物造成的減弱支撐力","B":"對第三者造成的財產上損失","C":"由第一部分保障所引致的責任","D":"以上各項都是"}'::jsonb, 'B', '第二部分：承保對因建築工程導致第三者受傷或財產損失所負的法律責任。'),
('p2', 260, '一', '一般保險產品類別', '261. 建築全險對以下哪項索償不會作出賠償？', '{"A":"委託人供應的物料","B":"實際點算時才發現的損失","C":"第三者的財產損毀","D":"清理殘損物的開支"}'::jsonb, 'B', '盤點時才發現的損失屬除外責任。'),
('p2', 261, '一', '一般保險產品類別', '262. 香港政府有計劃進行某填海項目，並提供特別的建築用的工業設備予承建商使用。該些工業設備應在以下哪項承保？', '{"A":"建築「全險」保險保單第一部份","B":"安裝工程「全險」保險保單","C":"建築「全險」保險保單第二部份","D":"裝配及安裝保險保單"}'::jsonb, 'A', '第一部分就指明的財產以「全險」方式提供財產保險。受保財產相當可能包括合約工程和任何由委託人供應的物料，附加承保建築用的裝置、設備和機械（作為單獨的裝置及機械保單的替代方法）也行。'),
('p2', 262, '一', '一般保險產品類別', '263. 以下哪項有關在香港的建築全險的說明是不正確的？', '{"A":"減弱支撐通常都是屬於責任保障的除外責任","B":"一項或多項的免賠額可應用於保單兩部份內的每一部份","C":"財產保險保障部份承保大部份損失，其中包括錯誤設計","D":"保險保單格式包括兩部份，財產保險及責任保險"}'::jsonb, 'C', '財產保險保障設有通常適用於「全險」保險保障的除外責任。還有一些適用於此類保障的，包括錯誤設計、有缺陷的材料、不良工匠技藝及只於盤點時才發現的損失在内的其他除外責任。'),
('p2', 263, '一', '一般保險產品類別', '264. 以下哪項對於建築工程全險保險的描述是不正確的？', '{"A":"減弱其他建築物支撐力是屬於除外責任，但可以付出額外保費，使之附加於保單上","B":"第一部份的保障以「全險」形式作為保障，包括錯誤設計","C":"第一部份或第二部份都設有免賠額","D":"以上所有各項"}'::jsonb, 'B', '設有通常適用於「全險」保險保障的除外責任。還有一些適用於此類保障的，包括錯誤設計、有缺陷的材料、不良工匠技藝及只於盤點時才發現的損失在内的其他除外責任 。'),
('p2', 264, '一', '一般保險產品類別', '265. 以下哪項不屬於強制性責任保險？', '{"A":"汽車第三者保險","B":"公眾責任保險","C":"僱主補償保險","D":"以上各項皆不屬於強制性責任保險"}'::jsonb, 'B', '公眾責任保險並不是法律上強制性保險。'),
('p2', 265, '一', '一般保險產品類別', '266. 以下哪兩項是責任保險的保障範圍:
i. 由蓄意的暴力所引起的責任
ii. 普通法下的責任(並非蓄意)
iii. 法定要求的責任
iv. 根據保險條款而自願承擔的責任', '{"A":"i , ii","B":"i , iii","C":"ii , iii","D":"iii, iv"}'::jsonb, 'C', '各別保障所保的法律責任可能因法規（即由立法機關制定的法律）及/或普通法（通常因疏忽）而產生。法律責任也可以在合約下產生，然而，合約附加的責任，即藉協議承擔的法侓責任，通常屬於責任保險保障的除外責任。'),
('p2', 266, '一', '一般保險產品類別', '267. 合約下產生的責任，在責任保險中：', '{"A":"法律要求下必須執行","B":"是特定除外","C":"保險人必須執行","D":"被保險人必須執行"}'::jsonb, 'B', '合約附加的責任，即藉協議承擔的法侓責任，通常屬於責任保險保障的除外責任。'),
('p2', 267, '一', '一般保險產品類別', '268. 責任保險可能從法定要求(條例的條款)及普通法規(疏忽)下及合約下(協議下)產生，下列那項是可保的？', '{"A":"法定要求而已","B":"普通法而已","C":"法定及普通法而已","D":"法定、普通法及合約下的責任"}'::jsonb, 'C', '各別保障所保的法律責任可能因法規（即由立法機關制定的法律）及/或普通法（通常因疏忽）而產生。'),
('p2', 268, '一', '一般保險產品類別', '269. 以下哪項不屬於責任保險的保障範圍？', '{"A":"觸犯條例而引起的責任","B":"因疏忽引致的責任","C":"不遵行協議內容引起的責任","D":"以上所有各項"}'::jsonb, 'C', '不遵行協議內容而產生的法律責任是除外責任。'),
('p2', 269, '一', '一般保險產品類別', '270. 以下哪項不是長期責任業務？', '{"A":"產品責任","B":"怠忽職守","C":"公眾責任","D":"火險"}'::jsonb, 'D', '火險不是責任保險。'),
('p2', 270, '一', '一般保險產品類別', '271. 責任保險一般計算方式是:', '{"A":"工資","B":"銷售額","C":"支付臨時保費","D":"以上所有各項"}'::jsonb, 'D', '以上皆是責任保險保險一般計算方式。'),
('p2', 271, '一', '一般保險產品類別', '272. 責任保險是屬於長期責任業務的意思是指：', '{"A":"索償從出現至開始，會跨越一個頗長的時間","B":"索償必須於保單生效期內呈報","C":"每項索償需要一段頗長的時間給付","D":"索償的結果會影響全年的盈利"}'::jsonb, 'A', '所有的責任保險所保的法律責任均屬長期待決責任，意思是索償可能遲遲才出現，並且經歷一段很長的發展期(延至保單到期後的數年也是可能的)。'),
('p2', 272, '一', '一般保險產品類別', '273. 在「索償申報」保單中，', '{"A":"意外發生日期屬關鍵因素","B":"提出索償的時間屬關鍵因素","C":"保單屆滿前必須完成所有索償的給付","D":"在受到法庭行約束下的保單才可獲得保障"}'::jsonb, 'B', '不論何時受傷或財產受損，第三者就此而提出的任何索償必須於該保單生效期間或任何延長申報期之內提出，而延長申告期是一段緊接着保單不續約或保單註銷的有限時期。'),
('p2', 273, '一', '一般保險產品類別', '274. 根據責任保險中的「索償申報」保單保障的含義，以下哪項出現後索償才會容許?', '{"A":"事故發生在保單年度出現","B":"索償在保單開始前經已提出","C":"索償於保單期限內給付","D":"申報索償的時間、屬於保單保障的期間、或其後一段指定的期限"}'::jsonb, 'D', '不論何時受傷或財產受損，第三者就此而提出的任何索償必須於該保單生效期間或任何延長申報期之內提出，而延長申告期是一段緊接着保單不續約或保單註銷的有限時期。'),
('p2', 274, '一', '一般保險產品類別', '275. 以下哪三項對僱員補償條例的描述是正確的？
i. 在普通法下，僱員是受到保障的
ii. 此保障包括承保商的僱員
iii. 在僱員補償條例中的責任是受到保障的保費以百分比或千分比徵費，並以僱主全年付出工資計算', '{"A":"i, ii, iii","B":"i, ii, iv","C":"i, iii, iv","D":"ii, iii, iv"}'::jsonb, 'C', '承保商的僱員不包括在內。'),
('p2', 275, '一', '一般保險產品類別', '276. 以下哪項屬於本港發出的僱員補償計劃內的保障？', '{"A":"對第三者的合約附加責任","B":"被保險承建商對本身僱員的法律責任","C":"不屬於本港僱員補償計劃內所指的「僱員」","D":"以上所有各項"}'::jsonb, 'B', '被保險承建商對本身僱員的法律責任並不包括在計劃內。'),
('p2', 276, '一', '一般保險產品類別', '277. 以下哪一項屬於僱主責任保險的保障範圍？', '{"A":"合約上的責任","B":"僱主的錯失引起的責任","C":"承建商的員工","D":"非僱員引起的責任"}'::jsonb, 'B', '這種僱主責任並非在該條例下產生，它與侵權法下（主要因為疏忽）的法律責任有關。'),
('p2', 277, '一', '一般保險產品類別', '278. 以下哪項對於僱員補償條例的描述是不正確的？', '{"A":"通常只適用於受傷或死亡","B":"賠償金額通常比違反普通法少","C":"必須証明僱主的疏忽","D":"必須於工作期間引致受傷或死亡"}'::jsonb, 'C', '《僱員補償條例》下的法律責任：這是加諸於僱主身上的法定責任。如果僱員在受僱期間因工遭遇意外事故以致受傷或死亡，那麽，僱主必須向僱員或其受養人支付規定的補償金額，而有關金額可能在個別個案中比實際的損失還要低。'),
('p2', 278, '一', '一般保險產品類別', '279. 在港簽發的「責任保險」中「第三者」是指', '{"A":"被保險人的僱員","B":"被保險人的非僱員","C":"被保險人的家庭成員","D":"與任何索償無關的人"}'::jsonb, 'B', '「第三者」是指被保險人的非僱員。'),
('p2', 279, '一', '一般保險產品類別', '280. 僱主責任保險通常是保障：', '{"A":"僱主對僱員的法律責任","B":"僱主對非僱員的法律責任","C":"僱主對其家庭成員的法律責任","D":"僱主對自己的法律責任"}'::jsonb, 'A', '僱員補償保單承保僱主對僱員應承擔的法律責任。'),
('p2', 280, '一', '一般保險產品類別', '281. 僱員補償條例，僱員的補償是:', '{"A":"僱員補償法例下的權益而已","B":"被保險人的妻子及家庭成員而已","C":"香港法律下適用的責任","D":"被保人因失責但並非法定所必須負上的責任"}'::jsonb, 'D', '僱員補償保單承保僱主對僱員應承擔的法律責任。'),
('p2', 281, '一', '一般保險產品類別', '282. 根據《僱員補償條例》，僱員要得到賠償，以下哪項描述是正確的？', '{"A":"僱員必須證明僱主的疏忽或錯失","B":"僱員毋須證明僱主的疏忽或錯失","C":"僱主必須證明僱員並無疏忽","D":"僱主及僱員必須證明雙方並無疏忽"}'::jsonb, 'B', '《僱員補償條例》下的法律責任：這是加諸於僱主身上的法定責任。如果僱員在受僱期間因工遭遇意外事故以致受傷或死亡，那麽，僱主必須向僱員或其受養人支付規定的補償金額。相對應「有過失法律責任」，這種法律責任是「嚴格法律責任」，即不論僱主一方是否疏忽，也要負責給予補償。'),
('p2', 282, '一', '一般保險產品類別', '283. 以下哪項屬於《僱員補償條例》的適用範圍？', '{"A":"因僱主疏忽而引致的損失，須負責補償","B":"不是僱主疏忽而引致的損失，須負責補償","C":"不論是否僱主疏忽而引致的損失，須負責補償","D":"不論是否因工受傷，須負責補償"}'::jsonb, 'C', '《僱員補償條例》下的法律責任：這是加諸於僱主身上的法定責任。如果僱員在受僱期間因工遭遇意外事故以致受傷或死亡，那麽，僱主必須向僱員或其受養人支付規定的補償金額。相對應「有過失法律責任」，這種法律責任是「嚴格法律責任」，即不論僱主一方是否疏忽，也要負責給予補償。'),
('p2', 283, '一', '一般保險產品類別', '284. 在港簽發的僱員補償保單保障在《僱員補償條例》下的法律責任及「普通法」的責任，「普通法的責任」意味著：', '{"A":"不屬於嚴重的受傷情況","B":"受保僱員引致的第三者受傷賠償","C":"基於過失的法律責任","D":"屬於較低金額的索償"}'::jsonb, 'C', '「普通法」責任：這種僱主責任並非在該條例下產生，它與侵權法下（主要因為疏忽）的法律責任有關。'),
('p2', 284, '一', '一般保險產品類別', '285. 根據普通法(即僱主的錯失)，而非《僱員補償條例》下的責任補償：', '{"A":"賠償金額通常會比較高","B":"賠償金額通常會比較低","C":"賠償金額相約","D":"屬於僱主的刑事責任"}'::jsonb, 'A', '《僱員補償條例》下的法律責任：這是加諸於僱主身上的法定責任。如果僱員在受僱期間因工遭遇意外事故以致受傷或死亡，那麽，僱主必須向僱員或其受養人支付規定的補償金額，而有關金額可能在個別個案中比實際的損失還要低。'),
('p2', 285, '一', '一般保險產品類別', '286. 以下哪項或哪些為僱員補償保險的除外責任？', '{"A":"通過協議承擔的法律責任","B":"被保險人對其承建商的僱員責任","C":"不是香港〈僱員補償條例〉下的僱員","D":"以上各項皆是"}'::jsonb, 'D', '除外責任:(i) 合約附加的責任；(ii)對被保險人的承建商的僱員承擔的法律責任；(iii)死傷者不屬於《僱員補償條例》所指的僱員；(iv)「標準的」除外責任，例如戰爭、核風險及恐怖主義。'),
('p2', 286, '一', '一般保險產品類別', '287. 僱員補償保單的保費計算較可能基於', '{"A":"被保險人發出的全年工資","B":"被保險人擁有的物業價值","C":"該保單提供的責任限制","D":"可能向僱員支付的最高權益"}'::jsonb, 'A', '首次保費屬於臨時性質，實際金額則根據最終工資數字而作出調整。'),
('p2', 287, '一', '一般保險產品類別', '288. 僱員補償保險的保費：', '{"A":"永不以可調整方法作根據","B":"有時以可調整方法作根據","C":"一直以可調整方法作根據","D":"只以個別被保險人而作出調整"}'::jsonb, 'C', '首次保費屬於臨時性質，實際金額則根據最終工資數字而作出調整。'),
('p2', 288, '一', '一般保險產品類別', '289. 保險人拒絕索償是因被保險人違反保單條款，但有一種索償是可能凌駕於拒絕索償的理由，這是：', '{"A":"個人意外保險","B":"關於被保險人財產的保險","C":"關於強制性保險保障的範圍","D":"以上所述各項"}'::jsonb, 'C', '相關的強制保險法例迫使保險人在合約條款已被違反的情況下仍要滿足索償要求；如果沒有了這項法律規定，保險人是可以避免承擔保單責任的。'),
('p2', 289, '一', '一般保險產品類別', '290. 以下哪項對產品責任保險的描述是正確的？', '{"A":"主要是保障「有問題」的產品","B":"有些高索償意識地區被稱為「危險的」市場","C":"設有同一年度的賠償總限額","D":"以上所有各項"}'::jsonb, 'D', '產品責任保單承保就由所售賣、供應或維修的貨品，或所提供的服務等引起，及在由被保險人擁有或佔用的處所以外的地方發生的傷害或損害，承擔的法律責任。世界上有些地區是出名的申索意識高的地區，尤其是美國和北美洲地區，所以，向這些市場供應產品會帶來較高的風險，產品責任保障也就會較昂貴或較難購得。'),
('p2', 290, '一', '一般保險產品類別', '291. 一項消費品(例如:電風扇)因生產過程出錯而成為有問題產品，購物者因觸電而對生產商提出索償，那麼涉及的保險是：', '{"A":"錯誤及疏忽保障","B":"公眾責任","C":"產品責任","D":"專業責任"}'::jsonb, 'C', '產品責任保單承保就由所售賣、供應或維修的貨品，或所提供的服務等引起，及在由被保險人擁有或佔用的處所以外的地方發生的傷害或損害，承擔的法律責任。'),
('p2', 291, '一', '一般保險產品類別', '292. 以下哪項對於產品責任的描述是不正確的？', '{"A":"主要保障「有問題」的產品","B":"它的保障範圍與公眾責任完全相同","C":"通常設有同一年度的索償限額","D":"有些北美地區稱為高危市場"}'::jsonb, 'B', '產品責任保單承保就由所售賣、供應或維修的貨品，或所提供的服務等引起，及在由被保險人擁有或佔用的處所以外的地方發生的傷害或損害，承擔的法律責任。類似法律責任如在被保險人的處所引起，應該由公眾責任保單承保，同時此保單設有年度的索償限額。'),
('p2', 292, '一', '一般保險產品類別', '293. 產品責任的保障包括：
i. 產品本身有問題
ii. 與公眾責任保障範圍一樣
iii. 通常是「索償申報」保單
iv. 某些市場屬於高度風險市場', '{"A":"i, ii, iii","B":"i, ii, iv","C":"ii, iii, iv","D":"i, iii, iv"}'::jsonb, 'D', '產品責任保單承保就由所售賣、供應或維修的貨品，或所提供的服務等引起，及在由被保險人擁有或佔用的處所以外的地方發生的傷害或損害，承擔的法律責任。世界上有些地區是出名的申索意識高的地區，尤其是美國和北美洲地區，所以，向這些市場供應產品會帶來較高的風險，產品責任保障也就會較昂貴或較難購得。最後，此保單是屬於「索償申報」保單的一種。'),
('p2', 293, '一', '一般保險產品類別', '294. 為製造業或工業團體設立的責任保險組合，較有可能提供：', '{"A":"公眾責任保障而已","B":"產品責任保障而已","C":"專業責任保障而已","D":"以上所有或大部份保障"}'::jsonb, 'B', '產品責任保障保障有關行業所所售賣、供應或維修的貨品，或所提供的服務等引起，及在由被保險人擁有或佔用的處所以外的地方發生的傷害或損害，承擔的法律責任。'),
('p2', 294, '一', '一般保險產品類別', '295. 以下哪情況不受保於產品責任保單？', '{"A":"一名兒童因有問題的玩具而受傷害","B":"產品在設計上出現危險性的錯誤","C":"殺蟲劑在製造過程中出錯而摧毀農作物","D":"一批醫療用品在製造的過程中出現錯誤"}'::jsonb, 'B', '由貨品的設計、規劃、程式或規格引起的法律責任屬除外責任。'),
('p2', 295, '一', '一般保險產品類別', '296. 以下哪項對於專業彌償保險的描述是正確的？', '{"A":"較常以索償申報的方式簽發","B":"它可能以「醫療事故責任保險」出現","C":"主要保障專業行為及疏忽出現的錯誤","D":"以上所有各項"}'::jsonb, 'D', '專業彌償保險單一般承保被保險人就其「錯誤」作為或不作為導致第三者傷亡、遭受財產損失或損害、或遭受財務損失（視乎受保活動或專業而定）而承擔的法律責任，但第三者的申索必須在保單期限内首次提出。專業彌償保險相當可能以「索償申報」方式提供保險保障。醫生的專業彌償保險單為醫療事故責任保險。'),
('p2', 296, '一', '一般保險產品類別', '297. 一位律師未能及時採取行動以致其當事人因此承受極大的財務損害，該事件可由該律師屬下那一項保險作出賠償', '{"A":"產品責任保險；","B":"公眾責任保險；","C":"後果責任保險；","D":"專業彌償保險"}'::jsonb, 'D', '專業彌償保單為「專業」人士提供保障，例如律師、醫生（醫療事故責任保險）、會計師、建築師、基金經理、受托人等，因此，這種保障是承保專業作為及不作為中的失誤，其中包括提供不適當的意見。'),
('p2', 297, '一', '一般保險產品類別', '298. 打算在本港從事保險經紀業務，必須購買以下哪項保險？', '{"A":"專業彌償保險","B":"怠忽職守","C":"僱員補償保險","D":"公眾責任保險"}'::jsonb, 'A', '香港的保險經紀，在獲授權開業前，必先取得專業彌償保障，以加強保護自己的客戶。'),
('p2', 298, '一', '一般保險產品類別', '299. 以下何者較可能得到專業彌償保險的保障？', '{"A":"銀行經理","B":"職業足球員","C":"保險代理","D":"保險經紀"}'::jsonb, 'D', '香港的保險經紀，在獲授權開業前，必先取得專業彌償保障，以加強保護自己的客戶。'),
('p2', 299, '一', '一般保險產品類別', '300. 以下哪項對「公眾責任保險」保費釐定的描述是不正確的？', '{"A":"保費是可以調整的","B":"保費是不可以調整的","C":"工資及銷售額可以是保費的根據","D":"通常要求在期後才付保費"}'::jsonb, 'D', '傳統上這種保單的保費是可以調整的，目的是反映保單有效期内商業活動的實際總量。但在香港，收取不可調整保費也越來越常見了，即保險人接受以預期的工資／銷售額視為當年的最終數值，因此就不必補交或退回保費了。'),
('p2', 300, '一', '一般保險產品類別', '301. 以下哪項對於公眾責任保障的描述是不正確？', '{"A":"保費一般是暫繳的，而且可以調整的","B":"主要保障對象是公眾及僱員","C":"保障範圍是不包括僱員","D":"提供實際索償的損失及訴訟費用"}'::jsonb, 'B', '這類保險是承保被保險人因在保單年度內發生的意外事故而須向第三者承擔的法律責任。'),
('p2', 301, '一', '一般保險產品類別', '302. 公眾責任保險是：', '{"A":"保障對於公眾成員的法律責任","B":"會保障由汽車意外引致的責任","C":"保障公眾成員所引致的損失毀壞","D":"保障員工的法律責任"}'::jsonb, 'A', '這類保險是承保被保險人因在保單年度內發生的意外事故而須向第三者承擔的法律責任。'),
('p2', 302, '一', '一般保險產品類別', '303. 以下哪項對於公眾責任保險的描述是正確的？', '{"A":"它的索償可能於較後時間提出","B":"它保障受傷及財產損毀的索償","C":"它保障有關索償訴訟的費用","D":"以上所有各項"}'::jsonb, 'D', '這類保險是承保被保險人因在保單年度內發生的意外事故而須向第三者承擔的法律責任。同時也承保法律開支，即因替被保險人辯護或堅持拒絕有關索償而引致的法律開支，及申索成功的第三者的法律開支。這種意外事故可能於較後時間才引起索償（有時在數年以後），只要被保險人符合了作出通知的保單規定，這種索償仍然是受保的。'),
('p2', 303, '一', '一般保險產品類別', '304. 公眾責任保險的概念是指：', '{"A":"提供僱員受傷的保障","B":"提供僱員的財產損毀保障","C":"提供僱員受傷及財產損毀保障","D":"提供非僱員受傷或財產損毀的保障"}'::jsonb, 'D', '這類保險是承保被保險人因在保單年度內發生的意外事故而須向第三者承擔的法律責任。'),
('p2', 304, '一', '一般保險產品類別', '305. 以下哪項屬於公眾責任保險的除外責任？', '{"A":"在特定地區範圍以外發生的意外","B":"其他保單也提供較適合的責任風險的保障","C":"合約上的責任","D":"以上所有各項"}'::jsonb, 'D', '除外責任:i在指明地區範圍以外發生的意外事故不受保。ii 其他保單也可以承保責任風險。iii 合約附加的責任。iv 「標準的」除外責任，例如戰爭及核風險等。'),
('p2', 305, '一', '一般保險產品類別', '306. 以下哪三項屬於在本港公眾責任保險保單中的除外責任？
i. 合約上附加的責任
ii. 在受保地區範圍以外發生的
iii. 較適合由其他保單保障的責任 (如: 汽車)
iv. 第三者意外責任', '{"A":"i , ii , iii","B":"i , ii , iv","C":"i , iii , iv","D":"ii , iii , iv"}'::jsonb, 'A', '除外責任:i在指明地區範圍以外發生的意外事故不受保。ii 其他保單也可以承保責任風險。iii 合約附加的責任。iv 「標準的」除外責任，例如戰爭及核風險等。'),
('p2', 306, '一', '一般保險產品類別', '307. 以下哪項較不可能是公眾責任保單的除外責任?', '{"A":"在特定範圍以外所引起的責任","B":"其他保單(例如:汽車) ， 較適合提供保障的責任","C":"因被保險人或其職員疏忽所引起的責任","D":"保險人根據合約安排承擔的責任"}'::jsonb, 'C', '除外責任:i在指明地區範圍以外發生的意外事故不受保。ii 其他保單也可以承保責任風險。iii 合約附加的責任。iv 「標準的」除外責任，例如戰爭及核風險等。'),
('p2', 307, '一', '一般保險產品類別', '308. 公眾責任保險保費可根據每年工資釐定而可以是經常調整的，可調整的意思是：', '{"A":"如沒有索償，可退還保費","B":"如該年工資高於預期，須支付額外保費","C":"如工資高於預期，則加下年之保費","D":"以上各項皆正確"}'::jsonb, 'B', '保費的釐定是基於某些可變動的因素的話，例如工資及銷售額，保費可以規定為可調整保費。所以，起保時須支付臨時保費；當知道了最後確切的數字時，再將保費調整至正確金額。'),
('p2', 308, '一', '一般保險產品類別', '309. 下列哪一項對於公眾責任保險保費的描述是不正確的', '{"A":"保費是可以調整的","B":"保費是根據被保險人所支付的每年工資而釐定","C":"保險費率是根據被保險人的行業及職業來釐定","D":"保費只需在保險期內支付"}'::jsonb, 'D', '在香港，收取不可調整保費也越來越常見了，即保險人接受以預期的工資／銷售額視為當年的最終數值，因此就不必補交或退回保費了。'),
('p2', 309, '一', '一般保險產品類別', '310. 以下那項有關公眾責任保險保費描述並不正確？', '{"A":"屬於可調整的","B":"有時是不可調整的","C":"所有類型保險的保費率是標準的","D":"視乎全年工資及營業額而調整"}'::jsonb, 'C', '保費的釐定是基於某些可變動的因素的話，例如工資及銷售額，保費可以規定為可調整保費。所以，起保時須支付臨時保費；當知道了最後確切的數字時，再將保費調整至正確金額。'),
('p2', 310, '一', '一般保險產品類別', '311. 某快餐店買了兩份公眾責任保險保單，一份保2021年，另一份保2022年。於2022年收到顧客在2021年於其處所受傷索償，到底哪份保單會作出賠付，原因何在', '{"A":"可能是第一張保單，原因是公眾責任保單通常以“索償發生”方式發出","B":"肯定是第二張保單，原因是第一張保單已屬無效","C":"可能是第二張保單，原因是公眾責任保單通常以“索償申報”方式發出","D":"肯定是第一張保單，原因是公眾責任保單通常以“索償發生”方式發出"}'::jsonb, 'A', '公眾責任險通常是用「索償發生」方式提供保險保障的，「索償申報」方式則不常用。'),
('p2', 311, '一', '一般保險產品類別', '312. 以下哪項或哪些是責任保險保單中的通用除外責任？', '{"A":"過失","B":"義務","C":"合約附加的責任","D":"以上各項"}'::jsonb, 'C', '合約附加的責任常為各責任保險保單中的通用除外責任。'),
('p2', 312, '一', '一般保險產品類別', '313. 一名兒童因有問題的玩具而受傷害，這情況受保於那項責任保單？', '{"A":"公眾責任保險","B":"產品責任保險","C":"專業保險","D":"以上所有各項"}'::jsonb, 'B', '每位製造商或賣家均對其消費者負有一項照顧責任，就是不可製造或向他們銷售「有問題的產品」，使他們因此蒙受傷害或損害，此為產品責任保險。'),
('p2', 313, '一', '一般保險產品類別', '314. 以下哪項對於公眾責任保障的描述是正確？
i.不會賠償因僱員在工作期間受傷
ii.保單的保費是可以調整的
iii.會賠償因僱員或第三者受傷
iv.訴訟費用及補償金額會包括', '{"A":"i, iii","B":"i,ii, iv","C":"ii,iii,iv","D":"i,ii,iii,iv"}'::jsonb, 'B', '公衆責任保險是承保被保險人因在保單年度內發生的意外事故而須向第三者承擔的法律責任，而保費可以規定為可調整保費。這類保單所承保的是第三者受傷、死亡和財產受損的法律責任。同時也承保法律開支，即因替被保險人辯護或堅持拒絕有關索償而引致的法律開支，及申索成功的第三者的法律開支。'),
('p2', 314, '一', '一般保險產品類別', '315. 關於公眾責任保險，以下哪一項不是正確的？', '{"A":"保費可調整","B":"保費以受保人每年支付的工資而釐定","C":"保費根據不同的行業及職業而定","D":"所有保費於每年年度完結才支付"}'::jsonb, 'D', '如果保費的釐定是基於某些可變動的因素的話，例如工資及銷售額，保費可以規定為可調整保費。所以，起保時須支付臨時保費；當知道了最後確切的數字時，再將保費調整至正確金額。'),
('p2', 315, '一', '一般保險產品類別', '316. 以下那個計劃在支付無法從相關僱主或保險人那裡得到應有的因工傷亡及損害賠償(僱主很困難為其從事高風險工種的僱員購買僱員保險)的受傷僱員本人或身故僱員的家人?', '{"A":"僱員傷亡彌償計劃","B":"僱員傷亡計劃","C":"僱員補償計劃","D":"僱員補償聯保計劃"}'::jsonb, 'D', '僱員補償聯保計劃支付無法從相關僱主或保險人那裡得到應有的因工傷亡及損害賠償的受傷僱員本人或身故僱員的家人'),
('p2', 316, '一', '一般保險產品類別', '317. 產品責任保險的限額一般是：', '{"A":"限額以每宗事故計算","B":"限額以每日計算","C":"以每年度一個限額計算","D":"沒有等定計算方法"}'::jsonb, 'C', '產品責任保險的保額一般以保單限額為依據，有關彌償限額可能是一項總限額，因此發生了索償後，在保險期限的餘下時間內可用的保障金額 會相應降低'),
('p2', 317, '一', '一般保險產品類別', '318. 水險單中指明免賠額為損失的5%，若船體價值為一佰萬，當船隻出現全部損失時，賠償額為：', '{"A":"25萬","B":"75萬","C":"95萬","D":"100萬"}'::jsonb, 'D', '全損時將會計算總損失金額賠償。'),
('p2', 318, '一', '一般保險產品類別', '319. 水險中，部分損失主要分成單獨海損及:', '{"A":"全損","B":"共同救助","C":"共同海損","D":"救助海損"}'::jsonb, 'C', '在水險中有兩種部分損失:單獨海損及共同海損。'),
('p2', 319, '一', '一般保險產品類別', '320. 以下哪項關於「海損」的描述是不正確的？', '{"A":"它的意思是部分損失而非全部","B":"它通常與不足額保險有關","C":"「共同海損」代表分擔出現的損失","D":"「單獨海損」是指船体或貨物某部份招致損失"}'::jsonb, 'B', '財產保險合約「適用比例分攤」，意思是說，必須全額投保，否則須按發生損失時投保不足的比例分攤損失，以作懲罰。在水險中，“Average”是指部分損失（即非全損）。'),
('p2', 320, '一', '一般保險產品類別', '321. 「單獨海損」是:', '{"A":"一種在水險出現非全損","B":"一種在火險出現和投保額不足有關","C":"一種計算保費的統計術語","D":"普遍用在各種保險"}'::jsonb, 'A', '單獨海損是影響有關保險標的的部分損失。'),
('p2', 321, '一', '一般保險產品類別', '322. 有關水險中的「海損」，一般分為兩種，一種是「共同海損」，而另一種是：', '{"A":"特定海損","B":"單獨海損","C":"特殊海損條件","D":"海損的比例計算條件"}'::jsonb, 'B', '海損為單獨海損及共同海損。'),
('p2', 322, '一', '一般保險產品類別', '323. 「共同海損」是', '{"A":"一個古老慣例去公平地分擔某些損失","B":"一個古老慣例要求所有保險人去同等支付","C":"保單條款要求被保險人承擔一部份損失","D":"一個海上相撞分擔過失的機制"}'::jsonb, 'A', '共同海損損失是由共同海損行為引起的部分損失（所謂「部分損失」是指整個海上冒險〔即某艘船的某段航程所涉及的權益的總和，尤其包括船隻本身及船上所載任何貨品〕的部分損失）。凡發生共同海損損失，蒙受損失的一方有權在海商法施加的條件的規限下，從被該行為惠及的具有權益的每一個人，包括他自己，按比率獲得分擔損失（稱為「共同海損分擔」）。'),
('p2', 323, '一', '一般保險產品類別', '324. 在海上船險中，以下哪項屬於單獨海損？', '{"A":"因船隻相撞造成的輕微損毀","B":"因盜竊而損失的貨運物品","C":"因漏電失火令導向舵損毀","D":"以上所有各項"}'::jsonb, 'D', '單獨海損是影響有關保險標的的部分損失。'),
('p2', 324, '一', '一般保險產品類別', '325. 以下哪項對共同海損的描述是正確的？
i. 有關損失必須是故意發生的
ii. 所作犧牲必須達致本身期望的目標
iii. 有關損失由所有整體冒險業務的既得利益者分擔
iv. 有關損失由犧牲貨物的物主以外所有既得益者分擔', '{"A":"i & ii","B":"ii & iii","C":"i, ii & iii","D":"i, ii, iii & iv"}'::jsonb, 'C', '凡在發生危險時，為了保存共同冒險中陷於危險中的財產而自願和合理地作出或招致任何特殊犧牲或費用，屬於共同海損行為。凡發生共同海損損失，蒙受損失的一方有權在海商法施加的條件的規限下，從被該行為惠及的具有權益的每一個人，包括他自己，按比率獲得分擔損失（稱為「共同海損分擔」）。'),
('p2', 325, '一', '一般保險產品類別', '326. 以下哪項對共同海損的描述是不正確的？', '{"A":"當整體冒險事業出現危機時出現","B":"整體事業最終是得救的","C":"本質上不屬於犧牲的","D":"出現損失時必須共同承擔"}'::jsonb, 'C', '凡在發生危險時，為了保存共同冒險中陷於危險中的財產而自願和合理地作出或招致任何特殊犧牲或費用，屬於共同海損行為。'),
('p2', 326, '一', '一般保險產品類別', '327. 為了犧牲而成功挽救冒險事業，而損失者可以向其他利益代表索取分擔出現的損失。這個慣例稱為：', '{"A":"分攤","B":"代位權","C":"共同海損","D":"按比例海損"}'::jsonb, 'C', '凡在發生危險時，為了保存共同冒險中陷於危險中的財產而自願和合理地作出或招致任何特殊犧牲或費用，屬於共同海損行為。'),
('p2', 327, '一', '一般保險產品類別', '328. 在水險保單中，下列哪三個構成損失的原因不是推定全損而是實際全損？
i. 船隻被火災完全摧毀
ii. 船隻在風暴中消失
iii. 船隻被盜且不能找回
iv. 船隻嚴重損毀在經濟角度上而言不值得維修', '{"A":"i, ii, iii","B":"ii, iii, iv","C":"i, iii, iv","D":"i, ii, iv"}'::jsonb, 'A', '保險標的被毀掉、保險標的遭損壞的程度使其不再屬受保類別的物品或被保險人已在無法挽回的情況下失去該保險標的為實際全損。'),
('p2', 328, '一', '一般保險產品類別', '329. 以下哪項對船東保賠組織的描述是正確的？', '{"A":"主要是為船體碰撞的責任負責","B":"提供代表船東運作的自保計劃","C":"屬於相互賠償社的組織","D":"以上所有各項"}'::jsonb, 'D', '船東保賠組織成立的目的是向本身的會員船東提供某些不易從商業保險人（或牟利保險人）那裏購得的保險，屬於自保計劃/相互賠償社的例子。'),
('p2', 329, '一', '一般保險產品類別', '330. 船東保賠組織是一個：', '{"A":"註冊的慈善機構","B":"獨資貿易商的組織","C":"相互賠償社","D":"專利(合股)公司"}'::jsonb, 'C', '船東保賠組織成立的目的是向本身的會員船東提供某些不易從商業保險人（或牟利保險人）那裏購得的保險，屬於自保計劃/相互賠償社的例子。'),
('p2', 330, '一', '一般保險產品類別', '331. 在水險的責任風險保險：', '{"A":"通常包括在水險保單","B":"是不會出現在水險保單","C":"是法律強制性的要求","D":"大部份是由船東保賠組織提供保障"}'::jsonb, 'D', '船東保賠組織成立的目的是向本身的會員船東提供某些不易從商業保險人（或牟利保險人）那裏購得的保險，屬於自保計劃/相互賠償社的例子。'),
('p2', 331, '一', '一般保險產品類別', '332. 「協會條款」在水險中是以編號條款形式構成一套公認的合約用詞，這協會是：', '{"A":"美國保險人協會","B":"倫敦保險人協會","C":"香港保險人協會","D":"水險保險人協會"}'::jsonb, 'B', '倫敦保險人協會條款在國際水險業中聲譽卓著，是被公認的保單措詞，並且幾乎被全球所有的保險人、銀行和有利害關係的機構所採納使用。'),
('p2', 332, '一', '一般保險產品類別', '333. 對於海上貨物保險，以下哪項的保障陳述是正確的？', '{"A":"包括共同海損，而不包括救助費用","B":"包括救助費用，而不包括共同海損","C":"共同海損及救助費用均為保障範圍","D":"共同海損及救助費用均不屬保障範圍"}'::jsonb, 'C', '共同海損及救助費用均為保障範圍。'),
('p2', 333, '一', '一般保險產品類別', '334. 在貨物條款的保障下，「倉至倉」的保障形式是：', '{"A":"只涉及陸路的運送","B":"只涉及水路上的運送","C":"全個運送過程，包括陸路及水路上的運送","D":"只包括由港口運抵貨倉途中的運送"}'::jsonb, 'C', '海上貨物保險保障大多數是「倉至倉」的保障，意思是保險保障自貨物離開發貨人的倉庫時開始，直至到達最終存放目的地時完結。這幾乎一定會同時涉及陸路和水上的運送。'),
('p2', 334, '一', '一般保險產品類別', '335. 以下哪項在水險中提供最廣闊的保障範圍？', '{"A":"約定價值保單","B":"協會貨物條款A","C":"協會貨物條款B","D":"協會貨物條款C"}'::jsonb, 'B', '協會貨物條款A(ICC(A))：有關的本身損害保險保障是「全險」的，很多時候這是就付運的貨物提供貸款或保證的銀行唯一可以接納的保險保障。'),
('p2', 335, '一', '一般保險產品類別', '336. 海上貨物保險的保障範圍？', '{"A":"只可以水路上的","B":"只可以陸路上的","C":"水路陸路都可以，水路到貨艙之間","D":"貨倉到貨倉之間"}'::jsonb, 'D', '海上貨物保險保障大多數是「倉至倉」的保障，意思是保險保障自貨物離開發貨人的倉庫時開始，直至到達最終存放目的地時完結。這幾乎一定會同時涉及陸路和水上的運送。'),
('p2', 336, '一', '一般保險產品類別', '337. 下列哪三種水險，是以「特定危險」為根據？
i. 貨物條款A
ii. 貨物條款B
iii. 貨物條款C
iv. 遊艇條款保險', '{"A":"i, ii, iii","B":"i, ii, iv","C":"ii, iii, iv","D":"i, ii, iii , iv"}'::jsonb, 'C', '協會貨物條款A(ICC(A))：有關的本身損害保險保障是「全險」的，很多時候這是就付運的貨物提供貸款或保證的銀行唯一可以接納的保險保障，而其他條款則以特定危險為根據。'),
('p2', 337, '一', '一般保險產品類別', '338. 協會貨物條款(A)是以「全險」作為根據，以下哪項是會得到保障？', '{"A":"在火災中被燒的貨物","B":"在運送途中被盜竊的貨物","C":"在航行中，被大浪捲走的貨物","D":"以上所有各項"}'::jsonb, 'D', '所有情況均為保障範圍內。'),
('p2', 338, '一', '一般保險產品類別', '339. 以下哪項海上保險是以「全險」型式發出的？
i. 船體保險
ii. 協會貨物條款A
iii. 協會貨物條款B
iv. 遊艇保險', '{"A":"只有 ii","B":"i, ii","C":"ii, iii","D":"i, ii, iii, iv"}'::jsonb, 'A', '協會貨物條款A(ICC(A))：有關的本身損害保險保障是「全險」的，很多時候這是就付運的貨物提供貸款或保證的銀行唯一可以接納的保險保障，而其他條款則以特定危險為根據。'),
('p2', 339, '一', '一般保險產品類別', '340. 以下哪項是海洋船體保險的保障範圍的標準特點?
i. 損害防止的開支
ii. 共同海損及救助費用
iii. 保障船主所承受的一切責任風險
iv. 保障範圍包括船隻整體及設備的損失及損毀', '{"A":"i, ii","B":"ii, iii","C":"i, ii, iv","D":"i, ii, iii, iv"}'::jsonb, 'C', '「財產損害」、共同海損和救助費用、損害防止費用及碰撞責任(保單只負責該等法律責任的 75%)為保障範圍內。'),
('p2', 340, '一', '一般保險產品類別', '341. 在船體保險中的定值保險的保障包括：', '{"A":"只當在全損的情況下提供賠償","B":"只賠償部份損失","C":"這種保單沒有保額","D":"賠償時不需扣減損耗"}'::jsonb, 'D', '賠償是按照以新代舊(new forold)的原則作出的，即不就損耗及折舊作扣減。'),
('p2', 341, '一', '一般保險產品類別', '342. 在船體碰撞責任作面，以下哪個機構會提供最大的責任保障？', '{"A":"船東保賠組織","B":"有關之保險人","C":"倫敦保險人協會","D":"負責處理之保險代理人"}'::jsonb, 'B', '「財產損害」、共同海損和救助費用、損害防止費用及碰撞責任(保單/保險人只負責該等法律責任的75%)為保障範圍內。'),
('p2', 342, '一', '一般保險產品類別', '343. 在船體保險中，保單只負責碰撞責任的：', '{"A":"0.9","B":"0.1","C":"0.25","D":"0.75"}'::jsonb, 'D', '「財產損害」、共同海損和救助費用、損害防止費用及碰撞責任(保單/保險人只負責該等法律責任的75%)為保障範圍內。'),
('p2', 343, '一', '一般保險產品類別', '344. 船體保險中的免賠額是：', '{"A":"約束著部份海損索償","B":"約束著全部損失的索償","C":"約束著部份海損及全部損失的索償","D":"部份海損及全部損失都不受約束"}'::jsonb, 'A', '免賠額就部分損失而非全損索償設定了免賠額，這與其他險種的做法有所不同。'),
('p2', 344, '一', '一般保險產品類別', '345. 海洋船體保險保費的釐定是根據：', '{"A":"船上貨物的價值","B":"被保險人的索償經驗","C":"船東的年齡","D":"船隻的大小"}'::jsonb, 'B', '保費的釐定很大程度上受個別被保險人的索償經驗影響。儘管是同一艘船，如果船東或管理人另有其人，應付的保費就可以有極其顯著的差別。'),
('p2', 345, '一', '一般保險產品類別', '346. 下列哪項對「遊艇條款」描述不正確？', '{"A":"免賠額不包括全部損失的賠償","B":"不包括責任權益","C":"倫敦保險人協會規定，以「指明危險」作為基準","D":"特快遊艇(超過十七海浬)需採用快艇條款"}'::jsonb, 'B', '很多承保遊艇的保單同時承保財產及責任風險。'),
('p2', 346, '一', '一般保險產品類別', '347. 以下哪項屬於遊艇保險的除外責任', '{"A":"遊艇上的釣魚裝備","B":"船外的引擎跌落水中","C":"沒有標記母艇名稱的小艇","D":"以上各項"}'::jsonb, 'D', '除外責任包括：(i) 裝於船外的引擎落入或跌落水中。(ii) 個人財物。(iii)可消耗的物料、釣魚裝備用具及繫泊用具。(iv) 該船的小艇如果沒有展示母艇的名稱作為永久的標記。'),
('p2', 347, '一', '一般保險產品類別', '348. 以下哪項屬於遊艇保險的除外責任', '{"A":"遊艇上的釣魚裝備","B":"船外的引擎跌落水中","C":"個人財物","D":"以上各項"}'::jsonb, 'D', '除外責任包括：(i) 裝於船外的引擎落入或跌落水中。(ii) 個人財物。(iii)可消耗的物料、釣魚裝備用具及繫泊用具。(iv) 該船的小艇如果沒有展示母艇的名稱作為永久的標記。'),
('p2', 348, '一', '一般保險產品類別', '349. 遊艇保險的理賠通常基於不折舊的方法。但對於某些例外的物品可能會作出折舊扣減，而最高折舊扣減額為原值的三分之一，例如：
i. 船帆
ii. 船外的引擎
iii. 船隻的小艇
iv. 船上的個人財物', '{"A":"i, ii","B":"i, ii, iii","C":"ii, iii, iv","D":"i, ii, iii, iv"}'::jsonb, 'A', '本身損害索償的結清是按以新代舊原則進行的但某些指明物品（例如船帆及安裝於船外的引擎）則須進行折舊扣減，最高扣減額為三分之一。'),
('p2', 349, '一', '一般保險產品類別', '350. 戰爭和類似風險:', '{"A":"是商業保險永不提供","B":"是所有險種都自由地提供","C":"可能會在汽車和火災保險中找到","D":"可能會在水和航空保單找到"}'::jsonb, 'D', '戰爭、罷工等風險引起的損失；水上保障中可支付額外保費及採用協會戰爭及罷工條款來投保此等危險。'),
('p2', 350, '一', '一般保險產品類別', '351. 船體險保單中免賠額，不適用於：', '{"A":"火險索償","B":"失竊索償","C":"全損索償","D":"單獨海損索償"}'::jsonb, 'C', '船體險保單就部分損失而非全損索償設定了免賠額，這與其他險種的做法有所不同。'),
('p2', 351, '一', '一般保險產品類別', '352. 在水險中的定值保單是指:
i.承諾全損保險保障
ii. 同意部分損失保險保障
iii. 沒有指明保額
iv. 為了商業上的方便購買', '{"A":"i, ii, iii","B":"i, ii, iv","C":"i, iii, iv","D":"i, ii. iii, iv"}'::jsonb, 'B', '為了商業上的方便，承保船隻或貨物的保險一般是以約定價值方式提供保險保障的—除了保額以外，保單還指明一個約定價值。就全損及部分損失而言，該約定價值將被當作是損失發生時的財產價值。'),
('p2', 352, '一', '一般保險產品類別', '353. 通常用於非全損免賠額保單可能是:', '{"A":"盜竊保險","B":"船體保險","C":"貨物保險","D":"火災及指明危險保險"}'::jsonb, 'B', '船體保險單就部分損失而非全損索償設定了免賠額，這與其他險種的做法有所不同。'),
('p2', 353, '一', '一般保險產品類別', '354. 1,000,000元保額的單獨海損的免賠額為損失的5%，當出現索償時，被保險人須承擔：', '{"A":"50,000元(對於全部損失索償)","B":"950,000元(對於非全部損失索償)","C":"1,000,000元(對於非全部損失索償)","D":"0元(對於全部損失索償)"}'::jsonb, 'D', '免賠額就部分損失而非全損索償設定了免賠額，這與其他險種的做法有所不同。'),
('p2', 354, '一', '一般保險產品類別', '355. 船體碰撞損毀發生，「船舶」保險會提供部份賠償，「船體」保險通常佔的比例是:', '{"A":"一半","B":"十分之一","C":"四分之一","D":"四分之三"}'::jsonb, 'D', '「財產損害」、共同海損和救助費用、損害防止費用及碰撞責任(保單/保險人只負責該等法律責任的75%)為保障範圍內。'),
('p2', 355, '二', '核保、投保文件與保單結構', '1. 在核保的過程，人壽保險及一般保險的基本分別在於', '{"A":"人壽保險核保屬於「一次過」事件","B":"一般保險核保屬於「一次過」事件","C":"一般保險只涉及實質危險","D":"一般保險通常涉及較低的保額"}'::jsonb, 'A', '人壽保險核保屬於「一次過」事件，有別於人壽保險，一般保險的風險評估是一個持續的、或最低限度是可重複的過程。'),
('p2', 356, '二', '核保、投保文件與保單結構', '2. 核保的程序涉及：', '{"A":"風險的類別","B":"風險的選擇","C":"決定標準合約的條款","D":"以上所有各項"}'::jsonb, 'D', '以上三種均為核保過程中的重要過程。'),
('p2', 357, '二', '核保、投保文件與保單結構', '3. 一般在判定一項風險的可保性和決定採納甚麼合約條件的人是：', '{"A":"代理人","B":"核保人","C":"保險經紀","D":"保險公司的行政總裁"}'::jsonb, 'B', '核保人將負責整個核保過程。'),
('p2', 358, '二', '核保、投保文件與保單結構', '4. 核保過程涉及：', '{"A":"選擇風險，但不涉及保險合約的條款","B":"選擇承保的風險及合約的條款","C":"只涉及釐訂保費","D":"以上所有各項"}'::jsonb, 'B', '核保重要過程包括選擇風險(判斷可保性)及 決定合約條款。'),
('p2', 359, '二', '核保、投保文件與保單結構', '5. 投保書屬於被保險人對保險人投保時的重要文件，用於向保險人披露重要事實，披露重要事實屬於那個壽險原則？', '{"A":"可保權益","B":"近因","C":"彌償","D":"最高誠信"}'::jsonb, 'D', '投保人必須遵守最高誠信責任，即是無論保險人有沒有明確發問，投保人都有義務披露所有的重要事實。'),
('p2', 360, '二', '核保、投保文件與保單結構', '6. 被保人有意不披露關於投保物件的重要事實或資料，而當保險人知道會拒絕受保，這種行為稱為:', '{"A":"無知","B":"欺詐","C":"最高誠信","D":"可保利益"}'::jsonb, 'C', '投保人必須遵守最高誠信責任，即是無論保險人有沒有明確發問，投保人都有義務披露所有的重要事實。'),
('p2', 361, '二', '核保、投保文件與保單結構', '7. 某個術語用在一般保險中，含義和人壽保險中的「申請表」相同。這個術語是：', '{"A":"保險憑証","B":"暫保單","C":"投保書","D":"續保要求"}'::jsonb, 'C', '投保書也稱為投保單、申請表，當中以申請表在人壽保險中用得較為普遍。投保書是一種問卷形式的文件，必須由投保人在提出保險保障申請時填寫。'),
('p2', 362, '二', '核保、投保文件與保單結構', '8. 違反最高誠信是:', '{"A":"令保單無效","B":"令受損害一方有權可以將保單無效","C":"保單無效可將保費沒收","D":"以上全部皆不是"}'::jsonb, 'B', '如投保人違反最高誠信，保險人可令保單變成無效的合約。'),
('p2', 363, '二', '核保、投保文件與保單結構', '9. 以下那項不屬於保單中的重要事實?', '{"A":"五十五歲的投保人(公眾責任)","B":"儲存大量汽油的辦公室(火險)","C":"多次被盜竊的地方(家居保險)","D":"曾遭意外導致雙足殘廢(意外保險)"}'::jsonb, 'A', '五十五歲的投保人 (年紀)與公眾責任並不構成直接的關係。'),
('p2', 364, '二', '核保、投保文件與保單結構', '10. 當被保人明知自己有心臟問題但不披露，保單會:', '{"A":"不受影響","B":"只保障其他疾病","C":"被保險公司決定是否無效","D":"自動延伸保障範圍"}'::jsonb, 'C', '如投保人違反最高誠信，保險人可令保單變成無效的合約。'),
('p2', 365, '二', '核保、投保文件與保單結構', '11. 專業評估風險', '{"A":"只會考慮或實質(物質)危險","B":"只關心人性元素","C":"和實質和道德危險有關","D":"可以由估價表計算"}'::jsonb, 'C', '對特定的投保進行風險評估時，核保人有必要全面了解該實際危險及道德危險。'),
('p2', 366, '二', '核保、投保文件與保單結構', '12. 指出下面哪一句是正確', '{"A":"所有保險合約一定要由書面作證","B":"不論有沒有被問到，普通法重要事實一定要披露","C":"違反保險保証，一定要和索償情況有關係，保險人才可以拒絕責任","D":"損害賠償永不適用在個人保險"}'::jsonb, 'B', '重要事實的法律定義為：「在訂定保費或決定是否承擔風險方面會影響一名審慎的保險人的判斷的任何情況」，投保人必須遵守最高誠信責任，即是無論保險人有沒有明確發問，投保人都有義務披露所有的重要事實。'),
('p2', 367, '二', '核保、投保文件與保單結構', '13. 任何對投保風險的可保性或可能採用的條件造成不利影響的資料，可被描述為：', '{"A":"重要事實","B":"必要事實","C":"基本事實","D":"核保要求"}'::jsonb, 'A', '重要事實是「必須申報的實情」（這是法律的規定，也好讓核保人對有關擬保風險能夠作出專業的評估）。'),
('p2', 368, '二', '核保、投保文件與保單結構', '14. 以下哪項屬於非重要事實？', '{"A":"改善或降低有關風險的事實","B":"過往的損失經驗","C":"以往的索償的經驗","D":"以上所有各項"}'::jsonb, 'A', '改善或降低風險的情況屬於「非重要」事實。'),
('p2', 369, '二', '核保、投保文件與保單結構', '15. 以下哪項屬於不須披露的重要事實？', '{"A":"一項減低風險的事實","B":"涉及過往賠償及損失的事實","C":"風險比預期大","D":"潛在損失比預期大"}'::jsonb, 'A', '改善或降低風險的情況屬於「非重要」事實，所以屬於不須披露的重要事實。'),
('p2', 370, '二', '核保、投保文件與保單結構', '16. 在農業保險申請表中，以下那項不屬於重要事實？', '{"A":"減低水災發生的事實","B":"在以往經歷中，涉及不受保險保障的水災索償的事實","C":"涉及風險大於正常的事實","D":"可能出現損失的程度高於標準水平"}'::jsonb, 'A', '改善或降低風險的情況屬於「非重要」事實，所以屬於不須披露的重要事實。'),
('p2', 371, '二', '核保、投保文件與保單結構', '17. 在正常情況下，要証明一項事實的重要性是屬於：', '{"A":"保險人的責任","B":"被保人的責任","C":"保險人及被保險人的責任","D":"由法庭裁決"}'::jsonb, 'A', '如果有不明確的情況，保險人一般有責任證明有關事實是重要的，而投保人所提供的資料是不充分的。這項責任是不容易完成的。'),
('p2', 372, '二', '核保、投保文件與保單結構', '18. 在一般保險中，風險估定以確定風險的可保性是：', '{"A":"只在保單索償時進行","B":"只在保單續保時進行","C":"在保單續保或其他時候重覆進行","D":"只在保單開始時進行"}'::jsonb, 'C', '風險評估通常出現在投保階段、保單續保的時候、索償發生時、對現有條款作重大更改時及風險有所變化的時間。'),
('p2', 373, '二', '核保、投保文件與保單結構', '19. 核保一般保險的特性：', '{"A":"保單條款與人壽保險一樣，核保之後便不能改變","B":"與人壽保險類似，但不涉及可保權益的考慮","C":"與人壽保險一樣，可保權益只需在保單開始時存在","D":"需要持續核保，每年續約或更新保單條件"}'::jsonb, 'D', '一般保險的風險評估是一個持續的、或最低限度是可重複的過程。'),
('p2', 374, '二', '核保、投保文件與保單結構', '20. 保險核保人在風險評估過程中，可能涉及：', '{"A":"風險的可保性","B":"標準保費是否合適","C":"是否要採納自負額或免賠額","D":"以上所有各項"}'::jsonb, 'D', '可保性(接納)、標準保費及措辭、自負額等都是風險評估的相關因素。'),
('p2', 375, '二', '核保、投保文件與保單結構', '21. 風險的估定是實質本性與有關事實的結合，可稱為 :', '{"A":"核保人承保的考慮因素","B":"道德危險","C":"實質危險","D":"受保商數"}'::jsonb, 'C', '實質危險指的是風險的客觀、物質性本質，即是明顯而且容易被確認的特點，這將影響發生損失的機會，及其嚴重程度。'),
('p2', 376, '二', '核保、投保文件與保單結構', '22. 結構、佔用和位置是會作為評估火災危險的因素', '{"A":"是","B":"除了佔用; 是","C":"假","D":"除了結構; 假"}'::jsonb, 'A', '建築材料對火險的重要性是十分明顯的。木質建築物比起混凝土的同類型建築物自然要付更高的保費。'),
('p2', 377, '二', '核保、投保文件與保單結構', '23. 以下哪句句子正確:', '{"A":"實質危險通常是比道德危險較容易評估","B":"雖然不是法律要求，投保書在主要的險種都恆久採用","C":"責任出現前的先決條件是合約的基準原則","D":"責任出現後的先決條件是合約的基準原則"}'::jsonb, 'A', '比起實質危險，道德危險屬於較主觀及較難理解的概念。'),
('p2', 378, '二', '核保、投保文件與保單結構', '24. 下例那項並不是道德危險的例子:', '{"A":"粗心大意","B":"心思熟慮","C":"不合情理","D":"不誠實"}'::jsonb, 'B', '我們可以簡述道德危險可能出現的負面形態如下:不誠實、粗心大意及魯莽、不合情理及反社會行為。'),
('p2', 379, '二', '核保、投保文件與保單結構', '25. 以下哪項危險屬於較易理解及辦別，而且擁有客觀的特質？', '{"A":"道德危險","B":"非道德危險","C":"實質危險","D":"非實質危險"}'::jsonb, 'C', '實質危險指的是風險的客觀、物質性本質，即是明顯而且容易被確認的特點，這將影響發生損失的機會，及其嚴重程度。'),
('p2', 380, '二', '核保、投保文件與保單結構', '26. 以下哪一項不屬於在一般情況下影響一項風險的實質危險?', '{"A":"引起盜竊的吸引力(盜竊保險)","B":"令人不滿的索償經驗","C":"被保險對索償的無理態度","D":"被保險人的身體狀況(個人意外保險)"}'::jsonb, 'C', '被保險對索償的無理態度屬於道德風險。'),
('p2', 381, '二', '核保、投保文件與保單結構', '27. 在不同保險業務類別中，以下哪些風險與實質危險有關？
i. 受保物件的實質價值(盜竊險)
ii. 被保人及其員工的粗心大意(意外保險)
iii. 被保人職業(公眾責任保險)
iv. 被保建築物的建築結構(火險)', '{"A":"(i), (ii), (iii)","B":"(i), (ii), (iv)","C":"(i), (iii), (iv)","D":"(ii), (iii), (iv)"}'::jsonb, 'C', '被保人及其員工的粗心大意(意外保險)屬道德危險。'),
('p2', 382, '二', '核保、投保文件與保單結構', '28. 投保書中問題的答案可能會引起保險人的進一步查詢(檢驗)，例如：', '{"A":"大額款項的盜竊保險","B":"曾多次意外撞車的汽車保險","C":"大額的建築火險保險","D":"以上所有各項"}'::jsonb, 'D', '以上三個情況保險人將會以實際危險(有關客觀發生的事實)的方式用於核保的過程。'),
('p2', 383, '二', '核保、投保文件與保單結構', '29. 當為火災保險作實質危險估定時，應考慮哪些因素？', '{"A":"結構物料","B":"投保人年齡","C":"投保人之道德操守","D":"以上全部都不是"}'::jsonb, 'A', '建築材料對火險的重要性是十分明顯的。木質建築物比起混凝土的同類型建築物自然要付更高的保費。'),
('p2', 384, '二', '核保、投保文件與保單結構', '30. 以下哪一項不是影響一項風險的道德危險？', '{"A":"被保險人一方的不誠實","B":"建築物中的建築材料","C":"被保險人及受僱僱員的粗心大意","D":"被保險人對索償的無理態度"}'::jsonb, 'B', '建築材料對火險的重要性是十分明顯的。木質建築物比起混凝土的同類型建築物自然要付更高的保費，以上為實質危險。'),
('p2', 385, '二', '核保、投保文件與保單結構', '31. 想處理不利的道德危險是困難的，原因是:', '{"A":"投保人時常會告訴事實的全部","B":"投保人時常不會告訴事實的全部","C":"每個人都不同","D":"以上全部皆不是"}'::jsonb, 'B', '把道德危險作為「人性元素」來考慮，或許更能明白其中的含義。也就是說，這是指被保險人及其他與該風險有關的人（例如被保險人的家庭成員和僱員）的態度、行為及操守的本質和特點。'),
('p2', 386, '二', '核保、投保文件與保單結構', '32. 以下哪項是道德危險的不正確描述？', '{"A":"涉及人性行為的特點","B":"道德危險有分為好與壞","C":"不單涉及不誠實，還涉及主觀的特點","D":"比實質危險容易察覺"}'::jsonb, 'D', '比起實質危險，道德危險屬於較主觀及較難理解的概念。'),
('p2', 387, '二', '核保、投保文件與保單結構', '33. 一些主觀因素，如態度、行為及操守都可以成為評估風險的考慮因素，這些因素亦稱為：', '{"A":"實質(物質)危險","B":"道德危險","C":"重要事實","D":"檢驗報告"}'::jsonb, 'B', '把道德危險作為「人性元素」來考慮，或許更能明白其中的含義。也就是說，這是指被保險人及其他與該風險有關的人（例如被保險人的家庭成員和僱員）的態度、行為及操守的本質和特點。'),
('p2', 388, '二', '核保、投保文件與保單結構', '34. 被保人不合情理:', '{"A":"會構成不利的道德危險","B":"會構成不利的實質危險","C":"意思是保險人會對索償制度上加大困難","D":"意思是風險不能投保"}'::jsonb, 'A', '道德危險通常教人把焦點放在被保險人的道德行為和準則上。儘管這些都是重要的，而且肯定是屬於道德危險，但是它的意義更為廣泛，還包括了態度、生活方式及粗心大意之類。'),
('p2', 389, '二', '核保、投保文件與保單結構', '35. 下列那項並不是道德危險的例子', '{"A":"粗心大意","B":"心思熟慮","C":"不合情理","D":"不誠實"}'::jsonb, 'B', '道德危險，但是它的意義更為廣泛，還包括了態度、生活方式及粗心大意之類。'),
('p2', 390, '二', '核保、投保文件與保單結構', '36. 以下哪項不是投保書的主體問題？', '{"A":"投保人的姓名","B":"投保人的地址","C":"投保人的年齡","D":"投保人過往的索償經驗"}'::jsonb, 'C', '投保人的詳情：諸如姓名、地址及職業。這些內容可能影響實質危險，而且是身份識別及溝通的必需資料。保險經歷：核保人需要知道被保險人是否還購買了其他保險，以及是否曾經遭到其他保險人拒保或施加異常限制的條款。'),
('p2', 391, '二', '核保、投保文件與保單結構', '37. 擬定投保書中的問題時，會選擇以下哪項作為根據？', '{"A":"投保人的詳情","B":"投保人的保險經歷","C":"投保人的損失及索償經歷","D":"以上全部各項"}'::jsonb, 'D', '保險經歷、投保人的詳情、損失／索償經歷及被保險人所作的估值都是擬定投保書的內容。'),
('p2', 392, '二', '核保、投保文件與保單結構', '38. 投保人的名稱在投保書:', '{"A":"可能會對評估實質危險重要","B":"只會對身份記認目的有意義","C":"會對收的保費是個人很重要的因素","D":"不是真正保險人需要的"}'::jsonb, 'A', '投保人的詳情：諸如姓名、地址及職業。這些內容可能影響實質危險，而且是身份識別及溝通的必需資料。'),
('p2', 393, '二', '核保、投保文件與保單結構', '39. 投保書是一種工具，投保人可利用這文件提交投保風險的詳細介紹，當中的態度必須符合以下哪項保險原則？', '{"A":"可保權益","B":"最高誠信","C":"近因","D":"代位權"}'::jsonb, 'B', '承保人可以透過很多方法和渠道，例如投保書，獲取擬保風險的重要事實的詳情。'),
('p2', 394, '二', '核保、投保文件與保單結構', '40. 以下哪項或哪些資料屬於投買汽車保險時的重要範圍
i. 投保人的詳細資料，例如：姓名、地址
ii. 投保人的職業
iii. 投保人的年齡
iv. 投保人的損失 / 索償經歷', '{"A":"i, ii, iii","B":"i, ii, iv","C":"ii, iii, iv","D":"i, ii, iii, iv"}'::jsonb, 'D', '保險經歷、投保人的詳情、損失／索償經歷及被保險人所作的估值都是擬定投保書的內容。'),
('p2', 395, '二', '核保、投保文件與保單結構', '41. 以下哪項一般保險業務，填妥的投保書是唯一的資料來源？', '{"A":"火險","B":"盜竊險","C":"汽車保險(私家車)","D":"公眾責任"}'::jsonb, 'C', '某些業務類別（大多數是個人險種，例如私家車）的投保書，基本上是核保資料的唯一來源。'),
('p2', 396, '二', '核保、投保文件與保單結構', '42. 以下哪項對一般保險的風險估定以確定風險的可保性描述並不正確', '{"A":"保單起保時","B":"保單續保和索償的時候，提供再次檢討的機會。","C":"保單是可以由保險人取消","D":"有別於人壽保險，一般保險的風險估定是一個持續的過程"}'::jsonb, 'A', '通常風險評估出現在投保階段、保單續保時、索償發生時、擬對現有條款作出重大更改時及風險有所變化的時間。'),
('p2', 397, '二', '核保、投保文件與保單結構', '43. 甚麼風險因素可影響道德危險?', '{"A":"建築物類別 (財產保險)","B":"個人健康狀況(個人意外保險)","C":"在索償時的不合情理(汽車保險)","D":"以上所有各項"}'::jsonb, 'C', '比起實質危險，道德危險屬於較主觀及較難理解的概念'),
('p2', 398, '二', '核保、投保文件與保單結構', '44. 對於某些險種，以下哪項可能是核保資料的唯一來源', '{"A":"投保書","B":"檢驗人的報告","C":"獨立的醫療報告","D":"以上皆是"}'::jsonb, 'A', '保險人可透過不同途徑以取得重要事實協助進行核保'),
('p2', 399, '二', '核保、投保文件與保單結構', '45. 以下那一項與人壽保險的申請表的基本定義是一致的', '{"A":"投保書","B":"重要事實","C":"保險單","D":"保險憑證"}'::jsonb, 'A', '投保書是一般保險中的投保問卷，與人壽保險的申請表是一致的'),
('p2', 400, '二', '核保、投保文件與保單結構', '46. 以下哪項或哪些有關保險報價的說明是正確的？', '{"A":"它以書面或口頭形式出現","B":"它可以涉及有關保費及（或）合約條款","C":"在法律上，要求一項報價可視為一項合約的要約","D":"以上各項皆是"}'::jsonb, 'D', '以報價的形式提供，其中包括以下一種或多種特點：(a) 可以是書面或口頭的；(b)可以只涉及設想中的保費，或同時提及其他的合約條款；(c)報價可能被視為可供承約的要約行為，因此必須在採用「報價」等詞及草擬報價單的文字時特別小心。'),
('p2', 401, '二', '核保、投保文件與保單結構', '47. 由客人查詢，經保險公司以書面發出但並不代表實際保費的稱為：', '{"A":"報價","B":"建議書","C":"投保書","D":"保單"}'::jsonb, 'A', '報價可以只涉及設想中的保費，或同時提及其他的合約條款'),
('p2', 402, '二', '核保、投保文件與保單結構', '48. 在一般保險中的報價是：', '{"A":"被保險中給投保人的；","B":"所有經安排的合約，均有這個特別項目","C":"表示保險人接納投保人的要約；","D":"在法律上代表保險人發出的一項正式要約"}'::jsonb, 'D', '報價可能被視為可供承約的要約行為，因此必須在採用「報價」等詞及草擬報價單的文字時特別小心。'),
('p2', 403, '二', '核保、投保文件與保單結構', '49. 以下哪項是對報價的不正確描述？', '{"A":"可以是書面或口頭","B":"這代表保險人的一項要約","C":"內容只可作為參考用途","D":"當中涉及的保費已是最終的決定"}'::jsonb, 'D', '報價可能被視為可供承約的要約行為，而不是最終決定。'),
('p2', 404, '二', '核保、投保文件與保單結構', '50. 以下哪項關於投保書的描述是不正確的？', '{"A":"保單一經批核，便不需要保存投保書","B":"有時可能是核保的唯一資料來源","C":"專家的報告被視為投保書的輔助文件","D":"投保書的資料及聲明是合約的基礎"}'::jsonb, 'A', '已完成的投保書擔當着重要的角色，所以它不應被視為暫時性的文件。'),
('p2', 405, '二', '核保、投保文件與保單結構', '51. 以下哪一項關於投保書是不正確的？', '{"A":"空白表格不是保險人所發出的合約要約","B":"它有時是核保的資料來源","C":"它是由保險中介人所設計及印製的","D":"以上所有各項"}'::jsonb, 'C', '投保書由保險人所設計及印製的。'),
('p2', 406, '二', '核保、投保文件與保單結構', '52. 以下哪項對於投保書的描述是正確的？', '{"A":"在核保之後便失去功用","B":"於續保時才有功用","C":"屬於主要文件，而任何附加資料亦視作投保書一部份","D":"完全沒用，可隨時丟棄"}'::jsonb, 'C', '已完成的投保書擔當着重要的角色，所以它不應被視為暫時性的文件。一些保險人在寄發保單文件的同時，也會附上已填妥的投保書的副本，以提醒被保險人他自己曾經提供過什麽資料，而且這些資料已成為保險人所作承諾的基礎。'),
('p2', 407, '二', '核保、投保文件與保單結構', '53. 在火險或意外險的投保書的聲明:', '{"A":"是用來延伸最高誠信的責任","B":"令全部投保書和合約都受制於最高誠信","C":"要獨立証人見証","D":"以上全部皆不是"}'::jsonb, 'A', '投保書的資料是保險人獲取擬保風險的重要事實的詳情。'),
('p2', 408, '二', '核保、投保文件與保單結構', '54. 導致一般保險合約的訂立及形成保險人承諾基礎的資料主要來源：', '{"A":"保單","B":"保險保證","C":"暫保單","D":"填妥的投保書"}'::jsonb, 'D', '投保書上提供的資料是承保人可用於核保決定的主要資料。'),
('p2', 409, '二', '核保、投保文件與保單結構', '55. 簽發的投保書交給保險人後：', '{"A":"保單便具有約束力","B":"投保書的作用便完成，可以棄置","C":"保險人不可再索取進一步資料","D":"保險人應好好保存，供日後作參考之用"}'::jsonb, 'D', '投保書對合約而言擔當着重要的角色，所以它不應被視為暫時性的文件。正由於它的重要性，一些保險人在寄發保單文件的同時，也會附上已填妥的投保書的副本，以提醒被保險人他自己曾經提供過什麽資料，而且這些資料已成為保險人所作承諾的基礎。'),
('p2', 410, '二', '核保、投保文件與保單結構', '56. 在一般保險的業務來說，除了投保書，還有額外的文件(如專家報告)，這文件：', '{"A":"不構成投保書的一部份","B":"屬例行公事，對保單的風險評估並無作用","C":"通常由投保人提供及支付有關費用","D":"構成投保書的一部份，並須知會投保人"}'::jsonb, 'D', '任何專家的報告或其他文件必須視為投保書的一部分，這個事實應該讓投保人加以注意。'),
('p2', 411, '二', '核保、投保文件與保單結構', '57. 以下哪項是對暫保單的描述是正確的？', '{"A":"暫保單是暫時性的文件，會被保單取代","B":"它與保單憑証的性質完全相同","C":"它視乎投保書的資料是否足夠","D":"以上所有各項"}'::jsonb, 'A', '暫保單是一份暫時性的文件，它實際上構成一份暫時性保單。'),
('p2', 412, '二', '核保、投保文件與保單結構', '58. 暫保單：', '{"A":"確認保險保障的文件","B":"稍後被正式保單所取代","C":"設有取消條款","D":"以上所列各項皆是"}'::jsonb, 'D', '暫保單是一份暫時性的文件，它實際上構成一份暫時性保單。同時，稍後會被保險單取代以及暫保單中通常設有取消條文，容許保險人按照規定發出通知就可以中止保險保障。'),
('p2', 413, '二', '核保、投保文件與保單結構', '59. 以下哪一項有關保險憑證是正確的？', '{"A":"其功能與暫保單相似","B":"是一份額外之永久性文件","C":"此乃強制性保險之憑證","D":"以上所有各項"}'::jsonb, 'D', '以上三項均為保險憑證的元素。'),
('p2', 414, '二', '核保、投保文件與保單結構', '60. 以下哪項對保險單的描述是正確的？', '{"A":"它是以蓋印形式簽發的","B":"它一經簽發便不可取消","C":"它是保險合約的證據","D":"以上所有各項"}'::jsonb, 'C', '在法律上，保單的正確性是可以被質疑的，但是法律一般假設合約的內容已顯示了各方的意圖，除非能提出有力證據以作反證。'),
('p2', 415, '二', '核保、投保文件與保單結構', '61. 一般保險中，保險的證據的基本文件是：', '{"A":"保單","B":"暫保單","C":"投保書","D":"保險憑證"}'::jsonb, 'A', '保險單（或稱保單）是無形的保險合約的有形證據—一項最正式、最常用的證據。'),
('p2', 416, '二', '核保、投保文件與保單結構', '62. 已簽發的保險單：', '{"A":"會取代暫保單","B":"可結合其他附加文件(投保書)成為整體合約的一部份","C":"會被視為合約的証據","D":"以上所有各項"}'::jsonb, 'D', '保單是合約的證據，主要收納其他資料以及取代任何暫保單。'),
('p2', 417, '二', '核保、投保文件與保單結構', '63. 保險單是：', '{"A":"保險合約的可見證據","B":"保險的真正合約","C":"必定屬於簡式合約","D":"以上所有各項都符合"}'::jsonb, 'A', '保險單（或稱保單）是無形的保險合約的有形證據—一項最正式、最常用的證據。'),
('p2', 418, '二', '核保、投保文件與保單結構', '64. 在一般保險中一種屬於合約期內的永久性文件，經常用於證明強制保險的存在，這種文件是：', '{"A":"保險憑證","B":"保單","C":"暫保單","D":"投保書"}'::jsonb, 'A', '對有必要知道法例強制的汽車或遊艇保險是否存在的人（例如警方）而言，保險憑證是唯一法律認可的證明。'),
('p2', 419, '二', '核保、投保文件與保單結構', '65. 以下哪項保險會提供保險憑證？', '{"A":"船上貨物保險","B":"旅遊保險","C":"汽車保險","D":"以上各項皆是"}'::jsonb, 'D', '汽車、旅遊及海上貨物保險亦會發出保險憑證。'),
('p2', 420, '二', '核保、投保文件與保單結構', '66. 以下哪類保險不會預期以保險憑證發出？', '{"A":"火險","B":"汽車保險","C":"旅遊保險","D":"船上貨物保險(總保險單)"}'::jsonb, 'A', '汽車、旅遊及海上貨物保險亦會發出保險憑證。'),
('p2', 421, '二', '核保、投保文件與保單結構', '67. 在某種保險類別中, 如果保單被取消,必須取回保險憑證; 該類保險是:', '{"A":"公眾責任","B":"汽車","C":"旅遊","D":"海上貨物"}'::jsonb, 'B', '在汽車保險中，一旦保險被取消，保險人必須索回保險憑證，這足以顯示保險憑證在法律上的重要性。'),
('p2', 422, '二', '核保、投保文件與保單結構', '68. 只要被保人已經支付全年保費:', '{"A":"他不需負責另加保費","B":"若果保險人業務業績惡劣，他要支付額外保費","C":"任何情況都不會有退回保費","D":"他永不有機會退回全部保費"}'::jsonb, 'A', '支付全年保費後保單持有人將不用於同年度再繳付保費。'),
('p2', 423, '二', '核保、投保文件與保單結構', '69. 保險人在核保時，會區分屬於同一風險類別的個別風險的特質，從而對保費作出上下調整，這核保程序稱之為風險：', '{"A":"估定","B":"核保","C":"類別","D":"差別對待"}'::jsonb, 'D', '在保險核保中，「風險差別對待」已經使用了很久，並沒有任何邪惡的含義，只不過是指區分屬於同一風險類別的個別風險的特質（有好有壞），慿此來對同屬某個籠統風險類別的保費作上下的調整。'),
('p2', 424, '二', '核保、投保文件與保單結構', '70. 核保人提及的所謂風險差別對待是指：', '{"A":"對投保表現出偏好及不好","B":"選擇利益好的風險","C":"調整保費作為對不同危險的獎賞及懲罰","D":"拒絕對商業風險的危險投保"}'::jsonb, 'C', '在保險核保中，「風險差別對待」已經使用了很久，並沒有任何邪惡的含義，只不過是指區分屬於同一風險類別的個別風險的特質（有好有壞），慿此來對同屬某個籠統風險類別的保費作上下的調整。'),
('p2', 425, '二', '核保、投保文件與保單結構', '71. 風險差別對待是指：', '{"A":"分辨承保的風險","B":"確定保費的高低","C":"釐訂保險合約的條件","D":"以上所有各項"}'::jsonb, 'D', '在保險核保中，「風險差別對待」已經使用了很久，並沒有任何邪惡的含義，只不過是指區分屬於同一風險類別的個別風險的特質（有好有壞），慿此來對同屬某個籠統風險類別的保費作上下的調整。'),
('p2', 426, '二', '核保、投保文件與保單結構', '72. 根據一般保險保單條文', '{"A":"保費永遠毋須於保單生效前繳付","B":"保費必須於保單生效前繳付","C":"保費不是保單合約的主要元素","D":"保費可能須要按保單條款於合約生效前繳付"}'::jsonb, 'D', '實際做法視乎保單措詞而定，有些保單嚴格規定，保險保障的有效性以收到保費為先決條件；其他保單可能要求被保險人「已經支付或承諾支付」保費，而被保險人過去數年一直支付保費的行為可能構成了支付保費的現行承諾。'),
('p2', 427, '二', '核保、投保文件與保單結構', '73. 以下哪項關於一般保險的保費支付的重要性的說明是不正確的？', '{"A":"保費支付必須是在保險生效前","B":"即使保費尚未支付，保障也可能有效","C":"支付給保險代理人的保費也構成對保險人的法律責任","D":"有些保險條款使得保費支付成為合約生效前的先決條件"}'::jsonb, 'A', '實際做法視乎保單措詞而定，有些保單嚴格規定，保險保障的有效性以收到保費為先決條件；其他保單可能要求被保險人「已經支付或承諾支付」保費，而被保險人過去數年一直支付保費的行為可能構成了支付保費的現行承諾。'),
('p2', 428, '二', '核保、投保文件與保單結構', '74. 一般保險中，當保費繳交予中介人時：', '{"A":"在法律下是不正確的","B":"代理人可獲雙倍佣金","C":"還未算繳交，直至保費繳交至保險人","D":"在法律下相等於已繳費予保險人"}'::jsonb, 'D', '實際做法視乎保單措詞而定，有些保單嚴格規定，保險保障的有效性以收到保費為先決條件；其他保單可能要求被保險人「已經支付或承諾支付」保費，而被保險人過去數年一直支付保費的行為可能構成了支付保費的現行承諾。'),
('p2', 429, '二', '核保、投保文件與保單結構', '75. 保費通常在保單生效前繳付，但如保險人慣性設有信貸安排，即使保費仍未繳交，有關的合約仍可有效。這原則叫：', '{"A":"通融","B":"最高誠信","C":"不容反悔","D":"寬限期"}'::jsonb, 'C', '就支付保費的準時性而言，寬免這種作為是指保險人清晰地以陳述或行為方式表示，不堅持一項明確地要求在保險保障生效前支付保費的合約規定。因此，如果保險人曾經毫不猶疑地收取過遲交的保費，他可能會被當作已經為日後準時支付保費的要求作出寬免。如果被保險人想另外引用不容反悔原則，便須證明曾經倚賴保險人上述的陳述或行為。'),
('p2', 430, '二', '核保、投保文件與保單結構', '76. 對一般保險徵收附加費的機構或計劃包括香港汽車保險局及：', '{"A":"僱員補償保障計劃","B":"僱員補償條例","C":"僱員補償援助計劃","D":"僱員補償保險局"}'::jsonb, 'C', '僱員補償援助計劃屬徵收附加費的計劃。'),
('p2', 431, '二', '核保、投保文件與保單結構', '77. 於汽車保險中，為了保障無償債能力的汽車保險人，香港汽車保險局從汽車保單加設保費徵費。以下哪項描述是正確？', '{"A":"汽車保費之1%","B":"汽車保費之3%","C":"於1998已撤銷有關徵費","D":"有關的徵費會存放於沒有能力償債之保險人"}'::jsonb, 'B', '汽車保險局的經費來自針對保險人簽發的所有汽車保單收取的保費徵款，徵款額為汽車保費的3%。徵款不屬於保險人所有，必須轉交給汽車保險局。'),
('p2', 432, '二', '核保、投保文件與保單結構', '78. 汽車保險與僱員補償保險的保費都繳納徵費，它的目的是：', '{"A":"協助保險人應付龐大的索償額","B":"給被保險人提供額外的保障","C":"在有需要時執行強制保險的目的","D":"為香港特別行政區增加稅收"}'::jsonb, 'C', '在處理賠償時執行強制保險的目的，向事故受害者作出補償。'),
('p2', 433, '二', '核保、投保文件與保單結構', '79. 香港汽車保險局在汽車保單加設的保費徵費是為了保障：', '{"A":"汽車上的財產損毀","B":"汽車造成的財產損毀","C":"意外導致死亡或受傷的人","D":"被保險汽車的乘客"}'::jsonb, 'C', '該局承諾會在有不受保「法令」責任情況下介入，向交通意外事故受害者作出補償。'),
('p2', 434, '二', '核保、投保文件與保單結構', '80. 由汽車保險費附加徵收的款項，用以補償由於駕駛著沒有強制性保險或事後下落不明的車輛所引致第三者傷亡，對於此徵款，下列哪項的描述是正確的？', '{"A":"此徵收款項為汽車保費的百分之一","B":"為無恥的保險人所引致的受害人提供補償","C":"此徵款將於不久將來後取消","D":"以上各項皆正確"}'::jsonb, 'A', '汽車保險局的經費來自針對保險人簽發的所有汽車保單收取的保費徵款，徵款額為汽車保費的3%。徵款不屬於保險人所有，必須轉交給汽車保險局。'),
('p2', 435, '二', '核保、投保文件與保單結構', '81. 香港汽車保險局是在強制性汽車保險不存在時支持貫徹這類保險的原意。以下哪項是僱員補償保險與強制性汽車保險的目的相同？', '{"A":"香港保險業聯會","B":"僱主責任援助計劃","C":"僱員補償保險局","D":"僱員補償援助計劃"}'::jsonb, 'D', '僱員補償援助計劃屬與香港汽車保險局相似的機構。'),
('p2', 436, '二', '核保、投保文件與保單結構', '82. 就一般保險合約而言：', '{"A":"保費永遠無須於保險保障生效前支付","B":"保費必須於保險保障生效前支付","C":"保費的支付不屬於合約的必要元素","D":"保費有時須於保險保障前根據保單條文支付"}'::jsonb, 'D', '實際做法視乎保單措詞而定，有些保單嚴格規定，保險保障的有效性以收到保費為先決條件。'),
('p2', 437, '二', '核保、投保文件與保單結構', '83. 為了補償遇上相關的汽車保險人無償付能力而未能獲得賠償的某些汽車意外受害人而設的經費由何而來?', '{"A":"政府資助","B":"保險索償投訴局","C":"香港保險業聯會","D":"汽車保險局徵款而來的保費"}'::jsonb, 'D', '汽車保險局的經費來自針對保險人簽發的所有汽車保單收取的保費徵款，徵款額為汽車保費的3%。徵款不屬於保險人所有，必須轉交給汽車保險局。'),
('p2', 438, '二', '核保、投保文件與保單結構', '84. 以下哪項不是一般保險保單的描述?', '{"A":"它是無形的保險合約，是有形證據","B":"保險合約不存在，但有保障效力","C":"一般保險保單可取代暫保單","D":"另一名稱叫暫保單"}'::jsonb, 'D', '暫保單是一份暫時性的文件，它實際上構成一份暫時性保單。'),
('p2', 439, '二', '核保、投保文件與保單結構', '85. 以下那項或那些是對一般保險的投保單描述是正確的', '{"A":"它們對問題的回答永遠不是保證，只是陳述","B":"它們的資料對合約的基礎非常重要","C":"它們對問題的回答有充足的資料，保險人不需要再查詢其他問題","D":"以上所有各項"}'::jsonb, 'B', '對於相對次要的風險，投保書相當可能是唯一的實用查詢方法，而是否接受投保可能純粹根據投保書上的答案來決定。投保書中的答案，或從中所作出的推論，都可能顯示須作進一步的查詢。'),
('p2', 440, '二', '核保、投保文件與保單結構', '86. 以下哪項關於一般保險的保費的特點是不正確？', '{"A":"必須收到第一筆保費後，保險保障才會開始","B":"代表投保人對合約的代價","C":"保費可由保額釐定","D":"以上所有各項都不是"}'::jsonb, 'A', '人壽保險中有一個幾乎固定的做法，就是只在收到第一筆保費後，保險保障才會開始。在一般保險中不一定有同樣的規定。'),
('p2', 441, '二', '核保、投保文件與保單結構', '87. 一般保險的產品保險費率的基準，通常以百分比或千分比表示，乘下列某個因素而釐訂：', '{"A":"保額","B":"每年的銷售額","C":"每年的工資支出","D":"以上各項，視乎不同險種"}'::jsonb, 'D', '一般保險的產品種類繁多，因此唯一可以預期的，就是不同種類的保險，其保費的基準也不同。'),
('p2', 442, '二', '核保、投保文件與保單結構', '88. 「總保險單」是:', '{"A":"繳付一個總保險費的保單","B":"保單的正本","C":"旅遊代理人用以安排渡假「套餐」的保險單","D":"以全險作為根據"}'::jsonb, 'C', '保險憑證可以具有不同的作用。當應用於旅遊及海上貨物保險時，可在總保險單下作為保障範圍的摘要而發出。'),
('p2', 443, '二', '核保、投保文件與保單結構', '89. 一般保險的保費繳付要求：', '{"A":"在保單生效前","B":"在保單生效後","C":"有時需要在保單生效前","D":"保單生效後的30天內"}'::jsonb, 'C', '一般保險繳付保費是視乎該保單條文所述，沒有特定規定何時繳付保費方式的'),
('p2', 444, '二', '核保、投保文件與保單結構', '90. 政府設了一項財務安排，以涵蓋______保險業務所面對的恐怖主義活動風險', '{"A":"僱員補償","B":"汽車","C":"海上","D":"強制性"}'::jsonb, 'A', '政府為項目設立了一項 100億元的財務安排'),
('p2', 445, '二', '核保、投保文件與保單結構', '91. 政府設了一項財務安排，以涵蓋______保險業務所面對的恐怖主義活動風險', '{"A":"僱員補償","B":"汽車保險","C":"人壽保險","D":"人身意外保險"}'::jsonb, 'A', '政府為項目設立了一項 100億元的財務安排'),
('p2', 446, '二', '核保、投保文件與保單結構', '92. 報價單可以為____構成合約元素之一', '{"A":"投保書","B":"要約","C":"要約的邀請","D":"單據"}'::jsonb, 'B', '報價可能被視為可供承約的要約行為，而不是最終決定。'),
('p2', 447, '二', '核保、投保文件與保單結構', '93. 於普通法角度，一般保險受保一刻是否必須是已繳交保費?', '{"A":"對，否則不能受保","B":"視乎公司而定","C":"保險中介人可決定","D":"支付保費不是先決條件"}'::jsonb, 'D', '普通法的角度：除非合約條款有明確的、相反的規定，否則支付保費不是先決條件，因此，即使還沒付保費，保險合約仍然可以有效。'),
('p2', 448, '二', '核保、投保文件與保單結構', '94. 僱員補償援助計劃的徵費來源是來自?', '{"A":"僱員補償保險","B":"僱員補償保險人供款","C":"僱主","D":"僱員"}'::jsonb, 'A', '僱員補償援助計劃的徵費來源是來自僱員補償保險'),
('p2', 449, '二', '核保、投保文件與保單結構', '95. 保險業監管局收取的保費徵費為:', '{"A":"0.0004","B":"0.001","C":"0.01","D":"0.03"}'::jsonb, 'B', '首階段的徵費率為每保單年度保費的0.04%，其後逐步調整至2021年4月份（即第四亦是最後階段的起點）的0.1%。每張保單的徵費金額設有上限。'),
('p2', 450, '二', '核保、投保文件與保單結構', '96. 以下哪個機構的營運不涉及保險徵款?', '{"A":"保險公司（僱員補償）無力償債管理局","B":"香港專業保險經紀協會","C":"香港汽車保險局","D":"以上各機構均涉及保險徵款"}'::jsonb, 'B', '香港專業保險經紀協會為保險經紀爭取利益的團體，不涉及保險徵款'),
('p2', 451, '二', '核保、投保文件與保單結構', '97. 僱員補償援助計劃的徵費是:', '{"A":"0.01","B":"0.05","C":"0.058","D":"0.02"}'::jsonb, 'C', '僱員補償援助計劃的保費徵收為5.8%'),
('p2', 452, '二', '核保、投保文件與保單結構', '98. 在一般保險中，一份典型之「承保表」包括', '{"A":"保單編號","B":"被保人之姓名","C":"標的物之描述","D":"以上所有各項"}'::jsonb, 'D', '承保表包含了:保單編號、被保險人的詳細資料、保單限額、有效期、保險標的的描述、保費、保險中介人的身份、任何適用的特別條款、該合約適用的任何額外利益及任何保險批單。'),
('p2', 453, '二', '核保、投保文件與保單結構', '99. 保單是：', '{"A":"條款不能隨意更改","B":"有關合約的書面證據","C":"必須有蓋印方能生效","D":"一份簡式合約的必要憑證"}'::jsonb, 'B', '保單是有關保險合約的書面證據，因此了解香港保單一般採用的形式是非常重要的。'),
('p2', 454, '二', '核保、投保文件與保單結構', '100. 在普通法中一般保險保單措詞：', '{"A":"是不受規管的","B":"受政府規管及規定","C":"人身意外保單才受規管","D":"強制保單才受規管"}'::jsonb, 'A', '在香港，保單措詞不受規管，保險人因此可以自由地設計和出售自己的產品。'),
('p2', 455, '二', '核保、投保文件與保單結構', '101. 「淺白英語」保單通常適用於那類保單？', '{"A":"個人保險保單","B":"責任保險保單","C":"商業保險保單","D":"強制性保險保單"}'::jsonb, 'A', '為了顯得更為「用家方便」，保單文件都用第一或第二身寫成，而非不帶個人感情的第三身。因此它採用「我們」和「你們」，而不是「本公司」和「該被保險人」等字眼。保單相當可能製成體積細小的小冊子，有時還會加進插圖及卡通畫。這種形式的保單多數用於個人險種，而非商業風險。'),
('p2', 456, '二', '核保、投保文件與保單結構', '102. 在保險條款中, 「淺白英語」的新表達方式,那個描述是正確?', '{"A":"它們的原意是為了「用家方便」","B":"傾向於利用「我們」或「你們」的表達方式","C":"多數用於「個人險種」而非商用險種","D":"以上各項皆是"}'::jsonb, 'D', '為了顯得更為「用家方便」，保單文件都用第一或第二身寫成，而非不帶個人感情的第三身。因此它採用「我們」和「你們」，而不是「本公司」和「該被保險人」等字眼。保單相當可能製成體積細小的小冊子，有時還會加進插圖及卡通畫。這種形式的保單多數用於個人險種，而非商業風險。'),
('p2', 457, '二', '核保、投保文件與保單結構', '103. 保單中使用「淺白英語」是因為：', '{"A":"用家方便","B":"配合法律文件中正式的傳統用語","C":"方便以第三身去表達保單中的內文","D":"只適用於商業保險，而非個人險種"}'::jsonb, 'A', '為了顯得更為「用家方便」，保單文件都用第一或第二身寫成，而非不帶個人感情的第三身。'),
('p2', 458, '二', '核保、投保文件與保單結構', '104. 只提供給個人而不提供給商業組織的一般保險業務類別，稱為？', '{"A":"個人險種保險","B":"私人保險","C":"非公司保險","D":"私人保單持有人保險保障"}'::jsonb, 'A', '個人險種保險屬個人一般保險類別。'),
('p2', 459, '二', '核保、投保文件與保單結構', '105. 以下哪項不會包含於承保表中？', '{"A":"被保人的姓名、地址及年齡","B":"仲裁條款","C":"保額","D":"標的物的描述"}'::jsonb, 'B', '承保表包含了:保單編號、被保險人的詳細資料、保單限額、有效期、保險標的的描述、保費、保險中介人的身份、任何適用的特別條款、該合約適用的任何額外利益及任何保險批單。'),
('p2', 460, '二', '核保、投保文件與保單結構', '106. 保單中會包括被保人的姓名、地址、職業及年齡等資料的部份稱為', '{"A":"承保表","B":"敘文條款","C":"履行條款","D":"保單條件"}'::jsonb, 'A', '承保表包含了:保單編號、被保險人的詳細資料、保單限額、有效期、保險標的的描述、保費、保險中介人的身份、任何適用的特別條款、該合約適用的任何額外利益及任何保險批單。'),
('p2', 461, '二', '核保、投保文件與保單結構', '107. 承保表式的保單格式的敘文條款，較可能包含：', '{"A":"被保險人的姓名及地址","B":"被保險標的物的完整描述","C":"對投保書及聲明的參照","D":"以上各項皆是"}'::jsonb, 'C', '敘文條款這個名稱不會出現在保單文件中，但是它實際上是個介紹有關合約的引子。它會提及合約方，還會提述投保書及聲明 ，視它們為合約的一部分，及合約的基礎。'),
('p2', 462, '二', '核保、投保文件與保單結構', '108. 在一般保險保單中，履行條款說明了怎樣可以得到保障的情況，這條款又稱為：', '{"A":"見證條款","B":"敘文條款","C":"保單條件","D":"承保條款"}'::jsonb, 'D', '履行條款表明在什麽情況下承保的承諾將得以履行（因此，有時也被稱為承保條款）。'),
('p2', 463, '二', '核保、投保文件與保單結構', '109. 在「承保表式」保單中，概述在甚麼情況下可以作出有效的索償的部份(有時會包括它本身的除外責任)稱為：', '{"A":"常用保單除外責任","B":"保單附表","C":"敘文條款","D":"履行條款"}'::jsonb, 'D', '履行條款它指明了受保的危險或指出保障範圍屬於「全險」。'),
('p2', 464, '二', '核保、投保文件與保單結構', '110. 承保表式保單中的一般不受保項目是指：', '{"A":"適用於整份合約的不保項目","B":"又名除外責任","C":"附帶條件","D":"以上各項皆是"}'::jsonb, 'D', '履行條款中的不同部分可以有本身的通用除外責任，適用於各種索償或保險金要求。「通用除外責任」這個標題在保單中明確可見，不過還可以另外使用「除外責任」或（較少用的）「附帶條件」等兩個名稱。'),
('p2', 465, '二', '核保、投保文件與保單結構', '111. 保單內之「通用除外責任項目」是：', '{"A":"適用於某個部份的有關保障","B":"適用於整份保險合約","C":"只適用於敘文條款的保障","D":"只適用於限制履行條款的保障"}'::jsonb, 'B', '通用除外責任意思是指此類除外責任適用於整個合約（即保單的每個部分）。'),
('p2', 466, '二', '核保、投保文件與保單結構', '112. 保單中的哪個部份會拒絕承認保單中每個部份的保障', '{"A":"履行條款","B":"敘文條款","C":"承保表","D":"通用除外責任項目"}'::jsonb, 'D', '通用除外責任意思是指此類除外責任適用於整個合約（即保單的每個部分）。'),
('p2', 467, '二', '核保、投保文件與保單結構', '113. 在一般保險單中，保單條件：', '{"A":"可以是明訂，也可以是隱含的","B":"總是出現於保單中","C":"總是隱含的（不會出現於保單中）","D":"於保險的保單中所有保險公司的都是一樣"}'::jsonb, 'A', '所有保險合約都設有一些除外責任；即使上述類型的除外責任沒有在保單文件中出現，但總會存在着某些由法律隱含的附帶條件。'),
('p2', 468, '二', '核保、投保文件與保單結構', '114. 以下哪項是對保單的正確說明？', '{"A":"隱含條款及明訂條款均不適用","B":"隱含條款是適用的，但不會於保單中列出","C":"明訂條款比隱含條款更為重要","D":"隱含條款及明訂條款會於保單中列出"}'::jsonb, 'B', '所有保險合約都設有一些除外責任；即使上述類型的除外責任沒有在保單文件中出現，但總會存在着某些由法律隱含的附帶條件。'),
('p2', 469, '二', '核保、投保文件與保單結構', '115. 適用於保單內各個部份的保單限制, 較可能出現於:', '{"A":"通用除外責任項目","B":"敘文條款","C":"保單附表","D":"見證條款"}'::jsonb, 'A', '通用除外責任項目是保單限制中其中一個元素。'),
('p2', 470, '二', '核保、投保文件與保單結構', '116. 以下哪項是形容保單除外責任？', '{"A":"總是在保單每個項目中出現","B":"總是在保單其中一個項目中出現","C":"不會出現在保單中","D":"以上各項皆不正確"}'::jsonb, 'D', '除外責任可以適用於整個合約（「通用除外責任」），或僅從個別保單部分剔除 部 分 保 險 保 障 （「 部 分 的 除 外責 任 」）。'),
('p2', 471, '二', '核保、投保文件與保單結構', '117. 以下哪項或哪些保單條款，會出現於一般保險的保單中？', '{"A":"仲裁","B":"取消","C":"索償條款","D":"以上所列各項"}'::jsonb, 'D', '索償或保險金要求、仲裁、取消、比例分攤、保單修改法律狀況及可調整的保費都均為保單條款元素。'),
('p2', 472, '二', '核保、投保文件與保單結構', '118. 以下哪項不是一般保險單的條件', '{"A":"仲裁條款","B":"取消條款","C":"需要可保權益","D":"索償條款"}'::jsonb, 'C', '索償或保險金要求、仲裁、取消、比例分攤、保單修改法律狀況及可調整的保費都均為保單條款元素。'),
('p2', 473, '二', '核保、投保文件與保單結構', '119. 最高誠信及可保權益這兩個保險原則是屬於哪種保單條款？', '{"A":"履行條款","B":"敘文條款","C":"隱含條款","D":"明訂條款"}'::jsonb, 'C', '最高誠信及可保權益為隱含條款，被保人於投保時須遵守有關保險原則而保單中可能沒有列明之保險原則。'),
('p2', 474, '二', '核保、投保文件與保單結構', '120. 以下哪項或哪些保單條件，相當可能出現於香港簽發的一般保險保單中？', '{"A":"仲裁","B":"取消","C":"索償條款","D":"上述所有各項"}'::jsonb, 'D', '索償或保險金要求、仲裁、取消、比例分攤、保單修改法律狀況及可調整的保費都均為保單條款元素。'),
('p2', 475, '二', '核保、投保文件與保單結構', '121. 以下那項/保單條件常見於一般保險保單:', '{"A":"仲裁","B":"取消","C":"索償金額","D":"以上各項皆是"}'::jsonb, 'D', '保單條件或條件包括:索償或保險金要求、仲裁、取消、比例分攤、保單修改法律狀況及可調整保費。'),
('p2', 476, '二', '核保、投保文件與保單結構', '122. 下列哪項是香港保單上常見的條件？', '{"A":"最高誠信","B":"仲裁","C":"保單除外責任","D":"可保權益"}'::jsonb, 'B', '索償或保險金要求、仲裁、取消、比例分攤、保單修改法律狀況及可調整的保費都均為保單條款元素。'),
('p2', 477, '二', '核保、投保文件與保單結構', '123. 購買不足額的保險會引致應用比例分攤的原則，即：', '{"A":"賠償已邀交的保費","B":"賠償保額","C":"按損失比例減低賠償","D":"兩份保單同時作出賠償"}'::jsonb, 'C', '比例分攤是對損失發生時保額不足的情況加以懲罰。'),
('p2', 478, '二', '核保、投保文件與保單結構', '124. 以下哪項是一般保險中自負額的不正確陳述？', '{"A":"標準自負額適用於所有同一種類保單","B":"附加自負額是由承保人額外規定的","C":"自願性自負額由被保險人主動提出的","D":"所有各類型保單均可由被保險人主動提出自負額藉以減低保費"}'::jsonb, 'D', '自願性自負額是被保險人自己選擇的，藉此取得扣減保費的優惠，但不是所有各類型保單均可由被保險人主動提出。'),
('p2', 479, '二', '核保、投保文件與保單結構', '125. 自負額通常包括以下哪項？
i. 標準的自負額
ii. 施加的自負額
iii. 核保的自負額
iv. 自願的自負額', '{"A":"i, ii , iii","B":"i, ii , iv","C":"ii, iii , iv","D":"i, ii, iii , iv"}'::jsonb, 'B', '自負額分為標準、施加及自願的三種。'),
('p2', 480, '二', '核保、投保文件與保單結構', '126. 以下哪項描述對標準的自負額是正確的？', '{"A":"是保險公司額外實施的，藉此抗衡不利的特點","B":"是被保險人取得保費扣減的手法","C":"適用於所有同類保單(例如「年輕司機」自負額)","D":"以上所有各項"}'::jsonb, 'C', '標準自負額適用於所有同類的保單（例如汽車保單中的「年輕司機自負額」）。'),
('p2', 481, '二', '核保、投保文件與保單結構', '127. 汽車保險中保險人會對一些特定風險，要求作出自負額名為：', '{"A":"附加自負額","B":"標準自負額","C":"自願性自負額","D":"歧視性自負額"}'::jsonb, 'B', '標準自負額適用於所有同類的保單（例如汽車保單中的「年輕司機自負額」）。'),
('p2', 482, '二', '核保、投保文件與保單結構', '128. 大部份的汽車保險單中，都設有「年輕駕駛人仕」的自負額。這種自負額稱為：', '{"A":"普遍自負額","B":"標準自負額","C":"自願自負額","D":"個人核保自負額"}'::jsonb, 'B', '標準自負額適用於所有同類的保單（例如汽車保單中的「年輕司機自負額」）。'),
('p2', 483, '二', '核保、投保文件與保單結構', '129. 以下哪項自負額是承保人為抗衡不利特點而額外實施，而且投保人不會得到保費扣減？', '{"A":"標準自負額","B":"附加自負額","C":"自願自負額","D":"核保自負額"}'::jsonb, 'B', '施加的自負額由核保人額外規定的（保費不獲扣減），藉以抵消擬保風險的某些不利因素（例如某張「全險」保單已錄得了幾項小額索償）。'),
('p2', 484, '二', '核保、投保文件與保單結構', '130. 在汽車保險中，以下哪項自負額可得到保費的扣減？', '{"A":"標準自負額","B":"自願性自負額","C":"由保險公司所訂定的自負額","D":"以上所有各項"}'::jsonb, 'B', '自願的自負額是被保險人自己選擇的，藉此取得扣減保費的優惠。'),
('p2', 485, '二', '核保、投保文件與保單結構', '131. 如果一份保險保單受到免賠額約束，它的意思是指：', '{"A":"低於免賠額的索償不會獲賠償","B":"保險人就有關保費提供折扣","C":"如果不足額保險出現的話，索償的付款便會減少","D":"以上所有各項"}'::jsonb, 'A', '起賠額的功能是排除小額索償，而只就達到或超逾該起賠額的損失作出足額賠償。'),
('p2', 486, '二', '核保、投保文件與保單結構', '132. 以下哪項對於免賠額的描述是正確的？', '{"A":"免賠額與起賠額的意義相同","B":"任何低於免賠額的索償都得不到賠償","C":"任何高於免賠額的索償都可全數獲得賠償","D":"以上所有各項"}'::jsonb, 'B', '起賠額的功能是排除小額索償，而只就達到或超逾該起賠額的損失作出足額賠償。'),
('p2', 487, '二', '核保、投保文件與保單結構', '133. 起賠額的意思是：', '{"A":"任何高於起賠額的索償可獲全數賠償","B":"任何低於起賠額的索償都得不到賠償","C":"希望消除小額索償","D":"以上所有各項"}'::jsonb, 'D', '起賠額的功能是排除小額索償，而只就達到或超逾該起賠額的損失作出足額賠償。'),
('p2', 488, '二', '核保、投保文件與保單結構', '134. 如果一份保單的起賠額是五百元正，對於五百元的索償，保險人需給付多少錢？', '{"A":"三百元","B":"四百元","C":"五百元","D":"保險人無需付給此索償"}'::jsonb, 'C', '起賠額的功能是排除小額索償，而只就達到或超逾該起賠額的損失作出足額賠償。500元已到起賠額之金額，並由保險人負責。'),
('p2', 489, '二', '核保、投保文件與保單結構', '135. 以下哪項除外責任屬於保單的條款?', '{"A":"一般除外責任","B":"特定除外責任","C":"業界除外責任","D":"以上所有各項"}'::jsonb, 'D', '除外責任分為通用、特定及業界除外責任。'),
('p2', 490, '二', '核保、投保文件與保單結構', '136. 以下哪項屬於對保證的正確描述？', '{"A":"違反保證可令致保單由生效日期開始時當作無效","B":"保證可分為明示，隱含及中性","C":"正常情況下，保證以明示方式出現於保單條件中","D":"違反保證必然與損失之間存在著因果關係"}'::jsonb, 'C', '在典型的一般保險投保書上的聲明中的保證，承諾投保書上的回答都是完整及真實的。'),
('p2', 491, '二', '核保、投保文件與保單結構', '137. 以下哪項描述是指被保險人作出一項絕對承諾，而涉及的承諾可以是作出或避免作出一些行為？', '{"A":"保證","B":"免賠額","C":"背書","D":"明示條件"}'::jsonb, 'A', '「保證」可以被視為一項被保險人對保險人所作出的、必須確實遵守的承諾。'),
('p2', 492, '二', '核保、投保文件與保單結構', '138. 優良保險慣例的一般原則建議不應因違反保證而拒絕索償，除非：', '{"A":"索償額巨大","B":"涉及強制性的保險索償","C":"違反保証與索償有重要的因果關係","D":"這並非被保險人在該單的第一次索償"}'::jsonb, 'C', '為了減輕保證的嚴酷程度，由香港保險業聯會發出以供會員遵守的《承保商專業守則》，規定保險人只可於違反保證和損失之間存在着因果關係，或違反屬欺詐行為的情況下，利用該違反作為拒賠的理由。'),
('p2', 493, '二', '核保、投保文件與保單結構', '139. 若被保人違反投保書內所提出的保証，保險人是會按一般守則要求一種關係才會拒絕賠償，這程「關係」是指：', '{"A":"該項違反是與導致的損失有著重大的關係","B":"該項違反是與導致的損失毋須有任何的關係","C":"被保險人與該項保証的關係","D":"保險人與該項保証的關係"}'::jsonb, 'A', '《承保商專業守則》規定保險人只可於違反保證和損失之間存在着因果關係，或違反屬欺詐行為的情況下，利用該違反作為拒賠的理由。'),
('p2', 494, '二', '核保、投保文件與保單結構', '140. 以下哪項有關保險保證的說明是正確的?
i. 若然違反保證，保險人便可拒絕承諾有關合約
ii. 保險人在拒絕索償前會要求的一種關係
iii. 保險人可要求被保險人採取一些行動(設置警鍾)保險人可要求被保險人避免一些行動(拆御有關設施)', '{"A":"i , ii","B":"iii, iv","C":"i, ii, iii","D":"i, ii, iii, iv"}'::jsonb, 'D', '以上四項均為保證的說明，並以假設的方式說明其中兩個保證的元素:有所為、有所不為。同時《承保商專業守則》規定保險人只可於違反保證和損失之間存在着因果關係，或違反屬欺詐行為的情況下，利用該違反作為拒賠的理由。'),
('p2', 495, '二', '核保、投保文件與保單結構', '141. 當一位公正的保險人利用違反保證事項為由來拒絕一個可能有效的索償前，他會考慮所違反之事項是否與那項索償情況有任何「關係」。此「關係」意思是指', '{"A":"所違反保證事項屬於蓄意造成","B":"有牽涉欺詐成份","C":"該項違反保證對那項索償情況有著重大意義","D":"那違反保證事項已曾經發生過"}'::jsonb, 'C', '《承保商專業守則》規定保險人只可於違反保證和損失之間存在着因果關係，或違反屬欺詐行為的情況下，利用該違反作為拒賠的理由。'),
('p2', 496, '二', '核保、投保文件與保單結構', '142. 根據「承保商專業守則」規定，違反保證和損失之間必須存在著「因果關係」時，又或者該違反屬於以下那種情況下，才可作為拒賠的理由？', '{"A":"屬於故意的情況下","B":"屬於欺詐的情況下","C":"屬於不知情的情況下","D":"屬於在一般情況下故意或無意的情況下"}'::jsonb, 'B', '《承保商專業守則》規定保險人只可於違反保證和損失之間存在着因果關係，或違反屬欺詐行為的情況下，利用該違反作為拒賠的理由。'),
('p2', 497, '二', '核保、投保文件與保單結構', '143. 某製品公司，買了一份火災保障包括建築物及物件。後經過一場火災的重大損毀，保險人委派理賠師在火災肇事地點的某露天處發現一些受損的殘損物件，理賠師對製品公司提出該保障有一保證不把存貨放在露天處的條款，這保證對該事件有什麼關係？', '{"A":"視乎是否蓄意違反該保證。香港法律容許屬非惡意違反的保證","B":"視乎保險人有否在損失發生前引起被保險人對違反的注意，如沒有保險人不可應用該保證","C":"如該違反沒有做成任何損失，按照優良保險慣例，有關保險人不得以違反保證而不承擔責任","D":"視乎建築物有否損毀，因該保證是保證物件的"}'::jsonb, 'C', '保險人承諾根據該會發出的《承保商專業守則》，如要拒絕賠償或支付保險金，必會給予充分的解釋。'),
('p2', 498, '二', '核保、投保文件與保單結構', '144. 以下哪項對於保單中的條件的描述是正確的？
i. 在其他法律分科中，是屬於一種基本條款合約生效前的先決條件，是合約開始前必須滿足的條件
iii. 違反合約生效後的先決條件，是會令合約變為無效
iv. 違反責任出現前的先決條件，是會使索償變為無效', '{"A":"i, ii , iii","B":"i, ii , iv","C":"ii, iii , iv","D":"i, ii, iii , iv"}'::jsonb, 'D', '在合約法中，一個合約的條件屬於該合約的基本條款，其基本的程度足以在違反之後，讓受屈一方有權把合約當作已廢除，並同時尋求某些其他補救。(i) 合約生效前的先決條件:合約生效之前必須履行的條款，例如失實陳述條件。(ii) 合約生效後的條件:例如在人身意外保險中，保費主要是根據受保人的職業釐定的，因此受保人如果在保單有效期內轉換職業，便須按照明示的要求通知保險人，並且取得保險人的同意。(iii) 責任出現前的先決條件:違反這類條款不會毀了整個合約，但會使某索償或保險金要求變成無效。一個明文和清晰地述明違反將會令被保險人喪失權利的通知條件。'),
('p2', 499, '二', '核保、投保文件與保單結構', '145. 保險單中的失述陳述條件屬於：', '{"A":"陳述","B":"合約生效前的條件","C":"合約生效後的條件","D":"責任出現前的先決條件"}'::jsonb, 'B', '合約生效前的先決條件:合約生效之前必須履行的條款，例如失實陳述條件。'),
('p2', 500, '二', '核保、投保文件與保單結構', '146. 香港所簽發的火險保單包含了一項失實陳述條件的條款，這條屬於：', '{"A":"保證","B":"責任出現前的先決條件","C":"合約生效前的先決條件","D":"合約生效後的先決條件"}'::jsonb, 'C', '合約生效前的先決條件:合約生效之前必須履行的條款，例如失實陳述條件。'),
('p2', 501, '二', '核保、投保文件與保單結構', '147. 在個人意外保單中，通常會指明被保人在轉職後要作出通知，若違反這些條件，保單便變為無效。這種情況下的條件便屬於：', '{"A":"隱含條款","B":"合約生效前的先決條件","C":"合約生效後的條件","D":"責任出現前的先決條件"}'::jsonb, 'C', '合約生效後的條件:例如在人身意外保險中，保費主要是根據受保人的職業釐定的，因此受保人如果在保單有效期內轉換職業，便須按照明示的要求通知保險人，並且取得保險人的同意。'),
('p2', 502, '二', '核保、投保文件與保單結構', '148. 在某種情況下，保單持有人因為延誤提出索償，而令致保險公司提出拒絕是次賠償，但該保單依然維持生效。這種情況引用了以下哪項條件？', '{"A":"避免某些條件及追償條款","B":"合約生效後的先決條件","C":"責任出現前的先決條件","D":"合約生效前的先決條件"}'::jsonb, 'C', '責任出現前的先決條件:違反這類條款不會毀了整個合約，但會使某索償或保險金要求變成無效。一個明文和清晰地述明違反將會令被保險人喪失權利的通知條件。'),
('p2', 503, '二', '核保、投保文件與保單結構', '149. 違反以下哪項條件會令到有關的索償無效，但保單依然有效？', '{"A":"合約生效前的先決條件","B":"合約生效後的先決條件","C":"責任出現前的先決條件","D":"以上所有各項"}'::jsonb, 'C', '責任出現前的先決條件:違反這類條款不會毀了整個合約，但會使某索償或保險金要求變成無效。一個明文和清晰地述明違反將會令被保險人喪失權利的通知條件。'),
('p2', 504, '二', '核保、投保文件與保單結構', '150. 大部份一般保險單索償條件，均要求儘快通知有關的索償，不符合要求會引致有關索償無效，但保單繼續有效，這個索償條件稱為：', '{"A":"隱含的條件","B":"責任出現前的先決條件","C":"合約發生前的先決條件","D":"合約發生後的條件"}'::jsonb, 'B', '責任出現前的先決條件:違反這類條款不會毀了整個合約，但會使某索償或保險金要求變成無效。一個明文和清晰地述明違反將會令被保險人喪失權利的通知條件。'),
('p2', 505, '二', '核保、投保文件與保單結構', '151. 以下哪項對於投保書中的陳述是不正確的？', '{"A":"投保書中的陳述可以是口頭的","B":"重要的陳述只需要是實質上真實的","C":"有關陳述必須出現於保單用詞中","D":"以上所有各項"}'::jsonb, 'C', '陳述可以是口頭的，也可以是書面的。'),
('p2', 506, '二', '核保、投保文件與保單結構', '152. 在保單條款內的除外責任有三種，以下那項的陳述是正確的？', '{"A":"通用除外責任是適用於某類別的所有保單的除外責任","B":"特定除外責任是承保人按個別風險所設定的除外責任","C":"業界除外責任是市場中所有保險人共同設定的除外責任","D":"以上所有各項"}'::jsonb, 'D', '通用除外責任定義為那些適用於某類險種的所有保單的除外責任。特定除外責任是由核保人基於特定風險的額外危險，決定在相關保單中加入的除外責任。業界除外責任屬於通用除外責任的另一種形式，它們很多時候與基本風險有關，而且在某些地區，是與當地政府磋商並徵得其同意後產生的。'),
('p2', 507, '二', '核保、投保文件與保單結構', '153. 以下哪項是汽車保險中標準的除外責任？', '{"A":"賽車","B":"速度測試","C":"戰爭風險","D":"以上所有各項"}'::jsonb, 'D', '私家車保險：意圖承保的是為商業或遊樂目的的正常使用，所以用於賽車、速度測試及汽車行業的使用就屬於標準的除外責任。'),
('p2', 508, '二', '核保、投保文件與保單結構', '154. 在一般保險中，業界的除外責任包括有:', '{"A":"核子風險","B":"輻射風險","C":"戰爭風險","D":"以上所有各項"}'::jsonb, 'D', '業界除外責任包括核及輻射風險、恐怖主義、音爆損害及戰爭風險。'),
('p2', 509, '二', '核保、投保文件與保單結構', '155. 以下哪項對於公眾利益的概念是正確的？', '{"A":"屬於非書面條件","B":"違反公眾利益的保單會得不到保障","C":"違反公眾利益的索償是無效的","D":"以上所有各項"}'::jsonb, 'D', '法院不容許作某些事情，理由是它們有違公共政策。在保險方面而言，這意味着在某些情況下，應該撇開特定保險的合約方的共同意圖而不為他們執行該合約或當中某些條文。'),
('p2', 510, '二', '核保、投保文件與保單結構', '156. 有關可調整保費的保單條件：', '{"A":"嚴格地說，在法律上不可強制執行","B":"要求被保險人保留足夠的相關記錄","C":"通常與財產保險的保費有關","D":"與汽車保險的無索償折扣制度有關"}'::jsonb, 'B', '如果保費因基於一些可變動的因素來計算而屬臨時性質，便需有項保單條件要求被保險人保留足夠的記錄，以便計算精確的保費，作為於保單期滿時調整保費之用。'),
('p2', 511, '二', '核保、投保文件與保單結構', '157. 於僱員補償條例中，除非殘疾維持了至少3天以上，否則便沒有得到殘疾利益，這是指保單條件包含了:', '{"A":"自負額","B":"保單保證","C":"免賠額","D":"保單時間起賠額"}'::jsonb, 'D', '有些一般保險對殘疾或喪失能力提供利益，但這種殘障或喪失能力的情形必須至少持續了某段期限之後，保險人才會給付利益，而一旦滿足了這項條件，整段喪失能力期間均獲給付保險利益。'),
('p2', 512, '二', '核保、投保文件與保單結構', '158. （承保表式）保單中提及合約各方（但不提名字），介紹投保書和聲明，提及有關保費（但不是金額）的部分可稱為:', '{"A":"保單承保表","B":"敘文條款","C":"履行條款","D":"見證條款"}'::jsonb, 'B', '敘文條款不會出現在保單文件中，但是它實際上是個介紹有關合約的引子。它會提及合約方（但名字則不提，可在承保表中找到），還會提述投保書及聲明，視它們為合約的一部分，及合約的基礎。保費的支付（而非金額）可能也會提及。'),
('p2', 513, '二', '核保、投保文件與保單結構', '159. 如果承保人在保單上加上特殊條款(例如：一個承保自負額)，哪部份會對此有所提及?', '{"A":"敘文條款","B":"履行條款","C":"保單條件","D":"通用除外責任"}'::jsonb, 'B', '履行條款或承保表中列出適用於該部份的任何自負額/免賠額。'),
('p2', 514, '二', '核保、投保文件與保單結構', '160. 在保險條款以「用家方便」表達並非正式，一般採用「我們」、「你們」的第一或第二身寫成，以下那個描述是正確表達方式?', '{"A":"時尚英語","B":"淺白英語","C":"較易明白英語","D":"現代英語"}'::jsonb, 'B', '淺白英語的使用，是近代努力避免採用法律文件的正式傳統用詞的成果。為了顯得更為「用家方便」，保單文件都用第一或第二身寫成，而非不帶個人感情的第三身。因此它採用「我們」和「你們」，而不是「本公司」和「該被保險人」等字眼。'),
('p2', 515, '二', '核保、投保文件與保單結構', '161. 公共政策的法律概念是指:', '{"A":"保單承保一個普通市民並非一間公司","B":"政府保險引起不同法律因素","C":"一份合約是不應違返公眾良知的合約","D":"即使法律責任不存在, 保單必須強制執行"}'::jsonb, 'C', '法院不容許作某些事情，理由是它們有違公共政策。在保險方面而言，這意味着社會（透過法官的判決）傳達了一個訊息，表明在某些情況下，應該撇開特定保險的合約方的共同意圖而不為他們執行該合約或當中某些條文。'),
('p2', 516, '二', '核保、投保文件與保單結構', '162. 一般保險的保單的某部分包含了所有只與該個合約有關的資料，該部分被稱為：', '{"A":"承保表","B":"敘文條款","C":"履行條款","D":"通用除外責任"}'::jsonb, 'A', '承保表或保單承保表是保單的一部分，它包含了只與受保風險有關的全部資料。'),
('p2', 517, '二', '核保、投保文件與保單結構', '163. 以下哪項是「陳述」的最佳描述?', '{"A":"必須是口頭提供資料","B":"和「保證」的意思相同","C":"正式提交經蓋印的說明解釋","D":"對投保風險作出的事實陳述"}'::jsonb, 'D', '陳述是合約一方對另一方就擬保風險作出的、關於事實的或所信的陳述。它可以是口頭的，也可以是書面的。'),
('p2', 518, '二', '核保、投保文件與保單結構', '164. 「時間性起賠」是指:', '{"A":"必須於指定限期內繳付保費","B":"保險人必須於指定時間內理賠","C":"於保單生效後指定限期內才可索償","D":"喪失能力的時間必須跨越指定期限，才可獲得賠償"}'::jsonb, 'D', '有些一般保險對殘疾或喪失能力提供利益，但這種殘障或喪失能力的情形必須至少持續了某段期限之後，保險人才會給付利益，而一旦滿足了這項條件整段喪失能力'),
('p2', 519, '二', '核保、投保文件與保單結構', '165. 以下哪項資料是不會包括於承保表當中？', '{"A":"總保費","B":"合約各方的名稱","C":"保單的責任範圍","D":"以上所有各項"}'::jsonb, 'B', '合約各方的名稱是於敘文條款中'),
('p2', 520, '二', '核保、投保文件與保單結構', '166. 在續保時，如果受保處所沒有配備警鐘裝置，並經常出現索償，在家居保險豁免承保盜竊引致的損失，這是屬於:', '{"A":"不保危險","B":"特定除外責任","C":"保單條件","D":"通用除外責任"}'::jsonb, 'B', '這些是由核保人基於特定風險的額外危險，決定在相關保單加入的除外責任，個別情況各不相同。'),
('p2', 521, '二', '核保、投保文件與保單結構', '167. 闡明認可產品(包括基本計劃和靈活計劃)在保單結構、條款及保障的最低要求是以下哪份文件?', '{"A":"自願醫保計劃下保險公司的註冊規則","B":"自願醫保計劃認可產品保單範本","C":"自願醫保計劃下產品的合規規則","D":"自願醫保計劃銷售規則"}'::jsonb, 'B', '自願醫保計劃認可產品保單範本是闡明產品的最低要永，簡稱保單範本'),
('p2', 522, '二', '核保、投保文件與保單結構', '168. 在續保時，如果受保處所沒有配備警鐘裝置，並經常出現索償，在家居保險豁免承保盜竊引致的損失，這是屬於_______的類別', '{"A":"不保危險","B":"保證","C":"通用除外責任","D":"特定除外責任"}'::jsonb, 'B', '保證可以被視為一項被保險人對保險人所作出的、必須確實遵守的承諾'),
('p2', 523, '二', '核保、投保文件與保單結構', '169. 適用於同一險種的所有保單的除外責任稱為為：', '{"A":"通用除外責任","B":"業界除外責任","C":"特定除外責任","D":"其它除外責任"}'::jsonb, 'A', '除外責任可分為業界除外責任、通用除外責任、特定除外責任及其它除外責任'),
('p2', 524, '二', '核保、投保文件與保單結構', '170. 以下那一項不是一般保險中保單條件的一部份?', '{"A":"取消","B":"仲裁","C":"需要可保權益的時間","D":"索償及保險金的安排"}'::jsonb, 'C', '索償或保險金要求、仲裁、取消、比例分攤、保單修改法律狀況及可調整的保費都均為保單條款元素。'),
('p2', 525, '二', '核保、投保文件與保單結構', '171. 以下不是通用除外責任之一?', '{"A":"合約附加的責任","B":"汽車保險中的速度測試","C":"人身意外保險中自殺","D":"核及輻射風險"}'::jsonb, 'D', '核及輻射風險屬於業界除外風險'),
('p2', 526, '二', '核保、投保文件與保單結構', '172. 非人壽保險單的續保:', '{"A":"一定要由保險人提出要約","B":"不需要由保險人提出要約","C":"一定要和現時保單條款一樣","D":"只有在被保人要求才會應允"}'::jsonb, 'B', '保險人和被保險人均無續保，或接受特定條件的義務。續保所採用的確切條款是可以討論和商議的，而要約和承約也屬相關考慮。'),
('p2', 527, '二', '核保、投保文件與保單結構', '173. 以下哪項關於「續保」描述正確？', '{"A":"保險人及客戶均無義務必需續約","B":"保單到期日自動續保","C":"保險人於保單到期日主動提醒客人續保","D":"客人於保單到期日主動提醒保險人續保"}'::jsonb, 'A', '在法律上，保險人沒有義務向被保險人提醒續保日期漸近。'),
('p2', 528, '二', '核保、投保文件與保單結構', '174. 以下哪項有關續保的說明是不正確的?', '{"A":"續保保單被視為一項新的合約","B":"續保後保單條件必定不變","C":"沒有續保的合約視為取消合約","D":"保險人並不一定接納續保"}'::jsonb, 'B', '即使仍使用同一張保單，續保構成了一個新的合約。這對可保性及條款提供了一個核保檢討的機會（如要續保，該等條款當然必須得到被保險人的同意）。'),
('p2', 529, '二', '核保、投保文件與保單結構', '175. 一般保險單通常為期十二個月，若合約雙方對條件不滿而沒有於十二個月後續保，這情況稱為：', '{"A":"取消合約","B":"終止合約","C":"失效合約","D":"不續保合約"}'::jsonb, 'C', '如果保險人不加以提醒，被保險人也沒有採取任何行動，那麽保單就會在期滿時失效。'),
('p2', 530, '二', '核保、投保文件與保單結構', '176. 一般保險的續保是，', '{"A":"非強制性的","B":"對於汽車保險是屬於強制性的","C":"對於長期協議是屬於強制性的","D":"所有保單都是強制性的"}'::jsonb, 'A', '保險人和被保險人均無續保，或接受特定條件的義務。'),
('p2', 531, '二', '核保、投保文件與保單結構', '177. 以下哪項屬保單失效而不是取消保單？', '{"A":"保單已經由保險人終止","B":"保單的保障期滿並沒有續保","C":"保險合約在到期日之前已被終止","D":"保險人被清盤，保單被迫取消"}'::jsonb, 'B', '如果保險人不加以提醒，被保險人也沒有採取任何行動，那麽保單就會在期滿時失效。'),
('p2', 532, '二', '核保、投保文件與保單結構', '178. 根據取消條款，以下哪項描述是正確的？', '{"A":"保險人或被保險人有權取消保單","B":"若保險人取消保單，會退回短期保費","C":"若被保人取消保單，會按比例退回有關保費","D":"以上所有各項"}'::jsonb, 'A', '保險人或被保險人都有取消保單的權利。保險人取消保單將按比例退保費，而被保險人取消保單所得既退款可以短期或比例方式，視乎保單措辭而定。'),
('p2', 533, '二', '核保、投保文件與保單結構', '179. 大多數一般保險都設有取消條款，以下哪兩項是正確的？
i. 保險人或被保險人可隨時取消保單
ii. 不需提出任何理由如保險人提出取消保單，被保險人可獲退回短期保費
iv. 如被保險人提出取消保單，可獲按比例退回保費', '{"A":"i , ii","B":"i , iii","C":"ii , iv","D":"iii , iv"}'::jsonb, 'A', '保險人或被保險人都有取消保單的權利。保險人取消保單將按比例退保費，而被保險人取消保單所得既退款可以短期或比例方式，視乎保單措辭而定。'),
('p2', 534, '二', '核保、投保文件與保單結構', '180. 以下哪項對取消條款的描述是正確的？', '{"A":"它總是賦予保險人及被保險人雙方的一項權利","B":"這條款並不必須，因普通法已有聲明","C":"所有一般保險均附有此條款","D":"如保險人提出取消，須按比例退回保費"}'::jsonb, 'D', '合約條款明確地允許單方面於期滿前取消合約，否則須經合約雙方同意方可。在實務中，大多數一般保險單都設有取消條款。保險人或被保險人都有取消保單的權利。保險人取消保單將按比例退保費，而被保險人取消保單所得既退款可以短期或比例方式，視乎保單措辭而定。'),
('p2', 535, '二', '核保、投保文件與保單結構', '181. 根據一般保單的取消條款，以下哪項屬於正確的描述', '{"A":"保險人有權取消該保單","B":"通常由被保險人取消該保單","C":"若該保單由保險人取消，已繳交的保費可以按比例退還","D":"以上所有各項"}'::jsonb, 'D', '保險人及被保險人都具有取消權，保險人取消保單將按比例退保費，而被保險人取消保單所得既退款可以短期或比例方式，視乎保單措辭而定。'),
('p2', 536, '二', '核保、投保文件與保單結構', '182. 在保險公司取消保單的情況下，保險公司通常：', '{"A":"按比例退回應繳保費","B":"退回全部保費","C":"退回短期保費","D":"沒有保費退回"}'::jsonb, 'A', '保險人取消保單將按比例退保費，而被保險人取消保單所得既退款可以短期或比例方式，視乎保單措辭而定。'),
('p2', 537, '二', '核保、投保文件與保單結構', '183. 短期保費退款通常適用於:', '{"A":"保險失效","B":"被保險人取消保單","C":"保險人取消保單","D":"保險人清盤"}'::jsonb, 'B', '被保險人取消保單所得既退款可以短期或比例方式，視乎保單措辭而定。'),
('p2', 538, '二', '核保、投保文件與保單結構', '184. 以下哪一項最能形容保單已「失效」的意思？', '{"A":"沒有續保的保險單","B":"保險人取消了的保單","C":"被保險人取消了的保單","D":"一份新的保單取提了現有的保單"}'::jsonb, 'A', '沒有續保的保險自然會失效'),
('p2', 539, '二', '核保、投保文件與保單結構', '185. 於通常取消條款下:', '{"A":"保險人有權取消該保單","B":"很多情況下，被保險人有權取消保單","C":"保單被取消後，可退回部份保費","D":"以上各項皆是"}'::jsonb, 'D', '保險人及被保險人都具有取消權，保險人取消保單將按比例退保費，而被保險人取消保單所得既退款可以短期或比例方式，視乎保單措辭而定。'),
('p2', 540, '三', '索償處理', '1. 保險人拒絕索償是因被保險人違反保單條款，但有一種索償是可能凌駕於拒絕索償的理由，這是：', '{"A":"個人意外保險","B":"關於被保險人財產的保險","C":"關於強制性保險保障的範圍","D":"以上所述各項"}'::jsonb, 'C', '根據規定，凡為施行「使若干條款無效及有權追回款項」條款而發出的保險單內載列任何條件，訂定如在引致可根據該保險單提出申索的事故發生後，某些指明事情獲得辦理或沒有辦理，便不會根據該保險單產生法律責任或已如此產生的法律責任即告終止，則該條件對任何適用強制汽車保險相關規定的申索並無效力。'),
('p2', 541, '三', '索償處理', '2. 如必須拒絕一項賠償，以下哪項屬於優良的保險慣例
i. 應該在初期拒絕所有賠償，藉此阻止瑣碎的賠償
ii. 理賠職員不應在沒有細心考慮的情況下拒絕賠償
iii. 一般情況下應該提供拒絕的理由拒絕賠償前，通常最好由保險人的高層職員作出確認', '{"A":"只有 i , ii","B":"只有 ii , iii","C":"只有 ii, iii, iv","D":"i, ii, iii, iv"}'::jsonb, 'C', '拒賠是一件嚴重的事情。優良的保險做法通常意味着永不拒賠，除非得到保險人的高級職員的批准。作為香港保險業聯會的會員，保險人承諾根據該會發出的《承保商專業守則》，如要拒絕賠償或支付保險金，必會給予充分的解釋。'),
('p2', 542, '三', '索償處理', '3. 在受賠償處理中，哪種不是正確的處理方法？', '{"A":"應避免不必要的拖延","B":"出現欺騙成份時，應於初期拒絕賠償","C":"應避免對保單作出不合理的解釋","D":"認定責任後應立即賠款"}'::jsonb, 'B', '保險人處理索償或保險金要求的手法不公正、不公平、不合理或過於遲緩，那麽其聲譽便會受損。在合理的範圍下，賠付或給付是保險人最佳的廣告方式。如要拒絕賠償或支付保險金，必會給予充分的解釋。'),
('p2', 543, '三', '索償處理', '4. 一個有效的索償要乎合下列哪項的要求？', '{"A":"索償沒有涉及欺詐成份","B":"導致索償的情況必須於保單有效期內發生","C":"導致損失的危險必須是由受保的原因引起","D":"以上所有各項"}'::jsonb, 'D', '索償時需考慮當中的因素:(i)被保險人的欺詐行為或以被保險人名義進行的欺詐行為(ii) 保單必須有效(iii) 危險考慮'),
('p2', 544, '三', '索償處理', '5. 以下哪點是符合一個有效索償的法律要求？', '{"A":"意外發生時保單必須有效","B":"並不違反公眾利益","C":"達保單內隱含及明示條款之要求","D":"以上全部都是"}'::jsonb, 'D', '索償時需考慮當中的因素:(i) 保單必須有效(ii) 隱含及明示合約條款(iii) 合乎公共政策'),
('p2', 545, '三', '索償處理', '6. 以下哪項是屬於有效索償的法律要求？
i. 導致損失的近因，必須是受保的危險
ii. 索償是符合保單中隱含及明訂條款的要求
iii. 當損失發生時，保單必須仍然有效
iv. 保單不能與公眾利益有所抵觸', '{"A":"i , ii","B":"ii , iii","C":"i, iii , iv","D":"i, ii, iii , iv"}'::jsonb, 'D', '索償時需考慮當中的因素:(i) 保單必須有效(ii) 隱含及明示合約條款(iii) 合乎公共政策'),
('p2', 546, '三', '索償處理', '7. 以下哪項/幾項會使索償變為無效？
i. 投保事件發生於保單有效日之後
ii. 被保險人作出欺詐的行為
iii. 發生的事件是屬於除外責任
iv. 違反社會上公眾利益的條件', '{"A":"i, ii, iii","B":"i, ii, iv","C":"ii, iii, iv","D":"i, ii, iii, iv"}'::jsonb, 'D', '索償時需考慮當中的因素:(i) 保單必須有效(ii) 隱含及明示合約條款(iii) 合乎公共政策(iv)被保險人的欺詐行為或以被保險人名義進行的欺詐行為'),
('p2', 547, '三', '索償處理', '8. 在建議優良保險慣例中，違反保單保証應：', '{"A":"可以理解為索償可被拒絕","B":"可以理解為可以發出通融賠償","C":"只要有關保証出現時才令索償無效","D":"只要被保險人出現欺詐性行為才令索償無效"}'::jsonb, 'A', '違反保單將有機會影響索償的結果。'),
('p2', 548, '三', '索償處理', '9. 在沒有法律責任下賠付：', '{"A":"屬於違法","B":"在技術上稱為同情賠款","C":"在技術上稱為通融賠付","D":"是永不合理的，因為這相當於懲罰其他的保單持有人"}'::jsonb, 'C', '遇上未必有保單責任的個案時，或拒賠將引致艱難的情況，總可考慮作出通融賠付。'),
('p2', 549, '三', '索償處理', '10. 索償通知上的延誤會使：', '{"A":"被保人必定不能夠得到賠償","B":"保險人不能作出相應的賠償","C":"保險人的利益受到損害","D":"以上所有各項"}'::jsonb, 'C', '索償通知延誤有機會引致被保險人完全喪失相關損失的索償權利或相關事件的保險金要求權。'),
('p2', 550, '三', '索償處理', '11. 當意外發生後，投保人需盡快通知保險公司，否則該項索償將不被接納，這項要求和下列哪項有關？', '{"A":"隱含條款","B":"責任出現前的條件","C":"合約生效前的條件","D":"合約生效後的條任"}'::jsonb, 'B', '違反責任出現前的條件不會毀了整個合約，但會使某索償或保險金要求變成無效。'),
('p2', 551, '三', '索償處理', '12. 在本港簽發的標準火險保單「受比例分攤約束」，意思指：', '{"A":"若損失發生時保額並不足夠，則保單便屬無效","B":"財產價值按平均市場價值計算","C":"保費按該年平均財產價值計算","D":"損失發生時存在不足額保險，被保險人成為共同保險人"}'::jsonb, 'D', '在大部分財產保險中，一旦損失發生時存在着不足額保險，保險人便可根據比例分攤條件，按不足額投保的比例降低賠償額，而被保險人將要承擔餘下的金額。'),
('p2', 552, '三', '索償處理', '13. 在「比例分攤保障」中，如果保額為一千萬，而在火災損毀的實際價值為二千萬，那麼一千二百萬的損毀金額賠償應為：', '{"A":"六百萬","B":"一千萬","C":"一千二百萬","D":"零元(有關索償因極度不足保額而告無效)"}'::jsonb, 'A', '保額為損失額的50%，引致被保險人只能取得50%的賠償額。'),
('p2', 553, '三', '索償處理', '14. 以下哪項保險條款的改動會影響到普通法的條款？', '{"A":"比例分攤","B":"代位權","C":"分攤","D":"以上所有各項"}'::jsonb, 'D', '三種改動:比例分攤、代位權及分攤將會影響索償或保險金要求的保單條文'),
('p2', 554, '三', '索償處理', '15. 普通法的代位權原則有時會被保單的條款更改:', '{"A":"這是不合法的","B":"這是保險人之間的協議","C":"在賠償之前已獲得代位權","D":"以上全部皆不是"}'::jsonb, 'C', '代位權只能在作出賠償之後才能取得；但是，根據典型的代位條件，被保險人必須應保險人的要求，容許保險人於發生了可能引起索償的事件後(賠償前)行使代位權。'),
('p2', 555, '三', '索償處理', '16. 當有索償發生，以下那項屬於受保人應付上的責任？', '{"A":"保存受損害財物","B":"提供索償的數額","C":"提供其他有關類型的索償保單","D":"以上各項皆正確"}'::jsonb, 'D', '保存受損害財物、索償或保險金要求及披露任何其他保險都是受保人應付上的責任。'),
('p2', 556, '三', '索償處理', '17. 以下哪一項不屬於被保險人出現損失後保單涉及的責任要求？', '{"A":"提供有效索償的合理証明","B":"披露任何與該項目相同損失有關的其他保險","C":"保存作為索償物件的已損毀財物","D":"向第三者承認責任及行使所有權力"}'::jsonb, 'D', '向第三者承認責任及行使所有權力不屬於受保人在損失上應付的責任。'),
('p2', 557, '三', '索償處理', '18. 有關索償的文件費用：', '{"A":"只由保險人支付","B":"只由被保人支付","C":"必須由保險人及被保人支付","D":"可以由保險人或被保人支付"}'::jsonb, 'D', '提供證明文件可能是被保險人的責任，也可能是保險人的責任（包括支付所需費用）。'),
('p2', 558, '三', '索償處理', '19. 一般保險的索償，保險人通常會要求以下的哪項文件證明？', '{"A":"醫療報告","B":"收據或其他數額的證明","C":"警方或其他有關當局的報告","D":"上述所有各項"}'::jsonb, 'D', '文件證據包括收據及金額的其他證明、合約要求的文件、水險索償及證人及警方報告等。'),
('p2', 559, '三', '索償處理', '20. 以下哪項醫療證據是由被保險人負責支付有關開支？', '{"A":"於個人意外保單中對於喪失能力的報告","B":"與僱員補償業務有關的報告","C":"為找出死因而安排的任何驗屍檢查報告","D":"以上所有各項"}'::jsonb, 'A', '提出喪失能力（人身意外）的保險金要求，須出具醫療報告，所需費用由被保險人負責。如果僱主要求受傷的僱員進行體檢，體檢費應由僱主按照《僱員補償條例》支付，但最終是由有關的保險人承擔。'),
('p2', 560, '三', '索償處理', '21. 以下哪三項文件可能被要求用作證明水險索償？
i. 檢驗報告
ii. 警方報告
iii. 提貨單
iv. 保單正本', '{"A":"i, ii, iii","B":"i, ii, iv","C":"i, iii, iv","D":"ii, iii, iv"}'::jsonb, 'C', '水險索償所需文件包括檢驗報告、保單正本、提貨單，或再加上其他的所有權文件。'),
('p2', 561, '三', '索償處理', '22. 以下哪項不屬於水險索償中所需文件？', '{"A":"檢驗報告","B":"保單正本","C":"提貨單","D":"警方報告"}'::jsonb, 'D', '水險索償所需文件包括檢驗報告、保單正本、提貨單，或再加上其他的所有權文件。'),
('p2', 562, '三', '索償處理', '23. 聘用於水險貨物索償的檢驗人，與聘用於火險索償的理賠人比較時：', '{"A":"檢驗人起初由保險人委任","B":"理賠人必須由被保險人委任","C":"無論任何時間保險人都不需要向檢驗人支付費用","D":"理賠人由保險人委任和支付費用"}'::jsonb, 'D', '水險的檢驗人與非水險的理賠師之間的最大區別在於後者通常由保險人聘請，而水險的檢驗人是由被保險人聘請的，並且檢驗費用至少是先由被保險人支付的。'),
('p2', 563, '三', '索償處理', '24. 以下哪三項有關理賠師說明是正確的？
i. 他們是由保險人委任
ii. 他們聲稱是該範圍的專家
iii. 他們的收費是按表計算的他們的建議對保險人具約束力，對被保險人則不具約束力', '{"A":"i, ii, iii","B":"i, ii, iv","C":"ii, iii, iv","D":"i, iii, iv"}'::jsonb, 'A', '理賠師通常由保險人聘請及支付服務費，他們聲稱是獨立的專家，提供中立的意見及服務。同時費用可按表計算，視乎同意賠償的金額而定，另作商議也行。'),
('p2', 564, '三', '索償處理', '25. 以下哪項保險會僱用理賠代理人？', '{"A":"火險","B":"水險貨物保單","C":"僱員補償業務","D":"營業中斷保險"}'::jsonb, 'B', '保險人在海上貨物保單或保險憑證上，指名獲授權商號在該保險人沒有設置辦事處的地區，為其處理賠案。理賠代理人可以是勞合社代理人，即受倫敦勞合社委任的，遍及包括香港在內的全球主要港口和地區的商號。'),
('p2', 565, '三', '索償處理', '26. 檢驗代理人通常是：
i. 處理水險索償的工作
ii. 在索償初期通常由被保險人委任
iii. 在索償初期通常由保險人委任
iv. 以個人或公司名義協助安排檢驗', '{"A":"i, ii, iii","B":"i, iii, iv","C":"ii, iii, iv","D":"i, ii, iii, iv"}'::jsonb, 'B', '海上貨物保險人一般在保單或保險憑證上，指明有關目的地的獲委任檢驗代理人的名稱和地址，並要求收貨人向此代理人申請海上損害檢驗。如果某特定檢驗代理人沒有僱用檢驗人，便須在接獲申請後安排檢驗人。勞合社代理人很多時候替海上保險人充當檢驗代理人，而保險人很多時候委任同一商號作為檢驗及理賠代理人。'),
('p2', 566, '三', '索償處理', '27. 檢驗代理人最主要的工作是：', '{"A":"專門處理水險索償","B":"從事有關財產損失","C":"專門從事責任索償","D":"以上所有各項"}'::jsonb, 'A', '檢驗代理人最主要的工作主要處理水險索償。'),
('p2', 567, '三', '索償處理', '28. 以下哪項對於海損理賠師的描述是不正確的？', '{"A":"他們專門從事共同海損的索償","B":"他們對海事及不同國家的法律要有深入的認識","C":"他們專門從事不足額保險(比例分攤)的安排","D":"一個個案的處理時間可能長達數年"}'::jsonb, 'C', '這類專家出現於水險的理賠中。更確切地說，他們專門處理共同海損。這是索償相關工作中極為複雜的領域，需要豐富的經驗和專業知識。為共同海損收款和分攤，一般需時數年，而非幾個星期或幾個月。這種工作需要有耐性和行之有法，所以經驗是非常必要的。'),
('p2', 568, '三', '索償處理', '29. 海損理賠師專門從事：', '{"A":"共同海損的理賠","B":"船體理賠","C":"極為複雜的貨物損失的理賠","D":"以上各項"}'::jsonb, 'D', '這類專家出現於水險的理賠中。更確切地說，他們專門處理共同海損。因其專長，海損理算師也可能參與船殼與機器損失和極為複雜的貨物損失的理賠。'),
('p2', 569, '三', '索償處理', '30. 以下哪項或哪些保單條件可能修改普通法中的條文？', '{"A":"比例分攤","B":"代位權","C":"分擔","D":"以上各項皆正確"}'::jsonb, 'D', '保單修改法律情況如比例分攤、分擔及代位都會造成一些影響。'),
('p2', 570, '三', '索償處理', '31. 下列關於海損理算師的說法中，哪項是不真實的？', '{"A":"他們專門從事共同海損的理賠；","B":"無論何時出現比例分攤(不足額保險)，通常都要用到他們；","C":"他們必須具有不同國家海事法律上的專業知識；","D":"他們單處理某一個案有時就可能需時幾年"}'::jsonb, 'B', '海損理算師中並沒有提及比例分攤的情況。'),
('p2', 571, '三', '索償處理', '32. 在優良保險手法中,以下那些是無效索償的不正確描述?
i.保險人對於這些索償需使用科學手法。
ii.無論任何情況,不應拒絕賠償。
iii. 保險人必須拒絕賠償，就應該給予充分的解釋。只能跟香港保險業聯會發出的《處理投訴的指引》中拒賠。', '{"A":"i,ii,iii","B":"i,ii,iv","C":"i,iii,iv","D":"ii,iii,iv"}'::jsonb, 'B', '優良的保險做法通常意味着永不拒賠，除非得到保險人的高級職員的批准。作為香港保險業聯會的會員，保險人承諾根據該會發出的《承保商專業守則》，如要拒絕賠償或支付保險金，必會給予充分的解釋。'),
('p2', 572, '三', '索償處理', '33. 被保險人發生了損失並要求索償，在普通法中，以下那項或那些是被保險人包括的責任?', '{"A":"沒有任何形式的欺詐行為","B":"在合理的範圍下與保險人合作","C":"有責任在合理的可能情況下，盡量地減少損失","D":"以上各項皆是"}'::jsonb, 'D', '在普通法中，被保險人的責任包括：(i) 在合理的範圍下與保險人合作；(ii)有責任在合理的可能情況下，盡量地減少損失；(iii)不危害保險人的權利（例如代位權）；(iv) 避免欺詐行為（任何形式）。'),
('p2', 573, '三', '索償處理', '34. 以下哪項屬於處理索償時的不正確態度?', '{"A":"應避免合理的拖延","B":"當出現欺詐成份時，便應於初期拒絕索償","C":"避免對保單作出不合理解釋","D":"確認責任後，便應盡快支付索償"}'::jsonb, 'A', '處理索償上應避免不必要的拖延'),
('p2', 574, '三', '索償處理', '35. 在優良保險手法中，以下哪些是無效索償的不正確描述？
i. 保險人對於這些索償需使用科學手法
ii. 無論任何情況，不應拒絶索償
iii. 保險人拒絶索償的話，應該給予充分的解釋只能跟據香港保險業聯會發出的處理投訴的指引拒賠', '{"A":"i, ii, iii","B":"i, iii, iv","C":"iI, iii, iv","D":"i, iii, iv"}'::jsonb, 'D', '守則提及到保險人應合理地處理索償'),
('p2', 575, '三', '索償處理', '36. 若對理賠中的數額有所爭拗，以下哪類人仕可提出仲裁？', '{"A":"保險人而已","B":"被保人而已","C":"保險人或被保人","D":"保險人及被保人也不可提出"}'::jsonb, 'C', '被保險人與保險人當然也可以因理賠糾紛上提出仲裁。'),
('p2', 576, '三', '索償處理', '37. 仲裁與訴訟的分別之處在於？
i. 仲裁的程序比訴訟為簡單
ii. 訴訟的費用必定比仲裁便宜
iii. 仲裁中的代表不必符合法律資格
iv. 兩者的結果對合約任何一方都具約束力', '{"A":"i, ii","B":"i, iii","C":"ii, iii","D":"iii, iv"}'::jsonb, 'B', '仲裁比起訴訟不那麽正式，雖然仲裁以正式的方式進行，然而案件不在法庭進行聽證，甚至不由符合法律資格的人來代表當事人各方或決定有關事項也沒問題。糾紛還可能出現在保險人與第三者索償人之間，但是第三者不受仲裁條件的約束。'),
('p2', 577, '三', '索償處理', '38. 以下哪項對於仲裁的描述是正確的？', '{"A":"它的形式和程序比起法庭的訴訟簡單","B":"對第三者並無約束力","C":"只適用於涉及金額上的糾紛","D":"以上各項皆正確"}'::jsonb, 'D', '仲裁比起訴訟不那麽正式，雖然仲裁以正式的方式進行，然而案件不在法庭進行聽證，甚至不由符合法律資格的人來代表當事人各方或決定有關事項也沒問題。糾紛還可能出現在保險人與第三者索償人之間，但是第三者不受仲裁條件的約束。最後糾紛的原因主要有關個別賠案難以處理，產生被保險人與保險人之間的糾紛。'),
('p2', 578, '三', '索償處理', '39. 以下哪種解決糾紛的情況屬於法庭聽證及裁決等正式的過程？', '{"A":"訴訟","B":"調解","C":"仲裁","D":"談判"}'::jsonb, 'A', '訴訟意見上指正式的法庭行動。'),
('p2', 579, '三', '索償處理', '40. 出現於法庭聽證會上，涉及法律的過程稱之為：', '{"A":"仲裁","B":"訴訟","C":"糾紛","D":"解決"}'::jsonb, 'B', '訴訟意見上指正式的法庭行動。'),
('p2', 580, '三', '索償處理', '41. 為甚麼人身意外保險一般不會設有仲裁條款？', '{"A":"這類保單是不合法的","B":"人身意外保險不存在金錢上的糾紛","C":"因為被保險人很多時在索償進行中已去世","D":"因為這類保單的索償金額不可能高到值得仲裁"}'::jsonb, 'B', '人身意外保險以人的生命、肢體、健康或醫療費用作為保險標的的險種。例如由暴力、意外、外在和可見的方式導致身體受傷後，可獲付為相關類別身體受傷指明的金額，所以不存在有關金錢上的糾紛。'),
('p2', 581, '三', '索償處理', '42. 以下哪項是仲裁一般保險糾紛索償的方法的特點?', '{"A":"形式及程序比訴訟簡單","B":"通常只適用於數額而已","C":"對第三者沒有約束力","D":"以上所有各項"}'::jsonb, 'D', '仲裁比起訴訟不那麽正式，雖然仲裁以正式的方式進行，然而案件不在法庭進行聽證，甚至不由符合法律資格的人來代表當事人各方或決定有關事項也沒問題。糾紛還可能出現在保險人與第三者索償人之間，但是第三者不受仲裁條件的約束。最後糾紛的原因主要有關個別賠案難以處理，產生被保險人與保險人之間的糾紛'),
('p2', 582, '三', '索償處理', '43. 仲裁條款出現於以下哪類保單？', '{"A":"個人意外保險","B":"財產保險","C":"責任保險","D":"以上各項都是"}'::jsonb, 'B', '仲裁條款會出現於一般保險中的財產保險。'),
('p2', 583, '三', '索償處理', '44. 在保險索償中之兩種元素為「責任」和「數額」，後者所表達的意思是指：', '{"A":"有關的保額","B":"保險人在約束下需要給付款項的時間","C":"保險人應給付之總額","D":"要確定是否與「近因」的原則有關"}'::jsonb, 'C', '數額是指由保險人理賠上所付出的金額。'),
('p2', 584, '三', '索償處理', '45. 由於一般保險中仲裁條款是有關金額多少的問題，若干保單沒有仲裁條款，以下哪一項金額問題已由保單條款所釐定？', '{"A":"火險保單","B":"盜竊保單","C":"個人意外保單","D":"以上所有各項"}'::jsonb, 'C', '人身意外保險以人的生命、肢體、健康或醫療費用作為保險標的的險種。例如由暴力、意外、外在和可見的方式導致身體受傷後，可獲付為相關類別身體受傷指明的金額，所以不存在有關金錢上的糾紛。'),
('p2', 585, '三', '索償處理', '46. 在理賠的情況下，爭議雙方可委任一名獨立仲裁員，如果他們未能就一名仲裁員達成協議，雙方便需各自委任一名仲裁員，再由這些仲裁員委任以下哪一名人仕在商議過程中列席？', '{"A":"公斷人","B":"公證人","C":"訴訟人","D":"評判師"}'::jsonb, 'A', '除仲裁員以外，公斷人亦會參與參與仲裁過程，為雙方的選定達成協議。'),
('p2', 586, '三', '索償處理', '47. 以下那項有關仲裁條款是不正確的？', '{"A":"通常每項索償中只有一個仲裁人","B":"如有需要，各方可安排一個仲裁人","C":"如有兩個仲裁人，可選出一名公斷人在出裁決","D":"公斷人對該索償釐定有關保費事宜"}'::jsonb, 'D', '公斷人只會參與參與仲裁過程，為雙方的選定達成協議。'),
('p2', 587, '三', '索償處理', '48. 以下哪類人仕可決定以何種方法作出「損害賠償」?', '{"A":"保險代理人","B":"保險經紀","C":"公斷人","D":"保險人"}'::jsonb, 'D', '保險人有權選擇怎麽向被保險人提供彌償。'),
('p2', 588, '三', '索償處理', '49. 現金支付較可能是適合下列那項結清給付形式?', '{"A":"個人意外保險的死亡賠償","B":"醫療賬單開支(旅遊保險)","C":"第三者受傷的索償(汽車保險)","D":"以上所有各項"}'::jsonb, 'D', '支付現金（總是使用支票或透過銀行轉賬）是一種最為普遍的結清索償或保險金要求方式。'),
('p2', 589, '三', '索償處理', '50. 對於提供利益而非損害賠償的保單，那項是結清給付的唯一可行方法？', '{"A":"現金支付","B":"直接支付維修費用","C":"更換","D":"恢復原狀"}'::jsonb, 'A', '向被保險人提供利益保單(例如人身意外保險利益)，支付現金是唯一的方式。'),
('p2', 590, '三', '索償處理', '51. 以下哪項結清方法是以現金支付的唯一可行方法？', '{"A":"汽車損毀","B":"個人意外","C":"財物損失","D":"以上各項均是"}'::jsonb, 'B', '向被保險人提供利益保單(例如人身意外保險利益)，支付現金是唯一的方式。'),
('p2', 591, '三', '索償處理', '52. 以下哪項是適合以更換作為損害賠償的結清方式？', '{"A":"玻璃保險","B":"全新或基本上全新的物品","C":"不存有折舊問題的物品","D":"以上所有各項"}'::jsonb, 'D', '玻璃、不會折舊的物品及全新或幾乎是全新的物品都可以以更換來作結清的方式。'),
('p2', 592, '三', '索償處理', '53. 以下哪三項是適合「更換」結清給付方式的情況？
i. 破裂的玻璃(玻璃保險)
ii. 遭遺失的珠寶(「全險保險」)
iii. 遭盜竊的新攝影機(旅遊保險)
iv. 船隻的全損(水險)', '{"A":"i, ii, iii","B":"i, ii, iv","C":"i, iii, iv","D":"ii, iii, iv"}'::jsonb, 'A', '玻璃、不會折舊的物品及全新或幾乎是全新的物品都可以以更換來作結清的方式。'),
('p2', 593, '三', '索償處理', '54. 以下哪項可以是形容恢復原狀這種理賠方式', '{"A":"重新修建被損毀的建築物","B":"可能是涉及火災保險的","C":"在某些規定的情況下，保險人可能被強制作出此安排","D":"以上各項都是"}'::jsonb, 'D', '恢復原狀涉及火險的理賠方式，方式是指使受保財產恢復到在受毀或受損以前那一刻所處的狀況。同時保險人有權選擇怎麽向被保險人提供彌償。然而因為希望令顧客感到滿意，絕少有保險人會強迫被保險人接受不情願的結清方式。'),
('p2', 594, '三', '索償處理', '55. 以下哪項屬於保險投訴局可處理的範圍？', '{"A":"酒店的鍋爐爆炸保單","B":"正進行仲裁或訴訟的個案","C":"涉及五十五萬元的個人意外保單","D":"以上所有各項"}'::jsonb, 'C', '保險投訴局可處理的範圍包括:涉案保單屬於個人保單、投訴個案的索償金額／爭議金額不超過 100萬港元及投訴個案並非正在進行法律程序或仲裁。'),
('p2', 595, '三', '索償處理', '56. 下列哪項是對保險索償投訴局的不正確描述？', '{"A":"處理70萬以下的索償","B":"接受各類型保險的投訴","C":"不論勝訴與否，也不會向投訴人徵收費用","D":"處理個人保險的投訴"}'::jsonb, 'B', '保險投訴局只接受涉案保單屬於個人保單的個案。'),
('p2', 596, '三', '索償處理', '57. 以下哪項或哪些索償投訴可能是保險投訴局的處理範圍？
i. 正在進行仲裁的索償
ii. 裝在船外的發動器損毀(私人的遊艇保險)
iii. 酒店鍋爐的損壞(鍋爐保險)個人人身意外保險的$250,000死亡利益(私人的人身意外保險)', '{"A":"i, ii","B":"i, iv","C":"ii, iii","D":"ii, iv"}'::jsonb, 'D', '保險投訴局可處理的範圍包括:涉案保單屬於個人保單及投訴個案並非正在進行法律程序或仲裁。鍋爐爆炸保險屬工程保險。'),
('p2', 597, '三', '索償處理', '58. 下列哪項不是保險投訴局的特點?', '{"A":"賠償的上限為七十萬港幣","B":"適用於任何種類索償","C":"無論勝數與否, 訴訟毋須支付任何費用","D":"只適用於保險索償投訴局成員的保險人"}'::jsonb, 'B', '保險投訴局只接受涉案保單屬於個人保單的個案。'),
('p2', 598, '三', '索償處理', '59. 以下哪項屬於保險投訴局的職權範圍？', '{"A":"涉及五十五萬的意外賠償","B":"七萬五千元的家居電器賠償","C":"二十五萬元的火災賠償","D":"以上所有各項"}'::jsonb, 'D', '保險投訴局可處理的範圍包括投訴個案的索償金額／爭議金額不超過 100萬港元。'),
('p2', 599, '三', '索償處理', '60. 以下哪項屬於保險投訴局的權力範圍可處理的個案？', '{"A":"失竊了值七萬五千元的手錶(家居保險)","B":"二萬五千元的醫療開支(個人意外保險)","C":"十五萬元的火災損毀(家居火災保單)","D":"以上所有各項"}'::jsonb, 'D', '保險投訴局可處理的範圍包括投訴個案的索償金額／爭議金額不超過 100萬港元。'),
('p2', 600, '三', '索償處理', '61. 以下哪項是對保險投訴局處理個案的不正確描述？', '{"A":"投訴須於索償後6個月內提出","B":"個案不得已經進行起訴或仲裁","C":"保險人必須已向被保險人通知自己的最後決定","D":"以上各項皆是"}'::jsonb, 'A', '投訴人須於接獲保險人發出的最終決定的六個月內，向保險投訴局作出書面投訴。'),
('p2', 601, '三', '索償處理', '62. 根據保單條款，誰人可決定是次賠付以支付現金或更換進行？', '{"A":"保險人","B":"被保險人","C":"保險中介人","D":"仲裁員/公斷人"}'::jsonb, 'A', '保險人有權選擇怎麽向被保險人提供彌償。然而因為希望令顧客感到滿意，絕少有保險人會強迫被保險人接受不情願的結清方式。'),
('p2', 602, '三', '索償處理', '63. 當“恢復原狀”一詞運用在一般保險保單時，以下哪項或哪些是這一詞的意義？', '{"A":"重建受損的建築物","B":"更換受火災焚燒後的汽車","C":"恢復及修理受損的建築物","D":"以上各項皆是"}'::jsonb, 'D', '恢復原狀是使受保財產恢復到在受毀或受損以前那一刻所處的狀況，重建受損的建築物是頗為普遍的結清方式，而恢復原狀一詞的含義與「修理」和「更換」的含義是有重疊的，所以更換受火災焚燒後的汽車也是恢復原狀的一種。'),
('p2', 603, '三', '索償處理', '64. 以下哪一個案屬於保險索償投訴局的處理範圍內？', '{"A":"關於增加續保保費的投訴","B":"被保險人已經向保險人發出令狀的個案","C":"丟失價值二萬五千港元手錶的個人旅遊保險索償","D":"某公司對比例分攤條件降低其火災索償金額有所不滿"}'::jsonb, 'C', '保險投訴局可處理的範圍包括:投訴個案屬金錢性質、涉案保單屬於個人保單及投訴個案並非正在進行法律程序或仲裁及投訴個案的索償金額／爭議金額不超過 100 萬港元。'),
('p2', 604, '三', '索償處理', '65. 以下哪項是適合於更換結清方式的情況？', '{"A":"全新的受保汽車在登記後的首年內被毀","B":"第三者的受傷的責任","C":"個人意外死亡","D":"以上所有各項都不是"}'::jsonb, 'A', '不會折舊的物品及全新或幾乎是全新的物品都可以以更換來作結清的方式。'),
('p2', 605, '三', '索償處理', '66. 以下哪一個案屬於保險投訴局的處理範圍內？', '{"A":"關於增加續保保費的投訴","B":"被保險人已經向保險人發出令狀的個案","C":"丟失價值二萬五千港元手錶的個人旅遊保險索償","D":"某公司對比例分攤條件降低其火災索償金額有所不滿"}'::jsonb, 'C', '保險投訴局投訴個案屬金錢性質、投訴個案的索償金額／爭議金額不超過100萬港元，以及涉案保單屬於個人保單。'),
('p2', 606, '三', '索償處理', '67. 當恢復原狀一詞運用在一般保險保單時，以下哪項或哪些是這一詞的意義？', '{"A":"重建受損的建築物","B":"更換受火災焚燒後的汽車","C":"恢復及修理受損的建築物","D":"以上各項皆是"}'::jsonb, 'D', '在保險中，這個詞有多種解釋。作為結清索償的方式，它是指使受保財產恢復到在受毀或受損以前那一刻處的狀況。為被毀建築物恢復原狀除會涉及重建開支外，還會涉及拆毀費用。'),
('p2', 607, '三', '索償處理', '68. 與索償無關的調解服務，其受理上限金額為:', '{"A":"50萬","B":"95萬","C":"100萬","D":"200萬"}'::jsonb, 'C', '與索償無關的調解服務，其受理上限金額為100萬'),
('p2', 608, '三', '索償處理', '69. 以下哪項不屬於結清方式？', '{"A":"更換","B":"恢復原狀","C":"重新選購","D":"支付現金"}'::jsonb, 'C', '重新選購不屬於結清方式，方式應包括支付現金、直接支付修理費用、更換及恢復原狀'),
('p2', 609, '四', '客戶服務與專業操守', '1. 以下哪3項提供資料及指引，在客戶服務方面鼓勵保險人及其員工？
i. 香港保險業監管局
ii. 保單持有人團體
iii. 個別保險人本身
iv. 保險業(行業機構)', '{"A":"i, ii, iii","B":"i, ii, iv","C":"i, iii, iv","D":"ii, iii, iv"}'::jsonb, 'C', '客戶服務方面，公司內部、保險業及監管機構均有不同的指引及聲明，提高整體客戶服務的水平。'),
('p2', 610, '四', '客戶服務與專業操守', '2. 以下哪項會對保險人的顧客服務進行監察？
i. 香港特區政府
ii. 保險業組織
iii. 保單持有人和公眾
iv. 保險人本身(內部部門監管)', '{"A":"i, ii, iii","B":"i, ii, iv","C":"ii, iii, iv","D":"i, ii, iii, iv"}'::jsonb, 'D', '監察方面，無論政府、監管機構、保險人或客人身上都會對保險人的顧客服務進行監察。'),
('p2', 611, '四', '客戶服務與專業操守', '3. 客戶服務經已成為保險人的重要考慮因素，以下哪項或哪些可能會對這題目有興趣？', '{"A":"個別保險人","B":"保險業","C":"政府","D":"以上各項皆是"}'::jsonb, 'D', '客戶服務方面，公司內部、保險業及監管機構均有不同的指引及聲明，提高整體客戶服務的水平。'),
('p2', 612, '四', '客戶服務與專業操守', '4. 以下哪項對客戶服務的形容是不正確的？', '{"A":"如果表現良好，它可以帶來多項正面的結果","B":"如果表現差劣，便可能有流失客戶的結果","C":"如果表現差劣，便可能失去中介人的支援","D":"政府將整項問題交給業界處理"}'::jsonb, 'D', '監管機構當然會監察行業運作，保險人獲授權在香港經營保險業務外，還希望他們能提高香港的地位及聲譽。'),
('p2', 613, '四', '客戶服務與專業操守', '5. 不良服務的負面影響為：', '{"A":"可以保留客戶，增加「忠誠度」","B":"喪失中介人的支援","C":"提升顧客推薦的「生產力」","D":"減少處理投訴的時間，即提升盈利能力"}'::jsonb, 'B', '如果保險中介人所付出的努力得不到高質量服務的支援，那麽就不能合理地期望他們能夠擴展業務。'),
('p2', 614, '四', '客戶服務與專業操守', '6. 保險人提供不良的客戶服務，會帶來負面結果包括：
i. 損失生意
ii. 喪失中介人的支援
iii. 破壞市場聲譽
iv. 政府介入', '{"A":"i, ii , iii","B":"i, ii , iv","C":"ii, iii , iv","D":"i, ii, iii , iv"}'::jsonb, 'D', '不良客戶服務將帶來以下後果:(i)喪失業務(ii) 喪失保險中介人的支持(iii) 破壞市場聲譽(iv) 監管機構介入'),
('p2', 615, '四', '客戶服務與專業操守', '7. 如果不注重客戶服務，便會預期帶來以下哪項「負面」結果？', '{"A":"損失生意","B":"增加口碑推薦的顧客生產力","C":"因減少耗於處理投訴的時間而提升的盈利能力","D":"以上所有各項"}'::jsonb, 'A', '不良客戶服務將帶來以下後果:(i)喪失業務(ii) 喪失保險中介人的支持(iii) 破壞市場聲譽(iv) 監管機構介入'),
('p2', 616, '四', '客戶服務與專業操守', '8. 如保險人不注重客戶服務，若干投訴後，以下那類或幾項會發生：', '{"A":"可能會流失客戶","B":"可能不被中介人支持","C":"政府可能會介入","D":"以上各項"}'::jsonb, 'D', '不良客戶服務將帶來以下後果:(i)喪失業務(ii) 喪失保險中介人的支持(iii) 破壞市場聲譽(iv) 監管機構介入'),
('p2', 617, '四', '客戶服務與專業操守', '9. 以下哪項屬於提供優良客戶服務的影響：', '{"A":"提升顧客忠誠度","B":"提升顧客生產力，向其他客戶大力推薦","C":"提升盈利能力","D":"以上各項皆正確"}'::jsonb, 'D', '客戶服務的正面影響的：(i) 顧客忠誠度(ii) 顧客「生產力」(iii) 提升盈利能力'),
('p2', 618, '四', '客戶服務與專業操守', '10. 假如保險人採取的客戶服務態度是「需要便取，不需要便算」時，請問會有以下哪項的結果？
i.喪失客戶
ii.喪失保險中介人的支持
iii.可能引致政府的關注或介入
iv.會遭受業界及市場的反對', '{"A":"i, ii","B":"ii, iii","C":"iii, iv","D":"i, ii, iii, iv"}'::jsonb, 'D', '不良手法對待客戶下，將有以下幾個後果:(i) 喪失業務(ii) 喪失保險中介人的支持(iii) 破壞市場聲譽(iv) 監管機構介入'),
('p2', 619, '四', '客戶服務與專業操守', '11. 提供優良客戶服務十分重要,以下那項屬於客戶「生產力」的影響?', '{"A":"將續保現有保單","B":"向家人和朋友推薦, 協助招攬新生意","C":"可以避免投訴,提升盈利能力","D":"以上各項皆是"}'::jsonb, 'B', '顧客「生產力」指對保險人的表現感到愉快及滿意的顧客，不僅會繼續光顧保險人，而且還會向家人和朋友大力推薦及作口頭廣告，極有效地協助招攬新生意。'),
('p2', 620, '四', '客戶服務與專業操守', '12. 一種對於保險人意願及服務標準的公開宣言，該聲明較可能包括', '{"A":"一項對素質及服務承諾的保證","B":"一項不會拒絕任何索償保證","C":"一種稱為市場提供最優惠保費的保證","D":"以上所有各項"}'::jsonb, 'A', '保險人為保險中介人及保單持有人而設立的公開的宣告，内容相當可能包括：(i) 對素質及服務所承擔的義務；(ii) 對高專業標準的奉獻；(iii) 對效率及高商業道德的承諾；(iv)保證公平及迅速地處理索償或保險金要求；(v)有關商業操守及某些做法的具體資訊。'),
('p2', 621, '四', '客戶服務與專業操守', '13. 以下哪項不會出現在保險公司的商業標準宣言中？', '{"A":"一項對質素和服務的承諾","B":"一種對效率和商業操守的保証","C":"一種對提供最低保險產品的保証","D":"涉及商業操守和實務方法的特定資訊"}'::jsonb, 'C', '保險人並不可能保留最低保險產品的保証。'),
('p2', 622, '四', '客戶服務與專業操守', '14. 下列哪項是預期服務標準的公開宣言？', '{"A":"保險人作出的承諾","B":"顧客義務的提醒","C":"上述兩項","D":"上述兩項都不是"}'::jsonb, 'A', '保險人應主動提供最佳實務及承諾，而不是由顧客所提醒。'),
('p2', 623, '四', '客戶服務與專業操守', '15. 保險公司服務方針及操守守則對公司起著關鍵性的推動力，亦同時作為宣告方向的標準，這宣告的原則是', '{"A":"法律所要求的","B":"每個保險人都必須制定相同的原則","C":"每家保險公司都可以自行制定類似的原則","D":"以上各項皆不是"}'::jsonb, 'C', '很多香港公司已經製作了服務方針及操守守則公開的宣告，這種做法將越來越普遍。每家公司在設計這些文件時，當然都有自己的表達風格和內容。'),
('p2', 624, '四', '客戶服務與專業操守', '16. 保險人有時會制定文件，用以提醒某些人仕之操守，以下哪兩項是該文件基本的制定對象？
i. 保單持有人
ii. 保險中介人
iii. 香港保險業聯會
iv. 保險業監督', '{"A":"i, ii","B":"i, iii","C":"ii, iii","D":"iii, iv"}'::jsonb, 'A', '很多香港保險公司已經製作了公開的服務政策及操守守則，這些都是為保險中介人及保單持有人而設立的。'),
('p2', 625, '四', '客戶服務與專業操守', '17. 保險公司製作了公開的宣告，每家公司在設計這些文件時，都是為保險中介人及保單持有人而設立的，内容相當可能包括：
i. 對素質及服務所承擔的義務
ii. 對高專業標準的奉獻
iii. 對效率及高商業道德的承諾
iv. 保證公平及迅速地處理索償或保險金要', '{"A":"i, ii, iii","B":"i, iii, iv","C":"iI, iii, iv","D":"i, ii, iii, iv"}'::jsonb, 'D', '內容還包括：有關商業操守及某些做法的具體資訊'),
('p2', 626, '四', '客戶服務與專業操守', '18. 保險人印製在業務上的客戶服務標準宣言，內容包括', '{"A":"辨別顧客的需要","B":"一種儘快提供文件的承諾","C":"一種對所提供資料保密的保證","D":"以上所有各項"}'::jsonb, 'D', '客戶服務標準及其實施包括:(a) 識別顧客的需求(b) 保密及依從(c) 提供所需保險保障(d) 保險文件提供的速度(e)理賠承諾，公平地處理索償或保險金要求'),
('p2', 627, '四', '客戶服務與專業操守', '19. 客戶服務標準的宣告：', '{"A":"必須保持機密","B":"每位保險人也略有不同","C":"不合時宜，很多保險人不再採用","D":"必須按〈保險公司條例〉要求"}'::jsonb, 'B', '不同保險人所宣告的客戶服務標準在細節上可能有所差別'),
('p2', 628, '四', '客戶服務與專業操守', '20. 一些宣告很可能提醒被保人及中介人某些必須負上的義務，包括：', '{"A":"對於重要事實遵行最高誠信原則責任的需要","B":"中介人受到實務守則的約束","C":"被保險人按時繳交保費的需要","D":"以上所有各項"}'::jsonb, 'D', '被保險人和保險中介人被要求履行的義務包括：(i) 披露的要求：最高誠信責任(ii)支付保費：按時支付保費的義務，以及保險中介人任何允許的信貸安排(iii) 保險代理人受到實務守則的約束'),
('p2', 629, '四', '客戶服務與專業操守', '21. 以下那三項相當有可能包括在本港保險人發出的客戶服務標準宣言中？
i. 確定客人需要
ii. 保證必定支付所有索償
iii. 準確及公平地提供索償
iv. 提供客人需要之保障', '{"A":"i, ii, iii","B":"i, ii, iv","C":"i, iii, iv","D":"ii, iii, iv"}'::jsonb, 'C', '客戶服務標準及其實施包括:(a) 識別顧客的需求(b) 保密及依從(c) 提供所需保險保障(d) 保險文件提供的速度(e)理賠承諾，公平地處理索償或保險金要求'),
('p2', 630, '四', '客戶服務與專業操守', '22. 針對客戶服務標準的規定及推行,實需要一種操守及處事的開明手法,描述這種需要的慣常用語是:', '{"A":"誠信","B":"透明度","C":"問責性","D":"榮譽"}'::jsonb, 'B', '「透 明度」是現代社會中一個很重要的詞，指操守及做法都應公開交代，並且不論什麽時候都要符合法律及道德的規範。'),
('p2', 631, '四', '客戶服務與專業操守', '23. 客戶服務標準的公開聲明:', '{"A":"必須保密","B":"每個保險人都略有不同","C":"不合時宜，很多保險人不再採用","D":"必須按保險業之要求"}'::jsonb, 'B', '每個保險人都有不同的客戶服務宣言'),
('p2', 632, '四', '客戶服務與專業操守', '24. 根據《承保商專業守則》，以下哪項是發揮優良保險慣例的應有標準？', '{"A":"產品剖析","B":"廣泛的顧客權益","C":"承保及索償","D":"以上所有各項"}'::jsonb, 'D', '守則為保險人提供標準，這包括：(i) 提供建議及銷售慣例(ii) 索償(iii) 保險代理人的管理(iv) 僱員管理(v) 保險人違規行為(vi) 查詢、投訴及糾紛'),
('p2', 633, '四', '客戶服務與專業操守', '25. 以下哪項對於保險公司來說是重要的？', '{"A":"代理法","B":"合約法","C":"法定的條例","D":"以上所有各項"}'::jsonb, 'D', '代理法、合約法及法定條例(保險業條例)也對公司運作十分重要。'),
('p2', 634, '四', '客戶服務與專業操守', '26. 《保險業條例》不會將一般保險公司就下面哪項事宜作出規管？', '{"A":"授權","B":"償付能力","C":"資產報酬率","D":"董事及控權人需為「適當的人選」"}'::jsonb, 'C', '《保險業條例》對保險公司作出了若干嚴格的要求:(i) 保險人的授權(ii) 股本規定(iii) 償付能力的規定(iv)控權人、董事、管控要員及獲委任精算師須屬「適當人選」(v) 「足夠」的再保險'),
('p2', 635, '四', '客戶服務與專業操守', '27. 根據《保險業條例》，以下哪項是規定了對保險公司嚴格要求
i. 保險人的股本
ii. 保險人有足夠的再保險
iii. 保險人的授權
iv. 保險人的償付能力', '{"A":"i, ii, iii","B":"i, ii, iv","C":"i, iii, iv","D":"i, ii, iii, iv"}'::jsonb, 'D', '《保險業條例》對保險公司作出了若干嚴格的要求:(i) 保險人的授權(ii) 股本規定(iii) 償付能力的規定(iv)控權人、董事、管控要員及獲委任精算師須屬「適當人選」(v) 「足夠」的再保險'),
('p2', 636, '四', '客戶服務與專業操守', '28. 《保險業條例》規定本港的保險人必須：', '{"A":"有「足夠」的再保險","B":"購買能夠維持去年盈利能力的再保險","C":"最少擁有50%的風險已購買再保險","D":"擁有50%的盈利是來自再保險"}'::jsonb, 'A', '「足夠」的再保險是《保險業條例》對保險公司作出了若干嚴格的要求之一。'),
('p2', 637, '四', '客戶服務與專業操守', '29. 《保險業條例》對保險人的嚴格要求不包括：', '{"A":"保險人的授權","B":"股本規定","C":"盈利指標","D":"償付能力的規定"}'::jsonb, 'C', '盈利指標不是《保險業條例》對保險公司作出了若干嚴格的要求。'),
('p2', 638, '四', '客戶服務與專業操守', '30. 以下那個或哪些機構制定《承保商專業守則》？', '{"A":"保險業條例","B":"保險業監督","C":"香港保險業聯會","D":"以上各項"}'::jsonb, 'C', '《承保商專業守則》這套守則由香港保險業聯會制定。'),
('p2', 639, '四', '客戶服務與專業操守', '31. 以下哪項是對承保商專業守則的不正確描述？', '{"A":"它由香港保險業聯會制定","B":"它通用於香港居民以個人身份作為保單持有人的個人保單","C":"它適用於所有個人保單","D":"以上各項皆是"}'::jsonb, 'C', '《承保商專業守則》由香港保險業聯會制定。'),
('p2', 640, '四', '客戶服務與專業操守', '32. 《承保商專業守則》由香港保險業聯會制定，適用於', '{"A":"個人及商業保險的保單持有人的保單","B":"於任何地方簽發，以個人為保單持有人的個人保單","C":"於香港簽發，以個人為保單持有人的個人保單","D":"於香港簽發，以個人或公司作為保單持有人的個人保單"}'::jsonb, 'C', '《承保商專業守則》適用於在香港簽發，由香港居民以個人身份，只為私人用途購買的保單。'),
('p2', 641, '四', '客戶服務與專業操守', '33. 以下哪項的內容是涉及提供建議及銷售慣例？', '{"A":"保險業條例","B":"承保商專業守則","C":"保險代理管理守則","D":"標準代理合約"}'::jsonb, 'B', '《承保商專業守則》旨於推廣保險業界的良好慣例，以及加強消費者認識保險服務應有的水平。'),
('p2', 642, '四', '客戶服務與專業操守', '34. 《承保商專業守則》包括優良保險慣例的部份。這部份處理以下哪類的事情？', '{"A":"承保及索償","B":"客戶的權益及需負的責任","C":"廣泛的顧客權利及權益","D":"以上所有各項"}'::jsonb, 'D', '《承保商專業守則》為保險人就多個範疇提供標準，包括:(i) 提供建議及銷售慣例(ii) 索償(iii) 保險代理人的管理(iv) 僱員管理(v) 保險人違規行為(vi) 查詢、投訴及糾紛'),
('p2', 643, '四', '客戶服務與專業操守', '35. 以下那項對《承保商專業守則》的說明是不正確的？', '{"A":"它適用於香港居民以個人身份作為保單持有人","B":"它適用於個人保險","C":"所有保險必須在承保商專業守則範圍之內","D":"這套守則由香港保險業聯會制定"}'::jsonb, 'C', '這套守則由香港保險業聯會制定，適用於在香港簽發，由香港居民以個人身份，只為私人用途購買的保單，旨於推廣保險業界的良好慣例，以及加強消費者認識保險服務應有的水平。'),
('p2', 644, '四', '客戶服務與專業操守', '36. 以下哪項刊載保險代理人及保險經紀的角色及責任，並包括定義及不適當地自稱為其中一種中介人的處分的法定條例？', '{"A":"標準代理合約","B":"承保商專業守則","C":"保險業條例","D":"保險代理管理守則"}'::jsonb, 'C', '《保險業條例》從法規上確定了對持牌保險中介人所作的規定的重要性。'),
('p2', 645, '四', '客戶服務與專業操守', '37. 《持牌保險代理人操守守則》的9個一般原則部份包括：
i. 誠實及持正
ii. 公平行事
iii. 資料披露
iv. 公司管治與管控及程序', '{"A":"i, ii, iii","B":"i, ii, iv","C":"ii, iii, iv","D":"i, ii, iii, iv"}'::jsonb, 'D', '一般原則有以下 9 個部份；(1) 誠實及持正；(2) 公平行事並符合客戶的最佳利益；(3) 以謹慎、技巧和努力行事；(4) 勝任提供意見；(5) 資料披露；(6) 意見的合適性；(7) 利益衝突；(8) 客戶資產；及(9) 公司管治與管控及程序。'),
('p2', 646, '四', '客戶服務與專業操守', '38. 保險經紀公司的規定是因應下列哪項條款設定的?', '{"A":"標準代理合約","B":"承保商專業守則","C":"保險業 (持牌保險經紀公司的財務及其他要求) 規則","D":"保險代理管理守則"}'::jsonb, 'C', '持牌保險經紀公司必須遵守《保險業(持牌保險經紀公司的財務及其他要求)規則》'),
('p2', 647, '四', '客戶服務與專業操守', '39. 以下哪項可以直接或間接地運用於客戶服務上？', '{"A":"個人資料(私隱)條例","B":"性別歧視條例","C":"殘疾歧視條例","D":"以上所有各項"}'::jsonb, 'D', '客戶服務上必須遵守以上三條的條例，其他條例可以再參考4.4(i)。'),
('p2', 648, '四', '客戶服務與專業操守', '40. 以下哪項對於《承保商專業守則》的描述是不正確的', '{"A":"屬於《保險業條例》的一部份","B":"由香港保險業聯會制定","C":"目的是發揮優良保險摜例","D":"提供建議及銷售慣例"}'::jsonb, 'A', '《承保商專業守則》不屬於《保險業條例》的一部份。'),
('p2', 649, '四', '客戶服務與專業操守', '41. 為施行法定規管對保險代理人和保險經紀下的定義可以在以下哪一項找到？', '{"A":"承保商專業守則","B":"保險業條例","C":"個人資料(私隱)條例","D":"保險代理管理守則"}'::jsonb, 'B', '《保險業條例》從法規上確定了對持牌保險中介人所作的規定的重要性。'),
('p2', 650, '四', '客戶服務與專業操守', '42. 保險業 (持牌保險經紀公司的財務及其他要求)規則是因應下列哪項條款設定的？', '{"A":"標準代理合約","B":"承保商專業守則","C":"保險業條例","D":"保險代理管理守則"}'::jsonb, 'C', '以上規則是根據保險業條例而定'),
('p2', 651, '四', '客戶服務與專業操守', '43. 「佣金回贈」的意思是：', '{"A":"進行不適當行為，所以不可取得佣金","B":"在保單被取消的情況下退回佣金給客戶","C":"將自己佣金的部份給客戶，從而換取業務","D":"告訴保險人就某份保單，不收取任何佣金"}'::jsonb, 'C', '回佣的意思是指，保險中介人把自己的佣金的一部分回贈給自身的客戶，因此為後者爭取「較便宜」的保費。'),
('p2', 652, '四', '客戶服務與專業操守', '44. 如果為了爭取業務，保險中介人提出向一名客戶分享本身的佣金。這種做法稱為：', '{"A":"曲解","B":"收受及支付回佣","C":"保費折扣","D":"佣金代償"}'::jsonb, 'B', '回佣的意思是指，保險中介人把自己的佣金的一部分回贈給自身的客戶，因此為後者爭取「較便宜」的保費。'),
('p2', 653, '四', '客戶服務與專業操守', '45. 利用佣金利誘以增加生產力及作生意的招徠是一件極嚴重的事情。以下哪項描述是正確的？
i. 破壞中介人的評級
ii. 屬於違反代理合約的理由
iii. 在保險業條例中是不合法的
iv. 做法近乎賄賂及貪污', '{"A":"i, ii, iii","B":"i, ii, iv","C":"ii, iii, iv","D":"以上所有各項"}'::jsonb, 'D', '回佣不但影響保險中介人，更令保險公司的形象受損。'),
('p2', 654, '四', '客戶服務與專業操守', '46. 代理人把部份佣金回贈予本身客戶，此行為稱為:', '{"A":"回佣","B":"利誘","C":"曲解","D":"保費優惠"}'::jsonb, 'A', '回佣的意思是指，保險中介人把自己的佣金的一部分回贈給自身的客戶，因此為後者爭取「較便宜」的保費。');
